-- N5-1: コンビニでの買い物
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'コンビニでの買い物',
  '店員：いらっしゃいませ。\n田中：すみません、おにぎりはどこですか。\n店員：おにぎりはあちらの棚にあります。\n田中：ありがとうございます。これと、お茶をください。\n店員：はい、おにぎり一つとお茶一つですね。全部で三百二十円です。\n田中：千円でお願いします。\n店員：六百八十円のおつりです。レジ袋はいりますか。\n田中：いいえ、大丈夫です。ありがとうございます。',
  'dialogue',
  'N5',
  ARRAY['店員', '田中'],
  'コンビニでおにぎりとお茶を買う場面',
  '[{"word":"棚","reading":"たな","meaning_ko":"선반"},{"word":"全部","reading":"ぜんぶ","meaning_ko":"전부"},{"word":"おつり","reading":"おつり","meaning_ko":"거스름돈"},{"word":"レジ袋","reading":"レジぶくろ","meaning_ko":"비닐봉지"},{"word":"大丈夫","reading":"だいじょうぶ","meaning_ko":"괜찮다"}]'::jsonb,
  '점원: 어서 오세요.\n다나카: 저기요, 주먹밥은 어디에 있나요?\n점원: 주먹밥은 저쪽 선반에 있습니다.\n다나카: 감사합니다. 이것과 차 주세요.\n점원: 네, 주먹밥 하나와 차 하나요. 전부 320엔입니다.\n다나카: 천 엔으로 부탁합니다.\n점원: 680엔 거스름돈입니다. 비닐봉지 필요하세요?\n다나카: 아니요, 괜찮습니다. 감사합니다.',
  1
);

-- N5-2: 駅で道を聞く
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '駅で道を聞く',
  '山田：すみません、図書館はどこですか。\n鈴木：図書館ですか。ここからまっすぐ行ってください。\n山田：まっすぐですか。\n鈴木：はい、まっすぐ行って、二つ目の信号を右に曲がってください。\n山田：二つ目の信号を右ですね。\n鈴木：そうです。右に曲がったら、左側にあります。\n山田：歩いてどのくらいかかりますか。\n鈴木：十分くらいですよ。\n山田：ありがとうございます。',
  'dialogue',
  'N5',
  ARRAY['山田', '鈴木'],
  '駅の近くで図書館への道を聞く場面',
  '[{"word":"図書館","reading":"としょかん","meaning_ko":"도서관"},{"word":"まっすぐ","reading":"まっすぐ","meaning_ko":"곧장"},{"word":"信号","reading":"しんごう","meaning_ko":"신호등"},{"word":"曲がる","reading":"まがる","meaning_ko":"돌다"},{"word":"左側","reading":"ひだりがわ","meaning_ko":"왼쪽"},{"word":"歩いて","reading":"あるいて","meaning_ko":"걸어서"}]'::jsonb,
  '야마다: 저기요, 도서관은 어디에 있나요?\n스즈키: 도서관이요? 여기서 곧장 가세요.\n야마다: 곧장이요?\n스즈키: 네, 곧장 가서 두 번째 신호등에서 오른쪽으로 도세요.\n야마다: 두 번째 신호등에서 오른쪽이요.\n스즈키: 맞아요. 오른쪽으로 돌면 왼쪽에 있습니다.\n야마다: 걸어서 얼마나 걸리나요?\n스즈키: 10분 정도예요.\n야마다: 감사합니다.',
  2
);

-- N5-3: レストランで注文
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'レストランで注文',
  '店員：いらっしゃいませ。何名様ですか。\n佐藤：二人です。\n店員：こちらの席にどうぞ。メニューです。\n佐藤：ありがとうございます。\n高橋：何にする？\n佐藤：私はカレーライスにする。高橋さんは？\n高橋：私はラーメンにします。\n店員：ご注文はお決まりですか。\n佐藤：カレーライス一つとラーメン一つ、お願いします。\n店員：お飲み物はいかがですか。\n高橋：水をください。\n店員：かしこまりました。少々お待ちください。',
  'dialogue',
  'N5',
  ARRAY['店員', '佐藤', '高橋'],
  'レストランで二人で食事を注文する場面',
  '[{"word":"何名様","reading":"なんめいさま","meaning_ko":"몇 분"},{"word":"席","reading":"せき","meaning_ko":"좌석"},{"word":"注文","reading":"ちゅうもん","meaning_ko":"주문"},{"word":"飲み物","reading":"のみもの","meaning_ko":"음료"},{"word":"かしこまりました","reading":"かしこまりました","meaning_ko":"알겠습니다(정중)"}]'::jsonb,
  '점원: 어서 오세요. 몇 분이세요?\n사토: 두 명이요.\n점원: 이쪽 자리로 앉으세요. 메뉴입니다.\n사토: 감사합니다.\n다카하시: 뭐로 할래?\n사토: 나는 카레라이스로 할게. 다카하시 씨는?\n다카하시: 저는 라멘으로 하겠습니다.\n점원: 주문하시겠어요?\n사토: 카레라이스 하나와 라멘 하나 부탁합니다.\n점원: 음료는 어떻게 하시겠어요?\n다카하시: 물 주세요.\n점원: 알겠습니다. 잠시만 기다려 주세요.',
  3
);

-- N5-4: 友達との電話
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '友達との電話',
  '山田：もしもし、鈴木さん？\n鈴木：あ、山田さん、こんにちは。\n山田：土曜日、ひまですか。\n鈴木：土曜日？うん、ひまだよ。\n山田：じゃあ、一緒に公園に行きませんか。\n鈴木：いいね！何時に会う？\n山田：十時はどうですか。\n鈴木：十時はちょっと早いな。十一時はどう？\n山田：十一時、いいですよ。駅の前で会いましょう。\n鈴木：分かった。楽しみだね。じゃあ、また土曜日に。\n山田：うん、じゃあね。',
  'dialogue',
  'N5',
  ARRAY['山田', '鈴木'],
  '友達に電話して週末の予定を相談する場面',
  '[{"word":"ひま","reading":"ひま","meaning_ko":"한가하다"},{"word":"一緒に","reading":"いっしょに","meaning_ko":"함께"},{"word":"公園","reading":"こうえん","meaning_ko":"공원"},{"word":"早い","reading":"はやい","meaning_ko":"이르다"},{"word":"楽しみ","reading":"たのしみ","meaning_ko":"기대"}]'::jsonb,
  '야마다: 여보세요, 스즈키 씨?\n스즈키: 아, 야마다 씨, 안녕하세요.\n야마다: 토요일에 시간 있어요?\n스즈키: 토요일? 응, 한가해.\n야마다: 그럼 같이 공원에 가지 않을래요?\n스즈키: 좋아! 몇 시에 만날까?\n야마다: 10시는 어때요?\n스즈키: 10시는 좀 이른데. 11시는 어때?\n야마다: 11시 좋아요. 역 앞에서 만나요.\n스즈키: 알았어. 기대된다. 그럼 토요일에.\n야마다: 응, 그럼.',
  4
);

-- N5-5: 天気のお知らせ
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '天気のお知らせ',
  'アナウンサー：天気のお知らせです。今日の東京の天気は晴れです。気温は二十五度です。明日は曇りで、午後から雨が降るでしょう。傘を持って出かけてください。週末は晴れて、暑くなります。水をたくさん飲んでください。以上、天気のお知らせでした。',
  'announcement',
  'N5',
  ARRAY['アナウンサー'],
  'テレビの天気予報のお知らせ',
  '[{"word":"晴れ","reading":"はれ","meaning_ko":"맑음"},{"word":"気温","reading":"きおん","meaning_ko":"기온"},{"word":"曇り","reading":"くもり","meaning_ko":"흐림"},{"word":"傘","reading":"かさ","meaning_ko":"우산"},{"word":"暑い","reading":"あつい","meaning_ko":"덥다"}]'::jsonb,
  '아나운서: 날씨 안내입니다. 오늘 도쿄의 날씨는 맑음입니다. 기온은 25도입니다. 내일은 흐리고 오후부터 비가 올 것입니다. 우산을 가지고 나가세요. 주말은 맑고 더워질 것입니다. 물을 많이 마시세요. 이상 날씨 안내였습니다.',
  5
);

-- ============================================
-- N4 Scripts (sort_order 6-10)
-- ============================================

-- N4-1: 病院での受診
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '病院での受診',
  '受付：おはようございます。保険証をお願いします。\n田中：はい、これです。\n受付：田中さんですね。今日はどうされましたか。\n田中：三日前から頭が痛くて、熱もあるんです。\n受付：そうですか。少しお待ちください。\n医者：田中さん、どうぞお入りください。いつから具合が悪いですか。\n田中：三日前からです。頭が痛くて、咳も出ます。\n医者：熱を測りましょう。三十八度二分ですね。のどを見せてください。\n田中：はい。\n医者：のどが赤いですね。風邪だと思います。薬を出しますから、三日分飲んでください。\n田中：分かりました。食事の前に飲みますか。\n医者：いいえ、食事の後に飲んでください。お大事に。',
  'dialogue',
  'N4',
  ARRAY['受付', '田中', '医者'],
  '病院で風邪の症状を医者に伝えて診察を受ける場面',
  '[{"word":"保険証","reading":"ほけんしょう","meaning_ko":"보험증"},{"word":"具合","reading":"ぐあい","meaning_ko":"상태, 컨디션"},{"word":"咳","reading":"せき","meaning_ko":"기침"},{"word":"のど","reading":"のど","meaning_ko":"목"},{"word":"風邪","reading":"かぜ","meaning_ko":"감기"},{"word":"薬","reading":"くすり","meaning_ko":"약"}]'::jsonb,
  '접수: 안녕하세요. 보험증 부탁드립니다.\n다나카: 네, 여기요.\n접수: 다나카 씨군요. 오늘은 어떻게 오셨나요?\n다나카: 3일 전부터 머리가 아프고 열도 있어요.\n접수: 그렇군요. 잠시만 기다려 주세요.\n의사: 다나카 씨, 들어오세요. 언제부터 상태가 안 좋으세요?\n다나카: 3일 전부터요. 머리가 아프고 기침도 나요.\n의사: 열을 재봅시다. 38도 2분이네요. 목을 보여주세요.\n다나카: 네.\n의사: 목이 빨갛네요. 감기인 것 같습니다. 약을 처방해 드릴 테니 3일분 드세요.\n다나카: 알겠습니다. 식사 전에 먹나요?\n의사: 아니요, 식사 후에 드세요. 몸조리 잘 하세요.',
  6
);

-- N4-2: 不動産屋でのアパート探し
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '不動産屋でのアパート探し',
  '店員：いらっしゃいませ。お部屋をお探しですか。\n佐藤：はい、一人暮らし用のアパートを探しています。\n店員：ご予算はどのくらいですか。\n佐藤：月六万円ぐらいがいいです。\n店員：駅からの距離はどうですか。\n佐藤：歩いて十分以内がいいんですが。\n店員：この物件はいかがですか。駅から歩いて七分で、家賃は五万八千円です。\n佐藤：いいですね。部屋の広さはどのくらいですか。\n店員：ワンルームで、二十平米です。バス・トイレ別です。\n佐藤：洗濯機は置けますか。\n店員：はい、ベランダに洗濯機置き場があります。\n佐藤：いいですね。一度見に行ってもいいですか。\n店員：もちろんです。今週の土曜日はいかがですか。',
  'dialogue',
  'N4',
  ARRAY['店員', '佐藤'],
  '不動産屋でアパートの条件を相談し、物件を探す場面',
  '[{"word":"一人暮らし","reading":"ひとりぐらし","meaning_ko":"자취, 혼자 사는 것"},{"word":"予算","reading":"よさん","meaning_ko":"예산"},{"word":"物件","reading":"ぶっけん","meaning_ko":"매물"},{"word":"家賃","reading":"やちん","meaning_ko":"집세"},{"word":"平米","reading":"へいべい","meaning_ko":"평방미터"},{"word":"ベランダ","reading":"ベランダ","meaning_ko":"베란다"}]'::jsonb,
  '직원: 어서 오세요. 방을 찾고 계신가요?\n사토: 네, 혼자 살 아파트를 찾고 있어요.\n직원: 예산은 어느 정도인가요?\n사토: 월 6만 엔 정도가 좋겠어요.\n직원: 역에서의 거리는 어떤가요?\n사토: 걸어서 10분 이내가 좋은데요.\n직원: 이 매물은 어떠세요? 역에서 걸어서 7분이고, 월세는 5만 8천 엔입니다.\n사토: 좋네요. 방 크기는 어느 정도예요?\n직원: 원룸이고 20제곱미터입니다. 욕실과 화장실이 분리되어 있어요.\n사토: 세탁기는 놓을 수 있나요?\n직원: 네, 베란다에 세탁기 놓는 곳이 있습니다.\n사토: 좋네요. 한번 보러 가도 될까요?\n직원: 물론이죠. 이번 주 토요일은 어떠세요?',
  7
);

-- N4-3: 郵便局での手続き
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '郵便局での手続き',
  '高橋：すみません、この荷物を韓国に送りたいんですが。\n局員：韓国ですね。中身は何ですか。\n高橋：お菓子と本です。\n局員：重さを量りますね。二キロです。送り方は航空便と船便がありますが。\n高橋：航空便でお願いします。どのくらいかかりますか。\n局員：航空便ですと、三日から五日ぐらいで届きます。料金は二千五百円です。\n高橋：じゃあ、航空便でお願いします。\n局員：こちらの伝票に送り先の住所とお名前を書いてください。\n高橋：分かりました。ここでいいですか。\n局員：はい、大丈夫です。壊れやすい物はありますか。\n高橋：いいえ、ありません。\n局員：では、二千五百円になります。',
  'dialogue',
  'N4',
  ARRAY['高橋', '局員'],
  '郵便局で韓国に荷物を送る手続きをする場面',
  '[{"word":"荷物","reading":"にもつ","meaning_ko":"짐, 소포"},{"word":"中身","reading":"なかみ","meaning_ko":"내용물"},{"word":"航空便","reading":"こうくうびん","meaning_ko":"항공편"},{"word":"届く","reading":"とどく","meaning_ko":"도착하다"},{"word":"伝票","reading":"でんぴょう","meaning_ko":"전표, 송장"},{"word":"壊れやすい","reading":"こわれやすい","meaning_ko":"깨지기 쉬운"}]'::jsonb,
  '다카하시: 저기요, 이 소포를 한국에 보내고 싶은데요.\n직원: 한국이군요. 내용물은 뭔가요?\n다카하시: 과자와 책이에요.\n직원: 무게를 재볼게요. 2킬로그램이네요. 배송 방법은 항공편과 선편이 있는데요.\n다카하시: 항공편으로 부탁합니다. 얼마나 걸리나요?\n직원: 항공편이면 3일에서 5일 정도에 도착합니다. 요금은 2,500엔입니다.\n다카하시: 그럼 항공편으로 부탁합니다.\n직원: 이 전표에 보내실 곳의 주소와 이름을 적어주세요.\n다카하시: 알겠습니다. 여기에 쓰면 되나요?\n직원: 네, 괜찮습니다. 깨지기 쉬운 물건이 있나요?\n다카하시: 아니요, 없습니다.\n직원: 그러면 2,500엔입니다.',
  8
);

-- N4-4: バスの案内放送
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'バスの案内放送',
  'アナウンス：ご乗車ありがとうございます。このバスは東京駅行きです。次は「中央公園前」です。中央公園、市立図書館にお越しの方はこちらでお降りください。お降りの際は、前のドアからお降りください。なお、本日は祝日ダイヤで運行しております。通常より本数が少なくなっておりますので、ご注意ください。次の「市役所前」は、降車ボタンでお知らせください。車内では携帯電話はマナーモードにしてください。ご協力をお願いいたします。',
  'announcement',
  'N4',
  ARRAY['アナウンス'],
  'バス車内での案内放送',
  '[{"word":"乗車","reading":"じょうしゃ","meaning_ko":"승차"},{"word":"お越し","reading":"おこし","meaning_ko":"오시는 것(경어)"},{"word":"祝日","reading":"しゅくじつ","meaning_ko":"공휴일"},{"word":"本数","reading":"ほんすう","meaning_ko":"운행 횟수"},{"word":"降車","reading":"こうしゃ","meaning_ko":"하차"},{"word":"携帯電話","reading":"けいたいでんわ","meaning_ko":"휴대전화"}]'::jsonb,
  '안내방송: 승차해 주셔서 감사합니다. 이 버스는 도쿄역 행입니다. 다음은 ''주오공원 앞''입니다. 주오공원, 시립도서관에 가시는 분은 여기서 내려주세요. 내리실 때는 앞문으로 내려주세요. 또한, 오늘은 공휴일 시간표로 운행하고 있습니다. 평소보다 운행 횟수가 적으니 주의해 주세요. 다음 ''시청 앞''은 하차 버튼으로 알려주세요. 차내에서는 휴대전화를 매너모드로 해주세요. 협조 부탁드립니다.',
  9
);

-- N4-5: 友人を旅行に誘う
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '友人を旅行に誘う',
  '山田：鈴木さん、来月の連休、どこか行かない？\n鈴木：いいね！どこに行きたい？\n山田：京都はどう？紅葉がきれいな時期だと思うんだけど。\n鈴木：京都いいね。でも、宿は取れるかな。\n山田：早めに予約すれば大丈夫だと思うよ。\n鈴木：交通手段はどうする？新幹線？\n山田：夜行バスのほうが安いよ。片道三千円ぐらいで行ける。\n鈴木：そんなに安いの？じゃあ、バスにしよう。\n山田：うん。一泊二日で、お寺とか回ろうよ。\n鈴木：いいね。抹茶のスイーツも食べたいな。\n山田：もちろん！じゃあ、詳しいことはまた連絡するね。\n鈴木：うん、楽しみにしてる！',
  'dialogue',
  'N4',
  ARRAY['山田', '鈴木'],
  '友人を京都旅行に誘い、計画を立てる場面',
  '[{"word":"連休","reading":"れんきゅう","meaning_ko":"연휴"},{"word":"紅葉","reading":"こうよう","meaning_ko":"단풍"},{"word":"宿","reading":"やど","meaning_ko":"숙소"},{"word":"夜行バス","reading":"やこうバス","meaning_ko":"야간버스"},{"word":"片道","reading":"かたみち","meaning_ko":"편도"},{"word":"一泊二日","reading":"いっぱくふつか","meaning_ko":"1박 2일"}]'::jsonb,
  '야마다: 스즈키 씨, 다음 달 연휴에 어디 안 갈래?\n스즈키: 좋아! 어디 가고 싶어?\n야마다: 교토는 어때? 단풍이 예쁜 시기일 거야.\n스즈키: 교토 좋다. 그런데 숙소 잡을 수 있을까?\n야마다: 일찍 예약하면 괜찮을 거야.\n스즈키: 교통수단은 어떻게 해? 신칸센?\n야마다: 야간버스가 더 싸. 편도 3천 엔 정도로 갈 수 있어.\n스즈키: 그렇게 싸? 그럼 버스로 하자.\n야마다: 응. 1박 2일로 절 같은 곳 돌아보자.\n스즈키: 좋다. 말차 디저트도 먹고 싶다.\n야마다: 물론! 그럼 자세한 건 다시 연락할게.\n스즈키: 응, 기대하고 있을게!',
  10
);

-- ============================================
-- N3 Scripts (sort_order 11-15)
-- ============================================

-- N3-1: 区役所での転入届
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '区役所での転入届',
  '窓口：いらっしゃいませ。どのようなご用件でしょうか。\n佐藤：先週、大阪から引っ越してきたので、転入届を出したいのですが。\n窓口：転入届ですね。前の住所の役所で転出届は出されましたか。\n佐藤：はい、転出証明書を持っています。\n窓口：ありがとうございます。では、こちらの用紙にご記入ください。新しい住所と、お名前、生年月日をお書きください。\n佐藤：はい。引っ越しの日付も書きますか。\n窓口：はい、実際に引っ越した日を書いてください。身分証明書はお持ちですか。\n佐藤：在留カードがあります。\n窓口：はい、結構です。在留カードの住所も変更が必要ですが、本日こちらで手続きできます。\n佐藤：ありがとうございます。住民票もすぐもらえますか。\n窓口：はい、手続きが終わりましたら、住民票を発行できます。一通三百円になります。\n佐藤：では、二通お願いします。\n窓口：かしこまりました。手続きに二十分ほどかかりますので、おかけになってお待ちください。\n佐藤：分かりました。よろしくお願いします。',
  'dialogue',
  'N3',
  ARRAY['窓口', '佐藤'],
  '区役所で転入届の手続きをする外国人の場面',
  '[{"word":"転入届","reading":"てんにゅうとどけ","meaning_ko":"전입신고"},{"word":"転出届","reading":"てんしゅつとどけ","meaning_ko":"전출신고"},{"word":"転出証明書","reading":"てんしゅつしょうめいしょ","meaning_ko":"전출증명서"},{"word":"在留カード","reading":"ざいりゅうカード","meaning_ko":"재류카드"},{"word":"住民票","reading":"じゅうみんひょう","meaning_ko":"주민표"},{"word":"発行","reading":"はっこう","meaning_ko":"발행"}]'::jsonb,
  '창구: 어서 오세요. 어떤 용건이신가요?\n사토: 지난주에 오사카에서 이사 왔는데, 전입신고를 하고 싶습니다.\n창구: 전입신고요. 이전 주소의 관청에서 전출신고는 하셨나요?\n사토: 네, 전출증명서를 가지고 있습니다.\n창구: 감사합니다. 그러면 이 용지에 기입해 주세요. 새 주소와 이름, 생년월일을 적어주세요.\n사토: 네. 이사 날짜도 쓰나요?\n창구: 네, 실제로 이사한 날을 적어주세요. 신분증은 가지고 계신가요?\n사토: 재류카드가 있습니다.\n창구: 네, 괜찮습니다. 재류카드의 주소도 변경이 필요한데, 오늘 여기서 수속할 수 있습니다.\n사토: 감사합니다. 주민표도 바로 받을 수 있나요?\n창구: 네, 수속이 끝나면 주민표를 발행할 수 있습니다. 한 통에 300엔입니다.\n사토: 그럼 두 통 부탁합니다.\n창구: 알겠습니다. 수속에 20분 정도 걸리니 앉아서 기다려 주세요.\n사토: 알겠습니다. 잘 부탁드립니다.',
  11
);

-- N3-2: 近所トラブルの相談
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '近所トラブルの相談',
  '管理人：はい、マンション管理事務所です。\n高橋：あの、三〇二号室の高橋です。ちょっとご相談があるのですが。\n管理人：高橋さん、どうされましたか。\n高橋：実は、上の階の方の足音がかなり気になっていまして。特に夜の十時過ぎに大きな音がするんです。\n管理人：それはお困りでしょうね。いつ頃からですか。\n高橋：先月から新しい方が越してきてからです。毎晩ではないんですが、週に三、四回くらいあります。\n管理人：分かりました。まず、全体のお知らせとして、夜間の騒音に関する注意書きを掲示板に貼りますね。\n高橋：直接言ったほうがいいでしょうか。\n管理人：最初は管理事務所から全体のお知らせという形が良いかと思います。それでも改善されない場合は、個別に対応いたします。\n高橋：分かりました。それでお願いします。\n管理人：何かあればまたいつでもご連絡ください。\n高橋：ありがとうございます。よろしくお願いします。',
  'phone_call',
  'N3',
  ARRAY['管理人', '高橋'],
  'マンション管理事務所に上階の騒音について電話で相談する場面',
  '[{"word":"管理人","reading":"かんりにん","meaning_ko":"관리인"},{"word":"足音","reading":"あしおと","meaning_ko":"발소리"},{"word":"騒音","reading":"そうおん","meaning_ko":"소음"},{"word":"掲示板","reading":"けいじばん","meaning_ko":"게시판"},{"word":"改善","reading":"かいぜん","meaning_ko":"개선"},{"word":"個別","reading":"こべつ","meaning_ko":"개별"}]'::jsonb,
  '관리인: 네, 맨션 관리사무소입니다.\n다카하시: 저, 302호실 다카하시입니다. 좀 상담할 게 있는데요.\n관리인: 다카하시 씨, 무슨 일이세요?\n다카하시: 사실, 윗층 분의 발소리가 꽤 신경 쓰여서요. 특히 밤 10시가 넘으면 큰 소리가 나요.\n관리인: 그건 곤란하시겠네요. 언제부터인가요?\n다카하시: 지난달에 새로운 분이 이사 오신 이후로요. 매일 밤은 아닌데 일주일에 서너 번 정도 있어요.\n관리인: 알겠습니다. 우선 전체 공지로 야간 소음에 관한 주의사항을 게시판에 붙이겠습니다.\n다카하시: 직접 말하는 게 좋을까요?\n관리인: 처음에는 관리사무소에서 전체 공지 형식이 좋을 것 같습니다. 그래도 개선되지 않으면 개별적으로 대응하겠습니다.\n다카하시: 알겠습니다. 그렇게 부탁합니다.\n관리인: 무슨 일이 있으면 언제든지 연락주세요.\n다카하시: 감사합니다. 잘 부탁드립니다.',
  12
);

-- N3-3: お祭りの案内放送
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'お祭りの案内放送',
  'アナウンス：皆さま、本日は第三十五回さくら祭りにお越しいただき、ありがとうございます。本日のスケジュールをご案内いたします。午前十時から正午まで、中央広場で和太鼓の演奏が行われます。午後一時からは、盆踊り大会を開催いたします。どなたでもご参加いただけます。また、会場の北側には屋台が並んでおりまして、焼きそば、たこ焼き、かき氷などをお楽しみいただけます。お子様向けには、南側の広場で金魚すくいや輪投げなどのゲームをご用意しております。なお、会場内は全面禁煙となっております。ゴミは所定のゴミ箱にお捨てください。花火大会は午後七時半から約三十分間行います。皆さま、最後までお楽しみください。',
  'announcement',
  'N3',
  ARRAY['アナウンス'],
  '地域のさくら祭りでの案内放送',
  '[{"word":"和太鼓","reading":"わだいこ","meaning_ko":"일본 북"},{"word":"盆踊り","reading":"ぼんおどり","meaning_ko":"봉오도리(일본 전통 춤)"},{"word":"屋台","reading":"やたい","meaning_ko":"포장마차"},{"word":"金魚すくい","reading":"きんぎょすくい","meaning_ko":"금붕어 잡기"},{"word":"全面禁煙","reading":"ぜんめんきんえん","meaning_ko":"전면 금연"},{"word":"花火大会","reading":"はなびたいかい","meaning_ko":"불꽃놀이 대회"}]'::jsonb,
  '안내방송: 여러분, 오늘 제35회 사쿠라 축제에 와주셔서 감사합니다. 오늘 일정을 안내해 드리겠습니다. 오전 10시부터 정오까지 중앙 광장에서 일본 북 연주가 있습니다. 오후 1시부터는 봉오도리 대회를 개최합니다. 누구나 참가하실 수 있습니다. 또한, 회장 북쪽에는 포장마차가 늘어서 있으며, 야키소바, 타코야키, 빙수 등을 즐기실 수 있습니다. 어린이들을 위해 남쪽 광장에서 금붕어 잡기와 고리 던지기 등의 게임을 준비하고 있습니다. 참고로 회장 내는 전면 금연입니다. 쓰레기는 지정된 쓰레기통에 버려주세요. 불꽃놀이 대회는 오후 7시 30분부터 약 30분간 진행됩니다. 여러분, 끝까지 즐겨주세요.',
  13
);

-- N3-4: 日本語教室での会話
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本語教室での会話',
  '先生：皆さん、今日は敬語の練習をしましょう。まず、尊敬語と謙譲語の違いを復習します。\nキム：先生、質問があります。「おっしゃる」と「申す」はどう使い分けますか。\n先生：いい質問ですね。「おっしゃる」は相手の動作に使う尊敬語で、「申す」は自分の動作に使う謙譲語です。例えば、「先生がおっしゃったこと」と「私が申したいこと」のように使います。\nキム：なるほど。日常生活ではどのくらい使いますか。\n先生：お店の店員さんとか、病院で話すときによく使いますよ。\nリン：先生、尊敬語と丁寧語はどう違いますか。\n先生：丁寧語は「です」「ます」のことで、誰に対しても使えます。尊敬語は相手を高める表現です。\nリン：じゃあ、友達には使わないほうがいいですか。\n先生：そうですね。友達に使うと距離を感じさせてしまいます。では、実際に練習してみましょう。ペアになってください。\nキム：はい。\n先生：一人がお客様役、もう一人が店員役です。自然な敬語で会話してみてください。',
  'dialogue',
  'N3',
  ARRAY['先生', 'キム', 'リン'],
  '日本語教室で敬語について学ぶ外国人学生と先生の会話',
  '[{"word":"敬語","reading":"けいご","meaning_ko":"경어"},{"word":"尊敬語","reading":"そんけいご","meaning_ko":"존경어"},{"word":"謙譲語","reading":"けんじょうご","meaning_ko":"겸양어"},{"word":"丁寧語","reading":"ていねいご","meaning_ko":"정중어"},{"word":"使い分ける","reading":"つかいわける","meaning_ko":"구분해서 사용하다"},{"word":"距離","reading":"きょり","meaning_ko":"거리"}]'::jsonb,
  '선생님: 여러분, 오늘은 경어 연습을 합시다. 우선 존경어와 겸양어의 차이를 복습합니다.\n김: 선생님, 질문이 있습니다. "おっしゃる"와 "申す"는 어떻게 구분해서 사용하나요?\n선생님: 좋은 질문이네요. "おっしゃる"는 상대방의 동작에 쓰는 존경어이고, "申す"는 자신의 동작에 쓰는 겸양어입니다. 예를 들어, "선생님이 말씀하신 것"과 "제가 말씀드리고 싶은 것"처럼 사용합니다.\n김: 그렇군요. 일상생활에서는 얼마나 사용하나요?\n선생님: 가게 점원이나 병원에서 이야기할 때 자주 사용해요.\n린: 선생님, 존경어와 정중어는 어떻게 다른가요?\n선생님: 정중어는 "です" "ます"를 말하는 것으로, 누구에게나 사용할 수 있어요. 존경어는 상대방을 높이는 표현입니다.\n린: 그럼 친구에게는 안 쓰는 게 좋나요?\n선생님: 맞아요. 친구에게 쓰면 거리감을 느끼게 합니다. 그러면 실제로 연습해 봅시다. 짝을 지어주세요.\n김: 네.\n선생님: 한 명이 손님 역, 다른 한 명이 점원 역입니다. 자연스러운 경어로 대화해 보세요.',
  14
);

-- N3-5: 災害時の避難案内
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '災害時の避難案内',
  'アナウンス：緊急のお知らせです。ただいま、この地域に大雨警報が発令されました。河川の水位が上昇しておりますので、川の近くにお住まいの方は十分にご注意ください。避難所は三か所開設されています。第一避難所は中央小学校、第二避難所は北区公民館、第三避難所は東体育館です。避難される方は、貴重品と水、食料を持って、落ち着いて行動してください。外が暗い場合は、懐中電灯をお持ちください。自動車での避難は道路が混雑する原因となりますので、できるだけ徒歩でお願いいたします。最新の情報は市の防災メールまたはラジオでご確認ください。皆さまの安全を第一にお考えください。繰り返します。この地域に大雨警報が発令されました。',
  'announcement',
  'N3',
  ARRAY['アナウンス'],
  '大雨警報発令時の地域防災放送',
  '[{"word":"警報","reading":"けいほう","meaning_ko":"경보"},{"word":"河川","reading":"かせん","meaning_ko":"하천"},{"word":"水位","reading":"すいい","meaning_ko":"수위"},{"word":"避難所","reading":"ひなんじょ","meaning_ko":"대피소"},{"word":"懐中電灯","reading":"かいちゅうでんとう","meaning_ko":"손전등"},{"word":"防災","reading":"ぼうさい","meaning_ko":"방재"}]'::jsonb,
  '안내방송: 긴급 안내입니다. 현재 이 지역에 호우경보가 발령되었습니다. 하천의 수위가 상승하고 있으니, 강 근처에 거주하시는 분들은 충분히 주의해 주세요. 대피소는 3곳이 개설되어 있습니다. 제1 대피소는 중앙초등학교, 제2 대피소는 북구 공민관, 제3 대피소는 동체육관입니다. 대피하시는 분은 귀중품과 물, 식량을 가지고 침착하게 행동해 주세요. 밖이 어두운 경우에는 손전등을 가져가세요. 자동차로 대피하시면 도로가 혼잡해지는 원인이 되니, 가능하면 도보로 부탁드립니다. 최신 정보는 시의 방재 메일 또는 라디오로 확인해 주세요. 여러분의 안전을 최우선으로 생각해 주세요. 반복합니다. 이 지역에 호우경보가 발령되었습니다.',
  15
);

-- ============================================
-- N2 Scripts (sort_order 16-20)
-- ============================================

-- N2-1: 市民講座の申し込み
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '市民講座の申し込み',
  '受付：はい、市民文化センターでございます。\n山田：あの、市民講座について問い合わせたいのですが。\n受付：はい、どのような講座をお探しでしょうか。\n山田：料理教室に興味がありまして。来月開講する講座はありますか。\n受付：来月ですと、「はじめての和食」と「家庭でできるイタリアン」の二講座がございます。\n山田：「はじめての和食」について詳しく教えていただけますか。\n受付：はい。毎週水曜日の午前十時から十二時まで、全八回のコースです。定員は十五名で、受講料は材料費込みで一万二千円になります。\n山田：申し込みはどのようにすればよろしいですか。\n受付：窓口での直接申し込みか、ホームページからのオンライン申し込みが可能です。なお、申し込み締め切りは今月の二十五日となっております。\n山田：定員にまだ空きはありますか。\n受付：現在のところ、まだ五名ほど空きがございます。\n山田：分かりました。持ち物は何か必要ですか。\n受付：エプロンと三角巾をご持参ください。調理器具と食材はこちらでご用意いたします。\n山田：ありがとうございます。では、オンラインで申し込ませていただきます。\n受付：はい、お待ちしております。ご不明な点がございましたら、いつでもお電話ください。',
  'phone_call',
  'N2',
  ARRAY['受付', '山田'],
  '市民文化センターに料理教室の講座について電話で問い合わせる場面',
  '[{"word":"開講","reading":"かいこう","meaning_ko":"개강"},{"word":"定員","reading":"ていいん","meaning_ko":"정원"},{"word":"受講料","reading":"じゅこうりょう","meaning_ko":"수강료"},{"word":"締め切り","reading":"しめきり","meaning_ko":"마감"},{"word":"三角巾","reading":"さんかくきん","meaning_ko":"삼각두건"},{"word":"調理器具","reading":"ちょうりきぐ","meaning_ko":"조리기구"}]'::jsonb,
  '접수: 네, 시민문화센터입니다.\n야마다: 저기, 시민강좌에 대해 문의하고 싶은데요.\n접수: 네, 어떤 강좌를 찾고 계신가요?\n야마다: 요리교실에 관심이 있는데요. 다음 달에 개강하는 강좌가 있나요?\n접수: 다음 달이면 "처음 시작하는 일식"과 "가정에서 만드는 이탈리안" 두 강좌가 있습니다.\n야마다: "처음 시작하는 일식"에 대해 자세히 알려주실 수 있나요?\n접수: 네. 매주 수요일 오전 10시부터 12시까지, 총 8회 코스입니다. 정원은 15명이고, 수강료는 재료비 포함 12,000엔입니다.\n야마다: 신청은 어떻게 하면 되나요?\n접수: 창구에서 직접 신청하시거나, 홈페이지에서 온라인 신청이 가능합니다. 참고로 신청 마감은 이달 25일입니다.\n야마다: 정원에 아직 자리가 있나요?\n접수: 현재로서는 아직 5명 정도 여유가 있습니다.\n야마다: 알겠습니다. 준비물은 뭐가 필요한가요?\n접수: 앞치마와 삼각두건을 지참해 주세요. 조리기구와 식재료는 저희 쪽에서 준비합니다.\n야마다: 감사합니다. 그럼 온라인으로 신청하겠습니다.\n접수: 네, 기다리고 있겠습니다. 불명확한 점이 있으시면 언제든지 전화해 주세요.',
  16
);

-- N2-2: 医師と患者の診察会話
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '医師と患者の診察会話',
  '医師：田中さん、先日の血液検査の結果が出ましたので、お伝えしますね。\n田中：はい、よろしくお願いします。\n医師：全体的に大きな問題はありませんが、コレステロール値がやや高めです。前回と比べると少し上がっています。\n田中：そうですか。何か生活で気をつけることはありますか。\n医師：まず、食生活の見直しが大切です。揚げ物や脂っこい食事を控えて、野菜を多く摂るようにしてください。\n田中：運動もしたほうがいいですか。\n医師：はい、ぜひ。毎日三十分程度のウォーキングをおすすめします。急に激しい運動をする必要はありませんが、継続的に体を動かすことが重要です。\n田中：分かりました。お酒はどうですか。\n医師：完全にやめる必要はありませんが、量を減らしてください。週に二日は休肝日を設けましょう。\n田中：薬は必要ですか。\n医師：今のところ、薬を出すほどではありません。まずは生活習慣の改善で様子を見ましょう。三か月後にもう一度検査をしますので、それまでに改善が見られなければ、その時に薬の処方を検討します。\n田中：分かりました。食事と運動、気をつけます。\n医師：あまり無理をせず、できることから始めてくださいね。次回は四月十五日でいかがですか。\n田中：はい、大丈夫です。ありがとうございました。',
  'dialogue',
  'N2',
  ARRAY['医師', '田中'],
  '健康診断の結果を踏まえて医師が生活改善を指導する場面',
  '[{"word":"血液検査","reading":"けつえきけんさ","meaning_ko":"혈액검사"},{"word":"コレステロール値","reading":"コレステロールち","meaning_ko":"콜레스테롤 수치"},{"word":"揚げ物","reading":"あげもの","meaning_ko":"튀김"},{"word":"継続的","reading":"けいぞくてき","meaning_ko":"지속적"},{"word":"休肝日","reading":"きゅうかんび","meaning_ko":"금주일"},{"word":"処方","reading":"しょほう","meaning_ko":"처방"}]'::jsonb,
  '의사: 다나카 씨, 며칠 전 혈액검사 결과가 나왔으니 알려드리겠습니다.\n다나카: 네, 부탁합니다.\n의사: 전체적으로 큰 문제는 없지만, 콜레스테롤 수치가 약간 높습니다. 전회와 비교하면 조금 올라갔어요.\n다나카: 그런가요. 생활에서 주의할 점이 있나요?\n의사: 우선 식생활 개선이 중요합니다. 튀김이나 기름진 식사를 줄이고, 채소를 많이 섭취하도록 해주세요.\n다나카: 운동도 하는 게 좋을까요?\n의사: 네, 꼭 하세요. 매일 30분 정도 걷기를 권장합니다. 갑자기 격렬한 운동을 할 필요는 없지만, 지속적으로 몸을 움직이는 것이 중요합니다.\n다나카: 알겠습니다. 술은 어떤가요?\n의사: 완전히 끊을 필요는 없지만, 양을 줄여주세요. 일주일에 이틀은 금주일을 만드세요.\n다나카: 약이 필요한가요?\n의사: 지금 당장은 약을 처방할 정도는 아닙니다. 우선 생활습관 개선으로 경과를 봅시다. 3개월 후에 다시 한번 검사를 하고, 그때까지 개선이 안 되면 그때 약 처방을 검토하겠습니다.\n다나카: 알겠습니다. 식사와 운동, 주의하겠습니다.\n의사: 너무 무리하지 마시고 할 수 있는 것부터 시작하세요. 다음은 4월 15일 어떠세요?\n다나카: 네, 괜찮습니다. 감사합니다.',
  17
);

-- N2-3: PTA会議での議論
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'PTA会議での議論',
  '会長：それでは、第三回PTA定例会議を始めます。本日の議題は、来月の運動会についてです。まず、日程の確認ですが、十月十二日の土曜日で変更はありませんね。\n副会長：はい、雨天の場合は翌日の十三日に延期ということで、学校側とも確認済みです。\n会長：ありがとうございます。次に、保護者のボランティアについてですが、現在何名集まっていますか。\n鈴木：現在、二十三名の申し出がありました。受付に五名、駐車場の誘導に四名、テント設営に六名、片付けに八名です。\n佐藤：すみません、救護班はどうなっていますか。看護師の資格を持っている方がいると安心なのですが。\n鈴木：救護班は学校の養護教諭が対応してくださいますが、補助として保護者の方にもお願いしたいと考えています。\n会長：では、次回までに救護班のボランティアも募集しましょう。それから、飲食の出店について何かご意見はありますか。\n佐藤：昨年はアレルギー対応が不十分だという声がありました。今年は各出店にアレルギー表示を義務付けてはどうでしょうか。\n副会長：賛成です。食品表示のテンプレートを作って配布するのがいいと思います。\n会長：では、そのように進めましょう。他にご質問やご意見はありますか。なければ、次回の会議は九月二十日に行います。本日はありがとうございました。',
  'meeting',
  'N2',
  ARRAY['会長', '副会長', '鈴木', '佐藤'],
  '小学校のPTA定例会議で運動会の準備を話し合う場面',
  '[{"word":"運動会","reading":"うんどうかい","meaning_ko":"운동회"},{"word":"雨天","reading":"うてん","meaning_ko":"우천"},{"word":"延期","reading":"えんき","meaning_ko":"연기"},{"word":"救護班","reading":"きゅうごはん","meaning_ko":"구호반"},{"word":"養護教諭","reading":"ようごきょうゆ","meaning_ko":"양호교사"},{"word":"アレルギー表示","reading":"アレルギーひょうじ","meaning_ko":"알레르기 표시"}]'::jsonb,
  '회장: 그러면 제3회 PTA 정례회의를 시작하겠습니다. 오늘의 의제는 다음 달 운동회에 대해서입니다. 우선 일정 확인인데, 10월 12일 토요일로 변경 없지요.\n부회장: 네, 우천 시에는 다음 날 13일로 연기하는 것으로 학교 측과도 확인 완료했습니다.\n회장: 감사합니다. 다음으로 학부모 봉사활동에 대해서인데, 현재 몇 명이 모였나요?\n스즈키: 현재 23명이 신청했습니다. 접수에 5명, 주차장 안내에 4명, 텐트 설치에 6명, 정리에 8명입니다.\n사토: 실례합니다만, 구호반은 어떻게 되어 있나요? 간호사 자격이 있는 분이 계시면 안심인데요.\n스즈키: 구호반은 학교 양호교사가 대응해 주시지만, 보조로 학부모 분께도 부탁하고 싶습니다.\n회장: 그러면 다음 회의까지 구호반 봉사자도 모집합시다. 그리고 음식 판매에 대해 의견이 있으신가요?\n사토: 작년에는 알레르기 대응이 불충분하다는 의견이 있었습니다. 올해는 각 판매점에 알레르기 표시를 의무화하는 것은 어떨까요?\n부회장: 찬성입니다. 식품 표시 템플릿을 만들어서 배포하는 게 좋겠습니다.\n회장: 그러면 그렇게 진행합시다. 다른 질문이나 의견이 있으신가요? 없으면 다음 회의는 9월 20일에 하겠습니다. 오늘 감사했습니다.',
  18
);

-- N2-4: 交通安全の講演
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '交通安全の講演',
  '講師：皆さん、こんにちは。本日は「身近な交通安全」というテーマでお話しさせていただきます。まず、昨年のこの地域の交通事故の統計をご覧ください。交通事故件数は前年より減少していますが、自転車に関する事故は逆に増加しています。特に、スマートフォンを見ながらの運転や、イヤホンをつけたままの走行が原因となるケースが目立ちます。自転車も車両の一種ですので、交通ルールを守る義務があります。具体的には、信号を守ること、一時停止の標識では必ず止まること、夜間は必ずライトを点灯すること、そして歩道ではなく車道の左側を走行することが基本です。また、最近は電動キックボードの事故も増えてきています。免許不要の区分であっても、ヘルメットの着用が推奨されています。お子さんがいらっしゃる方は、ぜひご家庭で交通安全について話し合ってみてください。小さなお子さんには、道路を渡るときは必ず手を挙げて、左右を確認してから渡るよう教えてあげてください。安全は一人一人の意識から始まります。ご清聴ありがとうございました。',
  'announcement',
  'N2',
  ARRAY['講師'],
  '地域の交通安全教室での講演',
  '[{"word":"統計","reading":"とうけい","meaning_ko":"통계"},{"word":"減少","reading":"げんしょう","meaning_ko":"감소"},{"word":"車両","reading":"しゃりょう","meaning_ko":"차량"},{"word":"一時停止","reading":"いちじていし","meaning_ko":"일시정지"},{"word":"点灯","reading":"てんとう","meaning_ko":"점등"},{"word":"着用","reading":"ちゃくよう","meaning_ko":"착용"}]'::jsonb,
  '강사: 여러분, 안녕하세요. 오늘은 "생활 속 교통안전"이라는 주제로 말씀드리겠습니다. 먼저, 작년 이 지역의 교통사고 통계를 보시겠습니다. 교통사고 건수는 전년보다 감소했지만, 자전거 관련 사고는 오히려 증가하고 있습니다. 특히 스마트폰을 보면서 운전하거나 이어폰을 끼고 주행하는 것이 원인이 되는 경우가 눈에 띕니다. 자전거도 차량의 일종이므로 교통 규칙을 지킬 의무가 있습니다. 구체적으로는 신호를 지키는 것, 일시정지 표지판에서는 반드시 멈추는 것, 야간에는 반드시 라이트를 켜는 것, 그리고 보도가 아닌 차도 왼쪽을 주행하는 것이 기본입니다. 또한 최근에는 전동 킥보드 사고도 늘어나고 있습니다. 면허 불요 구분이라 하더라도 헬멧 착용이 권장되고 있습니다. 자녀가 계신 분은 꼭 가정에서 교통안전에 대해 이야기해 보세요. 어린 자녀에게는 도로를 건널 때 반드시 손을 들고, 좌우를 확인한 후 건너도록 가르쳐 주세요. 안전은 한 사람 한 사람의 의식에서 시작됩니다. 경청해 주셔서 감사합니다.',
  19
);

-- N2-5: マンション管理組合の会合
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'マンション管理組合の会合',
  '理事長：それでは、マンション管理組合の臨時総会を開催いたします。本日の議題は、大規模修繕工事の実施計画についてです。\n副理事長：資料をお配りしましたので、ご確認ください。築二十年を迎えまして、外壁の塗装や防水工事が必要な時期となっております。\n住民A：工事費用はどの程度を見込んでいますか。\n理事長：見積もりを三社から取りまして、平均すると約三千万円になります。修繕積立金の残高は現在二千五百万円ですので、不足分は一時金として各戸にご負担いただく必要がございます。\n住民B：一戸あたりいくらになりますか。\n副理事長：全三十戸ですので、一戸あたり約十七万円のご負担となります。分割払いも検討しております。\n住民A：工事期間中はベランダが使えなくなるのでしょうか。\n理事長：足場を設置する関係で、各住戸のベランダが一週間から十日ほど使えなくなる期間がございます。洗濯物は室内に干していただくことになります。\n住民B：騒音はどの程度ですか。小さい子供がいるので心配です。\n副理事長：日中のみの作業で、土日は原則休工といたします。特に大きな騒音が出る作業の前には、事前にお知らせいたします。\n理事長：では、この計画について賛否をお聞きしたいと思います。賛成の方は挙手をお願いいたします。',
  'meeting',
  'N2',
  ARRAY['理事長', '副理事長', '住民A', '住民B'],
  'マンション管理組合の臨時総会で大規模修繕工事について話し合う場面',
  '[{"word":"大規模修繕","reading":"だいきぼしゅうぜん","meaning_ko":"대규모 수선"},{"word":"外壁","reading":"がいへき","meaning_ko":"외벽"},{"word":"修繕積立金","reading":"しゅうぜんつみたてきん","meaning_ko":"수선적립금"},{"word":"足場","reading":"あしば","meaning_ko":"비계, 발판"},{"word":"休工","reading":"きゅうこう","meaning_ko":"공사 중단"},{"word":"挙手","reading":"きょしゅ","meaning_ko":"거수"}]'::jsonb,
  '이사장: 그러면 맨션 관리조합 임시총회를 개최하겠습니다. 오늘의 의제는 대규모 수선공사 실시 계획에 대해서입니다.\n부이사장: 자료를 배포했으니 확인해 주세요. 건축 20년을 맞이하여, 외벽 도장이나 방수공사가 필요한 시기가 되었습니다.\n주민A: 공사 비용은 어느 정도 예상하고 있나요?\n이사장: 견적을 세 곳에서 받았는데, 평균 약 3,000만 엔입니다. 수선적립금 잔액은 현재 2,500만 엔이므로, 부족분은 일시금으로 각 세대에 부담해 주셔야 합니다.\n주민B: 세대당 얼마인가요?\n부이사장: 전체 30세대이므로, 세대당 약 17만 엔의 부담이 됩니다. 분할 납부도 검토하고 있습니다.\n주민A: 공사 기간 중에는 베란다를 사용할 수 없게 되나요?\n이사장: 비계를 설치하는 관계로, 각 세대 베란다를 1주일에서 열흘 정도 사용할 수 없는 기간이 있습니다. 빨래는 실내에서 말려주셔야 합니다.\n주민B: 소음은 어느 정도인가요? 어린 아이가 있어서 걱정됩니다.\n부이사장: 낮 시간에만 작업하고, 토일은 원칙적으로 공사를 중단합니다. 특히 큰 소음이 나는 작업 전에는 사전에 알려드리겠습니다.\n이사장: 그러면 이 계획에 대해 찬반을 묻고 싶습니다. 찬성하시는 분은 거수 부탁드립니다.',
  20
);

-- ============================================
-- N1 Scripts (sort_order 21-25)
-- ============================================

-- N1-1: 市長の施政方針演説
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '市長の施政方針演説',
  '市長：議員各位、並びに市民の皆さま、令和八年度の施政方針を申し述べます。当市は少子高齢化という構造的課題に直面しておりますが、これを危機ではなく変革の好機と捉え、持続可能なまちづくりを推進してまいります。第一に、子育て支援の抜本的強化です。待機児童ゼロの維持はもとより、第二子以降の保育料完全無償化を来年度から実施いたします。また、小中学校の給食費についても段階的に無償化し、子育て世帯の経済的負担を大幅に軽減いたします。第二に、高齢者福祉の充実です。地域包括ケアシステムをさらに拡充し、在宅医療と介護の連携を強化いたします。各地区に設置しております高齢者サロンを現在の十五か所から二十五か所に増設し、高齢者の社会参加と生きがいづくりを支援いたします。第三に、防災・減災対策の強化です。近年の気候変動による自然災害の激甚化を踏まえ、河川の堤防強化や排水設備の整備に重点的に予算を配分いたします。さらに、全市民を対象としたハザードマップの更新と防災訓練の拡充を図ります。これらの施策の財源については、行財政改革による歳出の見直しと、ふるさと納税の活用により確保してまいります。市民の皆さまのご理解とご協力を賜りますようお願い申し上げます。',
  'announcement',
  'N1',
  ARRAY['市長'],
  '市議会における市長の年度施政方針演説',
  '[{"word":"施政方針","reading":"しせいほうしん","meaning_ko":"시정방침"},{"word":"少子高齢化","reading":"しょうしこうれいか","meaning_ko":"저출산 고령화"},{"word":"待機児童","reading":"たいきじどう","meaning_ko":"대기아동"},{"word":"地域包括ケア","reading":"ちいきほうかつケア","meaning_ko":"지역포괄케어"},{"word":"激甚化","reading":"げきじんか","meaning_ko":"격심화"},{"word":"行財政改革","reading":"ぎょうざいせいかいかく","meaning_ko":"행재정 개혁"}]'::jsonb,
  '시장: 의원 여러분, 그리고 시민 여러분, 레이와 8년도 시정방침을 말씀드리겠습니다. 본 시는 저출산 고령화라는 구조적 과제에 직면해 있으나, 이를 위기가 아닌 변혁의 기회로 삼아 지속 가능한 도시 만들기를 추진해 나가겠습니다. 첫째, 육아 지원의 근본적 강화입니다. 대기아동 제로 유지는 물론이고, 둘째 자녀 이후의 보육료 완전 무상화를 내년도부터 실시하겠습니다. 또한 초중학교 급식비에 대해서도 단계적으로 무상화하여 육아 세대의 경제적 부담을 대폭 경감하겠습니다. 둘째, 고령자 복지의 충실입니다. 지역포괄케어시스템을 더욱 확충하고, 재택의료와 돌봄의 연계를 강화하겠습니다. 각 지구에 설치한 고령자 살롱을 현재 15곳에서 25곳으로 증설하여, 고령자의 사회참여와 보람 만들기를 지원하겠습니다. 셋째, 방재·감재 대책의 강화입니다. 최근 기후변동으로 인한 자연재해의 격심화를 감안하여, 하천 제방 강화와 배수 시설 정비에 중점적으로 예산을 배정하겠습니다. 나아가 전 시민을 대상으로 한 해저드맵 업데이트와 방재 훈련 확충을 도모하겠습니다. 이러한 시책의 재원에 대해서는 행재정 개혁을 통한 세출 재검토와 고향 납세 활용으로 확보해 나가겠습니다. 시민 여러분의 이해와 협조를 부탁드립니다.',
  21
);

-- N1-2: 文化交流シンポジウム
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '文化交流シンポジウム',
  '司会：本日は「多文化共生社会の実現に向けて」と題しまして、シンポジウムを開催いたします。まず、基調講演をお願いいたします。\n教授：ご紹介いただきました東京大学の山田です。日本における外国人住民の数は年々増加しており、多文化共生は避けて通れない社会課題となっています。しかし、共生という言葉が示すように、これは一方的な同化ではなく、相互理解と尊重に基づく関係の構築を意味します。\n司会：ありがとうございます。次に、パネリストの方々にお話しいただきます。\nパネリストA：私は地域の国際交流協会で活動しています。外国人住民の方々が最も困っているのは、やはり言葉の壁です。日本語教室を運営していますが、ボランティアの確保が課題です。また、災害時の多言語対応も急務となっています。\nパネリストB：教育の観点からお話しします。外国にルーツを持つ子どもたちの学習支援が不可欠です。日本語が十分でないために授業についていけず、不登校になるケースも少なくありません。母語教育の機会も保障すべきだと考えます。\n教授：お二人のご指摘は非常に重要です。制度的な整備に加えて、地域レベルでの草の根の交流こそが、真の共生社会を実現する鍵ではないでしょうか。お互いの文化を知り、日常的な接点を増やしていくことが、偏見や差別を克服する最も有効な手段だと確信しています。\n司会：貴重なご意見をありがとうございました。会場からのご質問を受け付けます。',
  'meeting',
  'N1',
  ARRAY['司会', '教授', 'パネリストA', 'パネリストB'],
  '多文化共生をテーマとした学術シンポジウム',
  '[{"word":"多文化共生","reading":"たぶんかきょうせい","meaning_ko":"다문화 공생"},{"word":"基調講演","reading":"きちょうこうえん","meaning_ko":"기조강연"},{"word":"同化","reading":"どうか","meaning_ko":"동화"},{"word":"急務","reading":"きゅうむ","meaning_ko":"급선무"},{"word":"不登校","reading":"ふとうこう","meaning_ko":"학교 부적응(미등교)"},{"word":"偏見","reading":"へんけん","meaning_ko":"편견"}]'::jsonb,
  '사회자: 오늘은 "다문화 공생 사회의 실현을 향하여"라는 주제로 심포지엄을 개최합니다. 먼저 기조강연을 부탁드리겠습니다.\n교수: 소개받은 도쿄대학의 야마다입니다. 일본에서의 외국인 주민 수는 해마다 증가하고 있으며, 다문화 공생은 피할 수 없는 사회적 과제가 되었습니다. 그러나 공생이라는 말이 보여주듯이, 이것은 일방적인 동화가 아니라 상호 이해와 존중에 기반한 관계 구축을 의미합니다.\n사회자: 감사합니다. 다음으로 패널리스트 분들에게 말씀을 듣겠습니다.\n패널리스트A: 저는 지역 국제교류협회에서 활동하고 있습니다. 외국인 주민들이 가장 곤란해하는 것은 역시 언어의 벽입니다. 일본어 교실을 운영하고 있지만 자원봉사자 확보가 과제입니다. 또한 재해 시 다국어 대응도 급선무가 되고 있습니다.\n패널리스트B: 교육 관점에서 말씀드리겠습니다. 외국에 뿌리를 둔 아이들의 학습 지원이 불가결합니다. 일본어가 충분하지 않아 수업을 따라가지 못하고, 미등교가 되는 경우도 적지 않습니다. 모국어 교육의 기회도 보장해야 한다고 생각합니다.\n교수: 두 분의 지적은 매우 중요합니다. 제도적 정비에 더하여, 지역 수준의 풀뿌리 교류야말로 진정한 공생 사회를 실현하는 열쇠가 아닐까요. 서로의 문화를 알고 일상적인 접점을 늘려가는 것이 편견과 차별을 극복하는 가장 유효한 수단이라고 확신합니다.\n사회자: 귀중한 의견 감사합니다. 회장에서의 질문을 받겠습니다.',
  22
);

-- N1-3: 地域活性化の座談会
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '地域活性化の座談会',
  '進行：本日は「人口減少時代における地域活性化」というテーマで座談会を行います。まず、田中さんから現状をお聞かせください。\n田中：当町の人口はこの二十年で三割減少しました。特に若年層の流出が深刻で、高校を卒業すると大半が都市部に出てしまいます。商店街もシャッター通りと化し、かつての賑わいは見る影もありません。\n山本：私は隣の村で農業を営んでいますが、後継者不足は切実な問題です。ただ、最近は都会からの移住者がわずかながら増えてきていまして、新規就農者の受け入れ体制を整えることで、地域に新しい風を吹き込めるのではないかと考えています。\n佐藤：観光の立場から申し上げますと、当地域にはまだ十分に活用されていない観光資源が数多くあります。温泉や伝統工芸、豊かな自然環境を組み合わせた体験型の滞在プログラムを開発することで、交流人口の拡大を図れるのではないでしょうか。\n田中：確かに、定住人口だけでなく関係人口という考え方も重要ですね。地域に関わる人を増やすことが、結果的に移住者の増加にもつながるかもしれません。\n山本：デジタル技術の活用も欠かせません。オンラインでの特産品販売や、リモートワーク環境の整備によって、場所に縛られない働き方を実現できれば、地方の可能性は広がります。\n進行：皆さんのおっしゃるように、一つの施策だけでなく、複合的なアプローチが求められているわけですね。行政としても、民間の創意工夫を後押しする柔軟な支援制度の構築が急がれます。\n佐藤：補助金に頼るだけでなく、地域自らが稼ぐ力をつけることが持続可能性の観点からも不可欠だと思います。\n田中：おっしゃる通りです。地域の課題を地域の強みに変えていく発想の転換こそが、これからの活性化の鍵になるでしょう。',
  'meeting',
  'N1',
  ARRAY['進行', '田中', '山本', '佐藤'],
  '地域の課題と活性化策について話し合う座談会',
  '[{"word":"過疎化","reading":"かそか","meaning_ko":"과소화"},{"word":"後継者","reading":"こうけいしゃ","meaning_ko":"후계자"},{"word":"関係人口","reading":"かんけいじんこう","meaning_ko":"관계인구"},{"word":"特産品","reading":"とくさんひん","meaning_ko":"특산품"},{"word":"創意工夫","reading":"そういくふう","meaning_ko":"창의적 궁리"},{"word":"発想の転換","reading":"はっそうのてんかん","meaning_ko":"발상의 전환"}]'::jsonb,
  '진행: 오늘은 "인구감소 시대의 지역 활성화"라는 주제로 좌담회를 진행합니다. 먼저 다나카 씨부터 현황을 말씀해 주세요.\n다나카: 우리 마을 인구는 지난 20년간 30% 감소했습니다. 특히 젊은 층의 유출이 심각해서, 고등학교를 졸업하면 대부분 도시로 나가버립니다. 상점가도 셔터 거리가 되어 예전의 활기는 흔적도 없습니다.\n야마모토: 저는 이웃 마을에서 농업을 하고 있는데, 후계자 부족은 절실한 문제입니다. 다만 최근에는 도시에서의 이주자가 조금씩 늘고 있어서, 신규 취농자 수용 체제를 갖추면 지역에 새바람을 불어넣을 수 있지 않을까 생각합니다.\n사토: 관광 입장에서 말씀드리면, 이 지역에는 아직 충분히 활용되지 않은 관광 자원이 많이 있습니다. 온천이나 전통 공예, 풍요로운 자연환경을 조합한 체험형 체재 프로그램을 개발하면 교류 인구 확대를 도모할 수 있지 않을까요.\n다나카: 확실히 정주 인구만이 아니라 관계인구라는 사고방식도 중요하네요. 지역에 관여하는 사람을 늘리는 것이 결과적으로 이주자 증가로도 이어질 수 있겠습니다.\n야마모토: 디지털 기술 활용도 빠뜨릴 수 없습니다. 온라인 특산품 판매나 원격근무 환경 정비를 통해 장소에 구애받지 않는 일하는 방식을 실현할 수 있다면, 지방의 가능성은 넓어집니다.\n진행: 여러분 말씀대로, 하나의 시책만이 아니라 복합적인 접근이 요구되고 있군요. 행정 측에서도 민간의 창의적 궁리를 뒷받침하는 유연한 지원 제도 구축이 시급합니다.\n사토: 보조금에만 의존하지 않고, 지역 스스로 수익을 낼 수 있는 힘을 기르는 것이 지속가능성 관점에서도 불가결하다고 생각합니다.\n다나카: 말씀하신 대로입니다. 지역의 과제를 지역의 강점으로 바꾸는 발상의 전환이야말로 앞으로의 활성화의 열쇠가 될 것입니다.',
  23
);

-- N1-4: 教育改革についての討論
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '教育改革についての討論',
  '司会：本日は「これからの教育のあるべき姿」について討論していただきます。まず、現在の教育の課題について、各パネリストの見解をお聞かせください。\n教授A：最大の課題は、画一的な教育から個別最適化された学びへの転換が進んでいないことです。子どもたちの学習速度や興味関心は多様であるにもかかわらず、一律の教科書、一律のペースで授業が進められています。\n教授B：私はむしろ、教育の本質的な目的が見失われていることを懸念しています。知識の暗記偏重から脱却できず、批判的思考力や創造性を育む教育が不十分です。変化の激しい時代において、自ら問いを立て、多角的に考える力こそが求められているはずです。\n保護者代表：現場の声として申し上げますと、教員の多忙化が子どもたちの教育の質に直接影響しています。教員が一人一人の子どもと向き合う時間が不足しています。部活動の指導や事務作業の負担を軽減しなければ、いくら理想を掲げても実現は困難です。\n教授A：おっしゃる通りです。教育改革は教員の働き方改革と表裏一体の関係にあります。また、地域格差の問題も看過できません。都市部と地方では、教育資源に大きな開きがあります。\n教授B：デジタル技術は地域格差を埋める有力な手段となり得ます。ただし、対面での対話やグループ活動を通じて培われる社会性やコミュニケーション能力は、デジタルでは代替できません。技術の活用と人間的な関わりのバランスが極めて重要です。\n司会：それぞれのお立場から貴重なご意見をいただきました。教育は社会の根幹を成すものであり、この議論を一過性のものとせず、継続的に対話を重ねていく必要がありますね。\n保護者代表：子どもたちの未来のために、理想論だけでなく、実行可能な具体策を早急に講じていただきたいと切に願っております。',
  'meeting',
  'N1',
  ARRAY['司会', '教授A', '教授B', '保護者代表'],
  '教育改革の方向性について専門家と保護者が討論するパネルディスカッション',
  '[{"word":"画一的","reading":"かくいつてき","meaning_ko":"획일적"},{"word":"暗記偏重","reading":"あんきへんちょう","meaning_ko":"암기 편중"},{"word":"批判的思考力","reading":"ひはんてきしこうりょく","meaning_ko":"비판적 사고력"},{"word":"表裏一体","reading":"ひょうりいったい","meaning_ko":"표리일체"},{"word":"看過","reading":"かんか","meaning_ko":"간과"},{"word":"一過性","reading":"いっかせい","meaning_ko":"일시적"}]'::jsonb,
  '사회자: 오늘은 "앞으로의 교육이 나아가야 할 방향"에 대해 토론해 주시겠습니다. 먼저 현재 교육의 과제에 대해 각 패널리스트의 견해를 들려주세요.\n교수A: 최대 과제는 획일적 교육에서 개별 최적화된 배움으로의 전환이 진행되지 않고 있다는 것입니다. 아이들의 학습 속도와 흥미 관심은 다양함에도 불구하고, 일률적인 교과서와 일률적인 속도로 수업이 진행되고 있습니다.\n교수B: 저는 오히려 교육의 본질적 목적이 상실되고 있는 것을 우려합니다. 지식 암기 편중에서 벗어나지 못하고, 비판적 사고력과 창의성을 기르는 교육이 불충분합니다. 변화가 격렬한 시대에 스스로 질문을 세우고 다각적으로 생각하는 힘이야말로 요구되는 것입니다.\n학부모 대표: 현장의 목소리로 말씀드리면, 교원의 과다 업무가 아이들의 교육 질에 직접 영향을 미치고 있습니다. 교원이 한 명 한 명의 아이와 마주할 시간이 부족합니다. 부활동 지도나 사무 작업의 부담을 줄이지 않으면, 아무리 이상을 내세워도 실현은 곤란합니다.\n교수A: 말씀하신 대로입니다. 교육 개혁은 교원의 근무 방식 개혁과 표리일체 관계에 있습니다. 또한 지역 격차 문제도 간과할 수 없습니다. 도시부와 지방에서는 교육 자원에 큰 차이가 있습니다.\n교수B: 디지털 기술은 지역 격차를 메우는 유력한 수단이 될 수 있습니다. 다만 대면 대화나 그룹 활동을 통해 길러지는 사회성과 커뮤니케이션 능력은 디지털로 대체할 수 없습니다. 기술 활용과 인간적 관계의 균형이 매우 중요합니다.\n사회자: 각각의 입장에서 귀중한 의견을 주셨습니다. 교육은 사회의 근간을 이루는 것이므로, 이 논의를 일회성으로 끝내지 않고 지속적으로 대화를 거듭해 나갈 필요가 있겠습니다.\n학부모 대표: 아이들의 미래를 위해 이상론만이 아닌 실행 가능한 구체적 대책을 조속히 마련해 주시기를 간절히 바랍니다.',
  24
);

-- N1-5: 環境保護NPOの活動報告
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '環境保護NPOの活動報告',
  '代表：皆さま、NPO法人「緑の地球を守る会」の年次活動報告をいたします。本年度は三つの重点事業に取り組んでまいりました。第一の事業は、里山再生プロジェクトです。荒廃していた市内五か所の里山において、地域住民とボランティアの協力のもと、間伐作業や植樹活動を実施しました。延べ参加人数は千二百名に達し、約三千本の苗木を植えることができました。生態系の回復も確認されており、絶滅が危惧されていたオオタカの営巣も観察されています。\n事務局長：第二の事業は、環境教育プログラムの推進です。市内の小中学校二十三校において、出前授業を実施しました。生物多様性の大切さや、身近にできるエコ活動について、体験を交えながら学んでいただきました。特に好評だったのが、河川の水質調査を子どもたち自身が行うプログラムで、科学的な探究心を育むとともに、地域の環境への関心を高めることができました。\n代表：第三の事業は、プラスチックごみ削減キャンペーンです。地元企業十五社と連携し、マイボトル・マイバッグの普及促進を行いました。また、海岸清掃活動を月一回実施し、年間で約二トンのごみを回収しました。課題としましては、活動資金の確保が依然として厳しい状況にあります。会員数は増加傾向にあるものの、助成金への依存度が高く、自主財源の多様化が必要です。\n事務局長：来年度の展望としましては、企業との協働事業の拡大や、クラウドファンディングの活用など、新たな資金調達の仕組みを構築してまいります。また、他地域のNPOとのネットワーク強化を通じて、活動の広域化を目指します。\n代表：持続可能な社会の実現は、一朝一夕に達成できるものではありません。しかし、地道な活動の積み重ねが、確実に地域を変えつつあることを実感しております。引き続き皆さまのご支援を賜りますようお願い申し上げます。',
  'announcement',
  'N1',
  ARRAY['代表', '事務局長'],
  '環境保護NPOの年次総会での活動報告',
  '[{"word":"里山","reading":"さとやま","meaning_ko":"마을 뒷산(전통적 농촌 산림)"},{"word":"間伐","reading":"かんばつ","meaning_ko":"간벌"},{"word":"生態系","reading":"せいたいけい","meaning_ko":"생태계"},{"word":"生物多様性","reading":"せいぶつたようせい","meaning_ko":"생물다양성"},{"word":"助成金","reading":"じょせいきん","meaning_ko":"보조금"},{"word":"一朝一夕","reading":"いっちょういっせき","meaning_ko":"하루아침"}]'::jsonb,
  '대표: 여러분, NPO법인 "녹색 지구를 지키는 모임"의 연차 활동 보고를 드리겠습니다. 본 연도는 세 가지 중점 사업에 힘써왔습니다. 첫 번째 사업은 마을산 재생 프로젝트입니다. 황폐해져 있던 시내 5곳의 마을산에서, 지역 주민과 자원봉사자의 협력 아래 간벌 작업과 식수 활동을 실시했습니다. 연인원 참가자 수는 1,200명에 달했으며, 약 3,000그루의 묘목을 심을 수 있었습니다. 생태계 회복도 확인되고 있으며, 멸종이 우려되던 참매의 영소도 관찰되고 있습니다.\n사무국장: 두 번째 사업은 환경 교육 프로그램의 추진입니다. 시내 초중학교 23개교에서 찾아가는 수업을 실시했습니다. 생물다양성의 소중함과 생활 속에서 할 수 있는 에코 활동에 대해, 체험을 곁들이며 배워주셨습니다. 특히 호평이었던 것은 하천 수질조사를 아이들 스스로 하는 프로그램으로, 과학적 탐구심을 기르는 동시에 지역 환경에 대한 관심을 높일 수 있었습니다.\n대표: 세 번째 사업은 플라스틱 쓰레기 감축 캠페인입니다. 지역 기업 15곳과 연계하여 개인 물병·개인 가방의 보급 촉진을 했습니다. 또한 해안 청소 활동을 월 1회 실시하여, 연간 약 2톤의 쓰레기를 수거했습니다. 과제로는 활동 자금 확보가 여전히 어려운 상황에 있습니다. 회원 수는 증가 추세에 있지만, 보조금 의존도가 높아 자주 재원의 다양화가 필요합니다.\n사무국장: 내년도 전망으로는, 기업과의 협업 사업 확대나 크라우드펀딩 활용 등, 새로운 자금 조달 방법을 구축해 나가겠습니다. 또한 다른 지역 NPO와의 네트워크 강화를 통해 활동의 광역화를 목표로 합니다.\n대표: 지속 가능한 사회의 실현은 하루아침에 달성할 수 있는 것이 아닙니다. 그러나 꾸준한 활동의 축적이 확실히 지역을 변화시키고 있음을 실감하고 있습니다. 계속해서 여러분의 지원을 부탁드립니다.',
  25
);

-- ============================================
-- N5 Additional Scripts (sort_order 6-30)
-- ============================================

-- N5-6: 自己紹介 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '自己紹介',
  '先生：はい、みなさん、新しい友達を紹介します。\nキム：はじめまして。キムです。韓国から来ました。よろしくお願いします。\n先生：キムさんは今日から一緒に勉強します。キムさん、趣味は何ですか。\nキム：音楽が好きです。ギターを弾きます。\n山田：へえ、すごい！私も音楽が好きです。一緒にバンドをしませんか。\nキム：本当ですか。ぜひやりたいです。\n先生：いいですね。キムさん、分からないことがあったら何でも聞いてください。\nキム：ありがとうございます。がんばります。',
  'dialogue',
  'N5',
  ARRAY['先生', 'キム', '山田'],
  '学校で新入生が自己紹介する場面',
  '[{"word":"紹介","reading":"しょうかい","meaning_ko":"소개"},{"word":"趣味","reading":"しゅみ","meaning_ko":"취미"},{"word":"弾く","reading":"ひく","meaning_ko":"(악기를) 치다"},{"word":"ぜひ","reading":"ぜひ","meaning_ko":"꼭, 반드시"}]'::jsonb,
  '선생님: 자, 여러분, 새 친구를 소개합니다.\n김: 처음 뵙겠습니다. 김입니다. 한국에서 왔습니다. 잘 부탁드립니다.\n선생님: 김 씨는 오늘부터 함께 공부합니다. 김 씨, 취미가 뭐예요?\n김: 음악을 좋아합니다. 기타를 칩니다.\n야마다: 와, 대단하다! 저도 음악을 좋아해요. 같이 밴드 하지 않을래요?\n김: 정말이요? 꼭 하고 싶어요.\n선생님: 좋네요. 김 씨, 모르는 게 있으면 뭐든지 물어보세요.\n김: 감사합니다. 열심히 하겠습니다.',
  6
);

-- N5-7: スーパーでの買い物 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'スーパーでの買い物',
  '佐藤：今日は何を買いますか。\n田中：卵と牛乳とパンを買います。\n佐藤：野菜は要りませんか。\n田中：あ、そうですね。にんじんとたまねぎも買いましょう。\n佐藤：果物はどうですか。りんごが安いですよ。\n田中：いくらですか。\n佐藤：一つ百円です。\n田中：じゃあ、三つください。全部でいくらになりますか。\n佐藤：えーと、千二百円ぐらいだと思います。',
  'dialogue',
  'N5',
  ARRAY['佐藤', '田中'],
  'スーパーマーケットで一緒に買い物をする場面',
  '[{"word":"卵","reading":"たまご","meaning_ko":"달걀"},{"word":"牛乳","reading":"ぎゅうにゅう","meaning_ko":"우유"},{"word":"野菜","reading":"やさい","meaning_ko":"채소"},{"word":"果物","reading":"くだもの","meaning_ko":"과일"},{"word":"安い","reading":"やすい","meaning_ko":"싸다"}]'::jsonb,
  '사토: 오늘은 뭘 살 거예요?\n다나카: 달걀이랑 우유랑 빵을 살 거예요.\n사토: 채소는 안 사요?\n다나카: 아, 그러네요. 당근이랑 양파도 삽시다.\n사토: 과일은 어때요? 사과가 싸요.\n다나카: 얼마예요?\n사토: 하나에 100엔이에요.\n다나카: 그럼 세 개 주세요. 전부 얼마나 될까요?\n사토: 음, 1,200엔 정도일 것 같아요.',
  7
);

-- N5-8: 時間を聞く (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '時間を聞く',
  '田中：すみません、今何時ですか。\n鈴木：今は三時半です。\n田中：ありがとうございます。図書館は何時までですか。\n鈴木：五時までですよ。\n田中：あ、まだ時間がありますね。ここから図書館まで何分ですか。\n鈴木：歩いて五分ぐらいです。\n田中：そうですか。ありがとうございます。\n鈴木：いいえ、どういたしまして。',
  'dialogue',
  'N5',
  ARRAY['田中', '鈴木'],
  '道で人に時間を聞く場面',
  '[{"word":"今","reading":"いま","meaning_ko":"지금"},{"word":"半","reading":"はん","meaning_ko":"반"},{"word":"まだ","reading":"まだ","meaning_ko":"아직"},{"word":"どういたしまして","reading":"どういたしまして","meaning_ko":"천만에요"}]'::jsonb,
  '다나카: 실례합니다, 지금 몇 시예요?\n스즈키: 지금 3시 반이에요.\n다나카: 감사합니다. 도서관은 몇 시까지예요?\n스즈키: 5시까지예요.\n다나카: 아, 아직 시간이 있네요. 여기서 도서관까지 몇 분이에요?\n스즈키: 걸어서 5분 정도예요.\n다나카: 그래요? 감사합니다.\n스즈키: 아니에요, 천만에요.',
  8
);

-- N5-9: 病院の受付 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '病院の受付',
  '受付：おはようございます。どうしましたか。\nキム：おなかが痛いです。\n受付：いつからですか。\nキム：昨日の夜からです。\n受付：熱はありますか。\nキム：はい、少し熱があります。\n受付：分かりました。保険証はありますか。\nキム：はい、これです。\n受付：キムさんですね。少し待ってください。名前を呼びます。\nキム：はい、分かりました。',
  'dialogue',
  'N5',
  ARRAY['受付', 'キム'],
  '病院の受付で症状を伝える場面',
  '[{"word":"おなか","reading":"おなか","meaning_ko":"배"},{"word":"痛い","reading":"いたい","meaning_ko":"아프다"},{"word":"昨日","reading":"きのう","meaning_ko":"어제"},{"word":"熱","reading":"ねつ","meaning_ko":"열"},{"word":"呼ぶ","reading":"よぶ","meaning_ko":"부르다"}]'::jsonb,
  '접수: 안녕하세요. 어떻게 오셨어요?\n김: 배가 아파요.\n접수: 언제부터예요?\n김: 어제 밤부터예요.\n접수: 열이 있나요?\n김: 네, 조금 열이 있어요.\n접수: 알겠습니다. 보험증 있으세요?\n김: 네, 여기요.\n접수: 김 씨군요. 조금 기다려 주세요. 이름을 부를게요.\n김: 네, 알겠습니다.',
  9
);

-- N5-10: 電車のアナウンス (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '電車のアナウンス',
  'アナウンス：まもなく、三番線に電車が来ます。白い線の後ろに下がってください。この電車は新宿行きです。次は渋谷です。渋谷を出ますと、次は新宿です。お降りの方は、忘れ物に気をつけてください。ドアが閉まります。ご注意ください。',
  'announcement',
  'N5',
  ARRAY['アナウンス'],
  '駅での電車の案内放送',
  '[{"word":"まもなく","reading":"まもなく","meaning_ko":"곧"},{"word":"白い線","reading":"しろいせん","meaning_ko":"흰 선"},{"word":"下がる","reading":"さがる","meaning_ko":"물러나다"},{"word":"忘れ物","reading":"わすれもの","meaning_ko":"분실물"},{"word":"閉まる","reading":"しまる","meaning_ko":"닫히다"}]'::jsonb,
  '안내방송: 곧 3번선에 전차가 옵니다. 흰 선 뒤로 물러나 주세요. 이 전차는 신주쿠 행입니다. 다음은 시부야입니다. 시부야를 출발하면 다음은 신주쿠입니다. 내리시는 분은 분실물에 주의해 주세요. 문이 닫힙니다. 주의해 주세요.',
  10
);

-- N5-11: 誕生日パーティー (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '誕生日パーティー',
  '山田：鈴木さん、お誕生日おめでとうございます！\n鈴木：ありがとうございます！\n田中：これ、プレゼントです。どうぞ。\n鈴木：わあ、ありがとう！開けてもいいですか。\n田中：はい、どうぞ。\n鈴木：きれいなマフラーですね。大好きな青い色です。\n山田：よかった！さあ、ケーキを食べましょう。\n鈴木：おいしそう！ろうそくは何本ですか。\n田中：二十五本ですよ。\n鈴木：ふーっ。消えた！\n山田：おめでとう！',
  'dialogue',
  'N5',
  ARRAY['山田', '鈴木', '田中'],
  '友達の誕生日パーティーの場面',
  '[{"word":"誕生日","reading":"たんじょうび","meaning_ko":"생일"},{"word":"プレゼント","reading":"プレゼント","meaning_ko":"선물"},{"word":"マフラー","reading":"マフラー","meaning_ko":"목도리"},{"word":"ろうそく","reading":"ろうそく","meaning_ko":"양초"},{"word":"消える","reading":"きえる","meaning_ko":"꺼지다"}]'::jsonb,
  '야마다: 스즈키 씨, 생일 축하합니다!\n스즈키: 감사합니다!\n다나카: 이거 선물이에요. 여기요.\n스즈키: 와, 감사해요! 열어봐도 돼요?\n다나카: 네, 그러세요.\n스즈키: 예쁜 목도리네요. 제가 좋아하는 파란색이에요.\n야마다: 다행이다! 자, 케이크를 먹어요.\n스즈키: 맛있겠다! 양초는 몇 개예요?\n다나카: 25개예요.\n스즈키: 후~. 꺼졌다!\n야마다: 축하해요!',
  11
);

-- N5-12: 学校の教室で (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '学校の教室で',
  '先生：みなさん、おはようございます。今日の授業は、ひらがなのテストです。\n学生A：先生、テストは何時からですか。\n先生：九時半からです。鉛筆と消しゴムを出してください。\n学生B：先生、教科書を見てもいいですか。\n先生：いいえ、教科書は見ないでください。\n学生A：テストは何分ですか。\n先生：三十分です。終わったら、紙を前に出してください。\n学生B：分かりました。\n先生：じゃあ、始めてください。がんばってね。',
  'instruction',
  'N5',
  ARRAY['先生', '学生A', '学生B'],
  '教室でテストの説明をする場面',
  '[{"word":"授業","reading":"じゅぎょう","meaning_ko":"수업"},{"word":"鉛筆","reading":"えんぴつ","meaning_ko":"연필"},{"word":"消しゴム","reading":"けしゴム","meaning_ko":"지우개"},{"word":"教科書","reading":"きょうかしょ","meaning_ko":"교과서"},{"word":"紙","reading":"かみ","meaning_ko":"종이"}]'::jsonb,
  '선생님: 여러분, 안녕하세요. 오늘 수업은 히라가나 시험이에요.\n학생A: 선생님, 시험은 몇 시부터예요?\n선생님: 9시 반부터예요. 연필과 지우개를 꺼내세요.\n학생B: 선생님, 교과서를 봐도 되나요?\n선생님: 아니요, 교과서는 보지 마세요.\n학생A: 시험은 몇 분이에요?\n선생님: 30분이에요. 끝나면 종이를 앞으로 내세요.\n학생B: 알겠습니다.\n선생님: 그럼, 시작하세요. 화이팅!',
  12
);

-- N5-13: ホテルのチェックイン (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ホテルのチェックイン',
  'フロント：いらっしゃいませ。\nキム：チェックインをお願いします。キムです。\nフロント：キム様ですね。少々お待ちください。はい、お部屋は五〇三号室です。\nキム：朝ごはんは何時ですか。\nフロント：朝食は七時から九時までです。一階のレストランです。\nキム：Wi-Fiはありますか。\nフロント：はい、あります。パスワードはこちらのカードに書いてあります。\nキム：ありがとうございます。\nフロント：エレベーターはあちらです。ごゆっくりどうぞ。',
  'dialogue',
  'N5',
  ARRAY['フロント', 'キム'],
  'ホテルのフロントでチェックインする場面',
  '[{"word":"チェックイン","reading":"チェックイン","meaning_ko":"체크인"},{"word":"号室","reading":"ごうしつ","meaning_ko":"호실"},{"word":"朝食","reading":"ちょうしょく","meaning_ko":"아침식사"},{"word":"一階","reading":"いっかい","meaning_ko":"1층"},{"word":"ごゆっくり","reading":"ごゆっくり","meaning_ko":"편히"}]'::jsonb,
  '프론트: 어서 오세요.\n김: 체크인 부탁합니다. 김입니다.\n프론트: 김 님이시군요. 잠시만 기다려 주세요. 네, 방은 503호실입니다.\n김: 아침식사는 몇 시예요?\n프론트: 조식은 7시부터 9시까지입니다. 1층 레스토랑이에요.\n김: 와이파이 있나요?\n프론트: 네, 있습니다. 비밀번호는 이 카드에 적혀 있습니다.\n김: 감사합니다.\n프론트: 엘리베이터는 저쪽입니다. 편히 쉬세요.',
  13
);

-- N5-14: 家族の写真 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '家族の写真',
  '田中：これは私の家族の写真です。\n佐藤：わあ、たくさんいますね。この人はだれですか。\n田中：父です。五十歳です。会社員です。\n佐藤：この女の人は？\n田中：母です。四十八歳です。先生です。\n佐藤：兄弟はいますか。\n田中：はい、兄が一人と妹が一人います。\n佐藤：お兄さんは何をしていますか。\n田中：大学生です。東京に住んでいます。\n佐藤：妹さんは？\n田中：高校生です。十六歳です。',
  'dialogue',
  'N5',
  ARRAY['田中', '佐藤'],
  '友達に家族の写真を見せて説明する場面',
  '[{"word":"家族","reading":"かぞく","meaning_ko":"가족"},{"word":"写真","reading":"しゃしん","meaning_ko":"사진"},{"word":"会社員","reading":"かいしゃいん","meaning_ko":"회사원"},{"word":"兄弟","reading":"きょうだい","meaning_ko":"형제"},{"word":"大学生","reading":"だいがくせい","meaning_ko":"대학생"}]'::jsonb,
  '다나카: 이건 제 가족 사진이에요.\n사토: 와, 많네요. 이 사람은 누구예요?\n다나카: 아버지예요. 50세예요. 회사원이에요.\n사토: 이 여자분은요?\n다나카: 어머니예요. 48세예요. 선생님이에요.\n사토: 형제가 있어요?\n다나카: 네, 형이 한 명이랑 여동생이 한 명 있어요.\n사토: 형은 뭐 하세요?\n다나카: 대학생이에요. 도쿄에 살고 있어요.\n사토: 여동생은요?\n다나카: 고등학생이에요. 16살이에요.',
  14
);

-- N5-15: タクシーに乗る (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'タクシーに乗る',
  'キム：すみません、東京駅までお願いします。\n運転手：東京駅ですね。分かりました。\nキム：どのくらいかかりますか。\n運転手：この時間は道が混んでいますから、三十分くらいかかります。\nキム：いくらぐらいですか。\n運転手：二千円ぐらいだと思います。\nキム：分かりました。\n運転手：お客さん、着きましたよ。千八百円です。\nキム：はい。おつりはいいです。\n運転手：ありがとうございます。お忘れ物のないように。',
  'dialogue',
  'N5',
  ARRAY['キム', '運転手'],
  'タクシーに乗って東京駅まで行く場面',
  '[{"word":"運転手","reading":"うんてんしゅ","meaning_ko":"운전사"},{"word":"道","reading":"みち","meaning_ko":"길"},{"word":"混む","reading":"こむ","meaning_ko":"붐비다"},{"word":"着く","reading":"つく","meaning_ko":"도착하다"},{"word":"お忘れ物","reading":"おわすれもの","meaning_ko":"분실물"}]'::jsonb,
  '김: 실례합니다, 도쿄역까지 부탁합니다.\n운전사: 도쿄역이요. 알겠습니다.\n김: 얼마나 걸리나요?\n운전사: 이 시간에는 길이 막혀서 30분 정도 걸립니다.\n김: 얼마 정도예요?\n운전사: 2,000엔 정도일 거예요.\n김: 알겠습니다.\n운전사: 손님, 도착했습니다. 1,800엔입니다.\n김: 네. 거스름돈은 괜찮습니다.\n운전사: 감사합니다. 분실물 없으시도록.',
  15
);

-- N5-16: 映画に誘う (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '映画に誘う',
  '山田：佐藤さん、日曜日、映画を見に行きませんか。\n佐藤：いいですね。何の映画ですか。\n山田：新しいアニメの映画です。とても人気があります。\n佐藤：何時の映画ですか。\n山田：午後二時からです。\n佐藤：どこの映画館ですか。\n山田：駅の近くの映画館です。\n佐藤：チケットはいくらですか。\n山田：千八百円です。ネットで買えますよ。\n佐藤：じゃあ、一時半に映画館の前で会いましょう。\n山田：はい！楽しみですね。',
  'dialogue',
  'N5',
  ARRAY['山田', '佐藤'],
  '友達を映画に誘う場面',
  '[{"word":"映画","reading":"えいが","meaning_ko":"영화"},{"word":"人気","reading":"にんき","meaning_ko":"인기"},{"word":"映画館","reading":"えいがかん","meaning_ko":"영화관"},{"word":"チケット","reading":"チケット","meaning_ko":"티켓"},{"word":"ネット","reading":"ネット","meaning_ko":"인터넷"}]'::jsonb,
  '야마다: 사토 씨, 일요일에 영화 보러 가지 않을래요?\n사토: 좋네요. 무슨 영화예요?\n야마다: 새 애니메이션 영화예요. 아주 인기가 있어요.\n사토: 몇 시 영화예요?\n야마다: 오후 2시부터예요.\n사토: 어디 영화관이에요?\n야마다: 역 근처 영화관이에요.\n사토: 티켓은 얼마예요?\n야마다: 1,800엔이에요. 인터넷으로 살 수 있어요.\n사토: 그럼 1시 반에 영화관 앞에서 만나요.\n야마다: 네! 기대되네요.',
  16
);

-- N5-17: 交番で道を聞く (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '交番で道を聞く',
  'キム：すみません、この近くに銀行はありますか。\n警察官：銀行ですか。はい、ありますよ。\nキム：どこですか。\n警察官：この道をまっすぐ行って、コンビニの角を左に曲がってください。\nキム：コンビニの角を左ですね。\n警察官：はい。それから、二百メートルぐらい歩くと、右側に銀行があります。\nキム：何という銀行ですか。\n警察官：みずほ銀行です。大きい建物ですから、すぐ分かりますよ。\nキム：ありがとうございます。',
  'dialogue',
  'N5',
  ARRAY['キム', '警察官'],
  '交番で銀行の場所を聞く場面',
  '[{"word":"交番","reading":"こうばん","meaning_ko":"파출소"},{"word":"銀行","reading":"ぎんこう","meaning_ko":"은행"},{"word":"角","reading":"かど","meaning_ko":"모퉁이"},{"word":"メートル","reading":"メートル","meaning_ko":"미터"},{"word":"建物","reading":"たてもの","meaning_ko":"건물"}]'::jsonb,
  '김: 실례합니다, 이 근처에 은행이 있나요?\n경찰관: 은행이요? 네, 있어요.\n김: 어디예요?\n경찰관: 이 길을 곧장 가서 편의점 모퉁이에서 왼쪽으로 돌아주세요.\n김: 편의점 모퉁이에서 왼쪽이요.\n경찰관: 네. 그리고 200미터 정도 걸으면 오른쪽에 은행이 있어요.\n김: 무슨 은행이에요?\n경찰관: 미즈호 은행이에요. 큰 건물이니까 바로 알 수 있을 거예요.\n김: 감사합니다.',
  17
);

-- N5-18: 図書館で (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '図書館で',
  '司書：いらっしゃいませ。\nキム：すみません、日本語の本を探しています。\n司書：どんな本ですか。\nキム：やさしい日本語の本がいいです。\n司書：こちらにあります。この棚です。\nキム：この本を借りたいです。\n司書：カードはありますか。\nキム：いいえ、まだありません。\n司書：では、カードを作りましょう。住所と名前を書いてください。\nキム：はい。いつまで借りられますか。\n司書：二週間です。',
  'dialogue',
  'N5',
  ARRAY['司書', 'キム'],
  '図書館で本を探して借りる場面',
  '[{"word":"司書","reading":"ししょ","meaning_ko":"사서"},{"word":"探す","reading":"さがす","meaning_ko":"찾다"},{"word":"やさしい","reading":"やさしい","meaning_ko":"쉬운"},{"word":"借りる","reading":"かりる","meaning_ko":"빌리다"},{"word":"住所","reading":"じゅうしょ","meaning_ko":"주소"}]'::jsonb,
  '사서: 어서 오세요.\n김: 실례합니다, 일본어 책을 찾고 있어요.\n사서: 어떤 책이에요?\n김: 쉬운 일본어 책이 좋겠어요.\n사서: 이쪽에 있어요. 이 선반이에요.\n김: 이 책을 빌리고 싶어요.\n사서: 카드 있으세요?\n김: 아니요, 아직 없어요.\n사서: 그럼 카드를 만들어요. 주소와 이름을 써주세요.\n김: 네. 언제까지 빌릴 수 있나요?\n사서: 2주간이에요.',
  18
);

-- N5-19: 料理の作り方 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '料理の作り方',
  '先生：今日はおにぎりの作り方を教えます。まず、手を洗ってください。次に、手に水と少しの塩をつけます。そして、ごはんを手に取ります。真ん中に梅干しを入れてください。三角の形にしてください。最後に、のりを巻きます。はい、できましたね。簡単でしょう？',
  'instruction',
  'N5',
  ARRAY['先生'],
  '料理教室でおにぎりの作り方を教える場面',
  '[{"word":"作り方","reading":"つくりかた","meaning_ko":"만드는 법"},{"word":"洗う","reading":"あらう","meaning_ko":"씻다"},{"word":"塩","reading":"しお","meaning_ko":"소금"},{"word":"梅干し","reading":"うめぼし","meaning_ko":"매실장아찌"},{"word":"のり","reading":"のり","meaning_ko":"김"}]'::jsonb,
  '선생님: 오늘은 주먹밥 만드는 법을 가르쳐 드릴게요. 먼저 손을 씻으세요. 다음으로 손에 물과 약간의 소금을 묻히세요. 그리고 밥을 손에 덜어주세요. 가운데에 매실장아찌를 넣어주세요. 삼각형 모양으로 만들어주세요. 마지막으로 김을 감싸세요. 네, 됐죠? 간단하죠?',
  19
);

-- N5-20: 服を買う (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '服を買う',
  '店員：いらっしゃいませ。何をお探しですか。\nキム：Tシャツを探しています。\n店員：色は何がいいですか。\nキム：白がいいです。\n店員：サイズはいくつですか。\nキム：Mサイズです。\n店員：こちらはいかがですか。\nキム：いいですね。試着してもいいですか。\n店員：はい、あちらの部屋でどうぞ。\nキム：ちょうどいいです。これをください。\n店員：二千円です。カードでもいいですか。\nキム：はい、カードでお願いします。',
  'dialogue',
  'N5',
  ARRAY['店員', 'キム'],
  '洋服屋でTシャツを買う場面',
  '[{"word":"色","reading":"いろ","meaning_ko":"색"},{"word":"白","reading":"しろ","meaning_ko":"흰색"},{"word":"サイズ","reading":"サイズ","meaning_ko":"사이즈"},{"word":"試着","reading":"しちゃく","meaning_ko":"시착"},{"word":"ちょうど","reading":"ちょうど","meaning_ko":"딱"}]'::jsonb,
  '점원: 어서 오세요. 무엇을 찾으시나요?\n김: 티셔츠를 찾고 있어요.\n점원: 색은 뭐가 좋으세요?\n김: 흰색이 좋아요.\n점원: 사이즈는 어떻게 되세요?\n김: M사이즈예요.\n점원: 이건 어떠세요?\n김: 좋네요. 입어봐도 되나요?\n점원: 네, 저쪽 방에서 해보세요.\n김: 딱 맞아요. 이걸로 주세요.\n점원: 2,000엔입니다. 카드도 되나요?\n김: 네, 카드로 부탁합니다.',
  20
);

-- N5-21: バイトの電話 (phone_call)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'バイトの電話',
  '店長：はい、さくらカフェです。\nキム：あの、アルバイトの求人を見ました。まだ募集していますか。\n店長：はい、まだ大丈夫ですよ。\nキム：何曜日ですか。\n店長：月曜日から金曜日の間で、週三日です。\nキム：時間は何時から何時までですか。\n店長：朝十時から午後三時までです。\nキム：時給はいくらですか。\n店長：千百円です。\nキム：面接をお願いしたいのですが。\n店長：明日の午前十時に来てください。履歴書を持ってきてね。\nキム：はい、分かりました。ありがとうございます。',
  'phone_call',
  'N5',
  ARRAY['店長', 'キム'],
  'カフェにアルバイトの電話をする場面',
  '[{"word":"アルバイト","reading":"アルバイト","meaning_ko":"아르바이트"},{"word":"求人","reading":"きゅうじん","meaning_ko":"구인"},{"word":"募集","reading":"ぼしゅう","meaning_ko":"모집"},{"word":"時給","reading":"じきゅう","meaning_ko":"시급"},{"word":"履歴書","reading":"りれきしょ","meaning_ko":"이력서"}]'::jsonb,
  '점장: 네, 사쿠라 카페입니다.\n김: 저, 아르바이트 구인을 봤는데요. 아직 모집하고 있나요?\n점장: 네, 아직 괜찮아요.\n김: 무슨 요일이에요?\n점장: 월요일부터 금요일 사이에 주 3일이에요.\n김: 시간은 몇 시부터 몇 시까지예요?\n점장: 아침 10시부터 오후 3시까지예요.\n김: 시급은 얼마예요?\n점장: 1,100엔이에요.\n김: 면접을 부탁하고 싶은데요.\n점장: 내일 오전 10시에 와주세요. 이력서를 가져오세요.\n김: 네, 알겠습니다. 감사합니다.',
  21
);

-- N5-22: 季節の話 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '季節の話',
  '田中：キムさんは日本の季節で何が好きですか。\nキム：春が好きです。桜がきれいですから。\n田中：そうですね。私は秋が好きです。\nキム：どうしてですか。\n田中：涼しくて、食べ物がおいしいからです。\nキム：日本の冬は寒いですか。\n田中：はい、とても寒いです。雪が降る所もあります。\nキム：韓国も冬は寒いですよ。\n田中：夏は暑いですか。\nキム：はい、とても暑いです。でも海に行けるので楽しいです。',
  'dialogue',
  'N5',
  ARRAY['田中', 'キム'],
  '友達と日本の季節について話す場面',
  '[{"word":"季節","reading":"きせつ","meaning_ko":"계절"},{"word":"春","reading":"はる","meaning_ko":"봄"},{"word":"桜","reading":"さくら","meaning_ko":"벚꽃"},{"word":"秋","reading":"あき","meaning_ko":"가을"},{"word":"涼しい","reading":"すずしい","meaning_ko":"시원하다"}]'::jsonb,
  '다나카: 김 씨는 일본 계절 중에 뭐가 좋아요?\n김: 봄이 좋아요. 벚꽃이 예쁘니까요.\n다나카: 그렇죠. 저는 가을이 좋아요.\n김: 왜요?\n다나카: 시원하고 음식이 맛있으니까요.\n김: 일본 겨울은 추워요?\n다나카: 네, 아주 추워요. 눈이 오는 곳도 있어요.\n김: 한국도 겨울은 추워요.\n다나카: 여름은 더워요?\n김: 네, 아주 더워요. 하지만 바다에 갈 수 있어서 즐거워요.',
  22
);

-- N5-23: 落とし物 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '落とし物',
  'キム：すみません、財布を落としました。\n駅員：どこで落としましたか。\nキム：たぶん電車の中です。\n駅員：何色の財布ですか。\nキム：黒い財布です。小さいです。\n駅員：中に何がありますか。\nキム：お金と学生証があります。\n駅員：お名前と電話番号を教えてください。\nキム：キム・ミンジュンです。電話は〇九〇ー一二三四ー五六七八です。\n駅員：分かりました。見つかったら電話します。\nキム：お願いします。',
  'dialogue',
  'N5',
  ARRAY['キム', '駅員'],
  '駅で落とし物を届け出る場面',
  '[{"word":"財布","reading":"さいふ","meaning_ko":"지갑"},{"word":"落とす","reading":"おとす","meaning_ko":"떨어뜨리다"},{"word":"たぶん","reading":"たぶん","meaning_ko":"아마"},{"word":"学生証","reading":"がくせいしょう","meaning_ko":"학생증"},{"word":"見つかる","reading":"みつかる","meaning_ko":"발견되다"}]'::jsonb,
  '김: 실례합니다, 지갑을 떨어뜨렸어요.\n역무원: 어디서 떨어뜨렸어요?\n김: 아마 전차 안이에요.\n역무원: 무슨 색 지갑이에요?\n김: 검은 지갑이에요. 작아요.\n역무원: 안에 뭐가 있어요?\n김: 돈과 학생증이 있어요.\n역무원: 이름과 전화번호를 알려주세요.\n김: 김민준입니다. 전화는 090-1234-5678이에요.\n역무원: 알겠습니다. 찾으면 전화할게요.\n김: 부탁합니다.',
  23
);

-- N5-24: 日曜日の予定 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日曜日の予定',
  '山田：キムさん、日曜日は何をしますか。\nキム：午前中は掃除と洗濯をします。\n山田：午後は？\nキム：友達と買い物に行きます。山田さんは？\n山田：私は朝ジョギングをします。\nキム：いつもジョギングをしますか。\n山田：はい、毎週日曜日に走ります。\nキム：すごいですね。夜は何をしますか。\n山田：テレビを見て、早く寝ます。\nキム：いい週末ですね。',
  'dialogue',
  'N5',
  ARRAY['山田', 'キム'],
  '友達と日曜日の予定について話す場面',
  '[{"word":"掃除","reading":"そうじ","meaning_ko":"청소"},{"word":"洗濯","reading":"せんたく","meaning_ko":"빨래"},{"word":"買い物","reading":"かいもの","meaning_ko":"쇼핑"},{"word":"走る","reading":"はしる","meaning_ko":"달리다"},{"word":"早く","reading":"はやく","meaning_ko":"일찍"}]'::jsonb,
  '야마다: 김 씨, 일요일에 뭐 해요?\n김: 오전에는 청소하고 빨래해요.\n야마다: 오후에는?\n김: 친구랑 쇼핑하러 가요. 야마다 씨는?\n야마다: 저는 아침에 조깅해요.\n김: 항상 조깅해요?\n야마다: 네, 매주 일요일에 달려요.\n김: 대단하네요. 밤에는 뭐 해요?\n야마다: 텔레비전을 보고 일찍 자요.\n김: 좋은 주말이네요.',
  24
);

-- N5-25: デパートの案内放送 (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'デパートの案内放送',
  'アナウンス：お客様にご案内いたします。本日は日曜日です。お店は朝十時から夜八時まで開いています。三階でセールをしています。服が半額です。四階のレストランは十一時から開きます。ランチセットは八百円からです。駐車場は地下一階にあります。三時間まで無料です。お買い物をお楽しみください。',
  'announcement',
  'N5',
  ARRAY['アナウンス'],
  'デパートでの案内放送',
  '[{"word":"案内","reading":"あんない","meaning_ko":"안내"},{"word":"セール","reading":"セール","meaning_ko":"세일"},{"word":"半額","reading":"はんがく","meaning_ko":"반값"},{"word":"駐車場","reading":"ちゅうしゃじょう","meaning_ko":"주차장"},{"word":"無料","reading":"むりょう","meaning_ko":"무료"}]'::jsonb,
  '안내방송: 고객 여러분께 안내드립니다. 오늘은 일요일입니다. 가게는 아침 10시부터 밤 8시까지 열려 있습니다. 3층에서 세일을 하고 있습니다. 옷이 반값입니다. 4층 레스토랑은 11시부터 엽니다. 런치 세트는 800엔부터입니다. 주차장은 지하 1층에 있습니다. 3시간까지 무료입니다. 쇼핑을 즐겨주세요.',
  25
);

-- N5-26: 携帯電話を買う (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '携帯電話を買う',
  '店員：いらっしゃいませ。何をお探しですか。\nキム：スマートフォンを買いたいです。\n店員：ご予算はどのくらいですか。\nキム：安いのがいいです。毎月五千円ぐらいで使えますか。\n店員：はい、こちらのプランがおすすめです。\nキム：インターネットもできますか。\n店員：はい、毎月三ギガバイト使えます。\nキム：電話番号は新しいのをもらえますか。\n店員：はい、新しい番号を差し上げます。パスポートはお持ちですか。\nキム：はい、あります。\n店員：では、こちらの書類に名前と住所を書いてください。',
  'dialogue',
  'N5',
  ARRAY['店員', 'キム'],
  '携帯ショップでスマートフォンを買う場面',
  '[{"word":"スマートフォン","reading":"スマートフォン","meaning_ko":"스마트폰"},{"word":"予算","reading":"よさん","meaning_ko":"예산"},{"word":"プラン","reading":"プラン","meaning_ko":"요금제"},{"word":"おすすめ","reading":"おすすめ","meaning_ko":"추천"},{"word":"書類","reading":"しょるい","meaning_ko":"서류"}]'::jsonb,
  '점원: 어서 오세요. 무엇을 찾으세요?\n김: 스마트폰을 사고 싶어요.\n점원: 예산은 어느 정도예요?\n김: 싼 게 좋아요. 매달 5,000엔 정도로 쓸 수 있나요?\n점원: 네, 이 요금제를 추천합니다.\n김: 인터넷도 되나요?\n점원: 네, 매달 3기가바이트 쓸 수 있어요.\n김: 전화번호는 새로 받을 수 있나요?\n점원: 네, 새 번호를 드립니다. 여권 가지고 계세요?\n김: 네, 있어요.\n점원: 그러면 이 서류에 이름과 주소를 써주세요.',
  26
);

-- N5-27: 美容院で (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '美容院で',
  '美容師：いらっしゃいませ。今日はどうしますか。\nキム：髪を短くしてください。\n美容師：どのくらい切りますか。\nキム：三センチぐらいお願いします。\n美容師：前髪はどうしますか。\nキム：前髪も少し切ってください。\n美容師：シャンプーもしますか。\nキム：はい、お願いします。\n美容師：はい、できました。いかがですか。\nキム：いいですね。ありがとうございます。いくらですか。\n美容師：三千五百円です。',
  'dialogue',
  'N5',
  ARRAY['美容師', 'キム'],
  '美容院で髪を切ってもらう場面',
  '[{"word":"美容院","reading":"びよういん","meaning_ko":"미용실"},{"word":"髪","reading":"かみ","meaning_ko":"머리카락"},{"word":"短い","reading":"みじかい","meaning_ko":"짧다"},{"word":"切る","reading":"きる","meaning_ko":"자르다"},{"word":"前髪","reading":"まえがみ","meaning_ko":"앞머리"}]'::jsonb,
  '미용사: 어서 오세요. 오늘은 어떻게 하시겠어요?\n김: 머리를 짧게 해주세요.\n미용사: 얼마나 자를까요?\n김: 3센티 정도 부탁합니다.\n미용사: 앞머리는 어떻게 할까요?\n김: 앞머리도 조금 잘라주세요.\n미용사: 샴푸도 할까요?\n김: 네, 부탁합니다.\n미용사: 네, 다 됐어요. 어떠세요?\n김: 좋네요. 감사합니다. 얼마예요?\n미용사: 3,500엔입니다.',
  27
);

-- N5-28: ゴミの出し方 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ゴミの出し方',
  '管理人：キムさん、ゴミの出し方を説明しますね。月曜日と木曜日は燃えるゴミの日です。水曜日はプラスチックの日です。金曜日はびんと缶の日です。朝八時までに出してください。ゴミ袋は透明の袋を使ってください。段ボールは第二土曜日に出してください。分からないことがあったら聞いてくださいね。',
  'instruction',
  'N5',
  ARRAY['管理人'],
  'アパートの管理人がゴミ出しの方法を説明する場面',
  '[{"word":"ゴミ","reading":"ゴミ","meaning_ko":"쓰레기"},{"word":"燃える","reading":"もえる","meaning_ko":"타다"},{"word":"プラスチック","reading":"プラスチック","meaning_ko":"플라스틱"},{"word":"缶","reading":"かん","meaning_ko":"캔"},{"word":"透明","reading":"とうめい","meaning_ko":"투명"}]'::jsonb,
  '관리인: 김 씨, 쓰레기 버리는 법을 설명할게요. 월요일과 목요일은 타는 쓰레기 날이에요. 수요일은 플라스틱 날이에요. 금요일은 병과 캔 날이에요. 아침 8시까지 내놓아주세요. 쓰레기 봉투는 투명 봉투를 사용해 주세요. 골판지는 둘째 주 토요일에 내놓아주세요. 모르는 게 있으면 물어보세요.',
  28
);

-- N5-29: 体育の時間 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '体育の時間',
  '先生：みなさん、今日はバスケットボールをします。二つのチームに分かれてください。\n山田：先生、何人ずつですか。\n先生：五人ずつです。\nキム：私はバスケットボールが初めてです。\n先生：大丈夫ですよ。ボールを持って走ってはいけません。友達にパスしてください。\nキム：分かりました。\n先生：シュートはあのリングに入れてください。\n山田：キムさん、一緒にがんばろう！\nキム：はい！',
  'dialogue',
  'N5',
  ARRAY['先生', '山田', 'キム'],
  '学校の体育の授業でバスケットボールをする場面',
  '[{"word":"体育","reading":"たいいく","meaning_ko":"체육"},{"word":"チーム","reading":"チーム","meaning_ko":"팀"},{"word":"分かれる","reading":"わかれる","meaning_ko":"나뉘다"},{"word":"パス","reading":"パス","meaning_ko":"패스"},{"word":"初めて","reading":"はじめて","meaning_ko":"처음"}]'::jsonb,
  '선생님: 여러분, 오늘은 농구를 합니다. 두 팀으로 나눠주세요.\n야마다: 선생님, 몇 명씩이에요?\n선생님: 5명씩이에요.\n김: 저는 농구가 처음이에요.\n선생님: 괜찮아요. 공을 들고 뛰면 안 돼요. 친구에게 패스하세요.\n김: 알겠습니다.\n선생님: 슛은 저 링에 넣으세요.\n야마다: 김 씨, 같이 힘내자!\n김: 네!',
  29
);

-- N5-30: 週末の報告 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '週末の報告',
  '先生：キムさん、週末は何をしましたか。\nキム：土曜日は友達と東京タワーに行きました。\n先生：どうでしたか。\nキム：とてもきれいでした。上から東京を見ました。\n先生：写真を撮りましたか。\nキム：はい、たくさん撮りました。\n先生：日曜日は？\nキム：日曜日は家でゆっくりしました。日本語の勉強もしました。\n先生：えらいですね。何を勉強しましたか。\nキム：漢字を二十個覚えました。\n先生：すばらしい！',
  'dialogue',
  'N5',
  ARRAY['先生', 'キム'],
  '月曜日の朝に先生と週末の話をする場面',
  '[{"word":"週末","reading":"しゅうまつ","meaning_ko":"주말"},{"word":"上","reading":"うえ","meaning_ko":"위"},{"word":"撮る","reading":"とる","meaning_ko":"찍다"},{"word":"ゆっくり","reading":"ゆっくり","meaning_ko":"느긋이"},{"word":"覚える","reading":"おぼえる","meaning_ko":"외우다"}]'::jsonb,
  '선생님: 김 씨, 주말에 뭐 했어요?\n김: 토요일에 친구랑 도쿄타워에 갔어요.\n선생님: 어땠어요?\n김: 아주 예뻤어요. 위에서 도쿄를 봤어요.\n선생님: 사진 찍었어요?\n김: 네, 많이 찍었어요.\n선생님: 일요일은요?\n김: 일요일에는 집에서 느긋하게 보냈어요. 일본어 공부도 했어요.\n선생님: 대단하네요. 뭘 공부했어요?\n김: 한자를 20개 외웠어요.\n선생님: 훌륭해요!',
  30
);

-- ============================================
-- N4 Additional Scripts (sort_order 11-30)
-- ============================================

-- N4-6: 引っ越しの準備 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '引っ越しの準備',
  '佐藤：来週引っ越しなんだけど、手伝ってくれない？\n高橋：いいよ。何曜日？\n佐藤：土曜日の朝九時からなんだ。\n高橋：大丈夫だよ。荷物は多い？\n佐藤：うん、結構あるんだ。特に本が多くて。\n高橋：段ボールは用意した？\n佐藤：スーパーでもらってきたけど、まだ足りないかもしれない。\n高橋：じゃあ、僕もいくつか持っていくよ。新しい部屋は広い？\n佐藤：今より少し広いよ。駅にも近いし、家賃も同じぐらいなんだ。\n高橋：いいね。じゃあ、土曜日にね。\n佐藤：ありがとう。お昼ごはんはおごるよ。',
  'dialogue',
  'N4',
  ARRAY['佐藤', '高橋'],
  '友達に引っ越しの手伝いをお願いする場面',
  '[{"word":"引っ越し","reading":"ひっこし","meaning_ko":"이사"},{"word":"手伝う","reading":"てつだう","meaning_ko":"도와주다"},{"word":"荷物","reading":"にもつ","meaning_ko":"짐"},{"word":"段ボール","reading":"だんボール","meaning_ko":"골판지 상자"},{"word":"足りない","reading":"たりない","meaning_ko":"부족하다"},{"word":"おごる","reading":"おごる","meaning_ko":"한턱 내다"}]'::jsonb,
  '사토: 다음 주에 이사하는데 도와줄 수 있어?\n다카하시: 좋아. 무슨 요일?\n사토: 토요일 아침 9시부터야.\n다카하시: 괜찮아. 짐은 많아?\n사토: 응, 꽤 있어. 특히 책이 많아서.\n다카하시: 골판지 상자는 준비했어?\n사토: 슈퍼에서 받아왔는데 아직 부족할지도 몰라.\n다카하시: 그럼 나도 몇 개 가져갈게. 새 방은 넓어?\n사토: 지금보다 좀 넓어. 역에도 가깝고, 월세도 비슷해.\n다카하시: 좋다. 그럼 토요일에.\n사토: 고마워. 점심은 내가 살게.',
  11
);

-- N4-7: 料理教室 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '料理教室',
  '先生：今日は肉じゃがを作りましょう。材料は、牛肉、じゃがいも、にんじん、たまねぎです。\nキム：先生、調味料は何を使いますか。\n先生：しょうゆ、砂糖、みりん、酒を使います。まず、野菜を切ってください。じゃがいもは一口大に切ります。\nキム：にんじんはどう切りますか。\n先生：にんじんは乱切りにしてください。次に、鍋に油を入れて、肉を炒めます。\nキム：火の強さはどのくらいですか。\n先生：中火です。肉の色が変わったら、野菜を入れてください。\nキム：煮る時間はどのくらいですか。\n先生：二十分ぐらい煮てください。味がしみこむまで弱火にしましょう。\nキム：いい匂いがしてきました。\n先生：上手にできましたね。',
  'dialogue',
  'N4',
  ARRAY['先生', 'キム'],
  '料理教室で肉じゃがの作り方を学ぶ場面',
  '[{"word":"材料","reading":"ざいりょう","meaning_ko":"재료"},{"word":"調味料","reading":"ちょうみりょう","meaning_ko":"조미료"},{"word":"乱切り","reading":"らんぎり","meaning_ko":"어슷 썰기"},{"word":"炒める","reading":"いためる","meaning_ko":"볶다"},{"word":"煮る","reading":"にる","meaning_ko":"끓이다"},{"word":"匂い","reading":"におい","meaning_ko":"냄새"}]'::jsonb,
  '선생님: 오늘은 니쿠자가를 만들어 봅시다. 재료는 쇠고기, 감자, 당근, 양파입니다.\n김: 선생님, 조미료는 뭘 사용하나요?\n선생님: 간장, 설탕, 미린, 술을 사용합니다. 먼저 채소를 잘라주세요. 감자는 한입 크기로 자릅니다.\n김: 당근은 어떻게 자르나요?\n선생님: 당근은 어슷하게 잘라주세요. 다음으로 냄비에 기름을 넣고 고기를 볶습니다.\n김: 불 세기는 어느 정도예요?\n선생님: 중불이에요. 고기 색이 변하면 채소를 넣어주세요.\n김: 끓이는 시간은 얼마나 되나요?\n선생님: 20분 정도 끓여주세요. 맛이 배어들 때까지 약불로 합시다.\n김: 좋은 냄새가 나기 시작했어요.\n선생님: 잘 만들었네요.',
  12
);

-- N4-8: 電気屋で (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '電気屋で',
  '店員：いらっしゃいませ。何かお探しですか。\nキム：ノートパソコンを探しています。\n店員：ご使用の目的は何ですか。\nキム：プログラミングの勉強に使いたいです。\n店員：それでしたら、メモリが多いものがいいですね。こちらはメモリ十六ギガで、ストレージは五百ギガあります。\nキム：値段はいくらですか。\n店員：税込みで九万八千円です。\nキム：少し高いですね。もう少し安いのはありますか。\n店員：こちらはメモリ八ギガですが、六万五千円です。\nキム：保証はありますか。\n店員：はい、一年間のメーカー保証がついています。延長保証もお付けできます。\nキム：じゃあ、安いほうにします。',
  'dialogue',
  'N4',
  ARRAY['店員', 'キム'],
  '電器店でノートパソコンを選ぶ場面',
  '[{"word":"ノートパソコン","reading":"ノートパソコン","meaning_ko":"노트북"},{"word":"使用","reading":"しよう","meaning_ko":"사용"},{"word":"目的","reading":"もくてき","meaning_ko":"목적"},{"word":"税込み","reading":"ぜいこみ","meaning_ko":"세금 포함"},{"word":"保証","reading":"ほしょう","meaning_ko":"보증"},{"word":"延長","reading":"えんちょう","meaning_ko":"연장"}]'::jsonb,
  '점원: 어서 오세요. 뭔가 찾고 계세요?\n김: 노트북을 찾고 있어요.\n점원: 사용 목적이 뭔가요?\n김: 프로그래밍 공부에 쓰려고요.\n점원: 그러시면 메모리가 많은 게 좋겠네요. 이건 메모리 16기가에 저장 공간이 500기가 있어요.\n김: 가격은 얼마예요?\n점원: 세금 포함 98,000엔입니다.\n김: 좀 비싸네요. 좀 더 싼 건 없나요?\n점원: 이건 메모리 8기가인데 65,000엔이에요.\n김: 보증은 있나요?\n점원: 네, 1년간 제조사 보증이 있습니다. 연장 보증도 붙일 수 있어요.\n김: 그럼 싼 쪽으로 할게요.',
  13
);

-- N4-9: 歯医者の予約 (phone_call)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '歯医者の予約',
  '受付：はい、田中歯科クリニックです。\nキム：あの、予約をしたいのですが。\n受付：初めてですか。\nキム：はい、初めてです。\n受付：症状はどのようなものですか。\nキム：奥歯が痛いんです。冷たいものを飲むと特に痛みます。\n受付：いつ頃からですか。\nキム：一週間ぐらい前からです。\n受付：分かりました。来週の月曜日の午後三時はいかがですか。\nキム：できれば午前中がいいのですが。\n受付：では、火曜日の午前十時半はどうですか。\nキム：それで大丈夫です。\n受付：保険証をお持ちくださいね。\nキム：はい、分かりました。よろしくお願いします。',
  'phone_call',
  'N4',
  ARRAY['受付', 'キム'],
  '歯医者に電話で予約をする場面',
  '[{"word":"歯科","reading":"しか","meaning_ko":"치과"},{"word":"予約","reading":"よやく","meaning_ko":"예약"},{"word":"症状","reading":"しょうじょう","meaning_ko":"증상"},{"word":"奥歯","reading":"おくば","meaning_ko":"어금니"},{"word":"冷たい","reading":"つめたい","meaning_ko":"차가운"},{"word":"痛む","reading":"いたむ","meaning_ko":"아프다"}]'::jsonb,
  '접수: 네, 다나카 치과 클리닉입니다.\n김: 저, 예약을 하고 싶은데요.\n접수: 처음이세요?\n김: 네, 처음이에요.\n접수: 증상은 어떤 건가요?\n김: 어금니가 아파요. 차가운 것을 마시면 특히 아파요.\n접수: 언제부터인가요?\n김: 일주일 전쯤부터요.\n접수: 알겠습니다. 다음 주 월요일 오후 3시는 어떠세요?\n김: 가능하면 오전이 좋은데요.\n접수: 그러면 화요일 오전 10시 반은 어떠세요?\n김: 그걸로 괜찮습니다.\n접수: 보험증을 가져와 주세요.\n김: 네, 알겠습니다. 잘 부탁드립니다.',
  14
);

-- N4-10: スポーツジムの見学 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'スポーツジムの見学',
  'スタッフ：いらっしゃいませ。見学ですか。\nキム：はい、入会を考えていまして。\nスタッフ：ご案内しますね。こちらがトレーニングルームです。マシンは全部で三十台あります。\nキム：プールはありますか。\nスタッフ：はい、地下一階に二十五メートルプールがあります。\nキム：営業時間は何時から何時までですか。\nスタッフ：平日は朝六時から夜十一時まで、土日は朝八時から夜九時までです。\nキム：月会費はいくらですか。\nスタッフ：全施設利用で月八千円です。プールだけのプランは月五千円です。\nキム：見学の後、すぐ入会できますか。\nスタッフ：はい、本日入会ですと、入会金が無料になるキャンペーン中です。\nキム：それはお得ですね。入会します。',
  'dialogue',
  'N4',
  ARRAY['スタッフ', 'キム'],
  'スポーツジムを見学して入会する場面',
  '[{"word":"見学","reading":"けんがく","meaning_ko":"견학"},{"word":"入会","reading":"にゅうかい","meaning_ko":"입회"},{"word":"マシン","reading":"マシン","meaning_ko":"기구"},{"word":"営業時間","reading":"えいぎょうじかん","meaning_ko":"영업시간"},{"word":"月会費","reading":"げつかいひ","meaning_ko":"월회비"},{"word":"キャンペーン","reading":"キャンペーン","meaning_ko":"캠페인"}]'::jsonb,
  '직원: 어서 오세요. 견학이신가요?\n김: 네, 입회를 생각하고 있어서요.\n직원: 안내해 드릴게요. 이쪽이 트레이닝 룸이에요. 기구는 전부 30대 있어요.\n김: 수영장은 있나요?\n직원: 네, 지하 1층에 25미터 수영장이 있어요.\n김: 영업시간은 몇 시부터 몇 시까지예요?\n직원: 평일은 아침 6시부터 밤 11시까지, 토일은 아침 8시부터 밤 9시까지예요.\n김: 월회비는 얼마예요?\n직원: 전 시설 이용으로 월 8,000엔이에요. 수영장만 이용하는 플랜은 월 5,000엔이에요.\n김: 견학 후에 바로 입회할 수 있나요?\n직원: 네, 오늘 입회하시면 입회금이 무료인 캠페인 중이에요.\n김: 그건 이득이네요. 입회할게요.',
  15
);

-- N4-11: 図書館のルール (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '図書館のルール',
  'アナウンス：図書館からのお知らせです。図書館のルールについてご案内します。本は一人五冊まで借りることができます。貸出期間は二週間です。返却が遅れた場合は、遅れた日数分、新しい本を借りることができません。館内では静かにしてください。携帯電話での通話は禁止です。飲み物は蓋のついたボトルのみ持ち込み可能です。食べ物の持ち込みはご遠慮ください。コピー機は一階にあります。一枚十円です。閉館時間は平日が夜八時、土日は夕方五時です。ご協力をお願いいたします。',
  'announcement',
  'N4',
  ARRAY['アナウンス'],
  '図書館の利用ルールに関する館内放送',
  '[{"word":"貸出","reading":"かしだし","meaning_ko":"대출"},{"word":"返却","reading":"へんきゃく","meaning_ko":"반납"},{"word":"日数","reading":"にっすう","meaning_ko":"일수"},{"word":"通話","reading":"つうわ","meaning_ko":"통화"},{"word":"蓋","reading":"ふた","meaning_ko":"뚜껑"},{"word":"閉館","reading":"へいかん","meaning_ko":"폐관"}]'::jsonb,
  '안내방송: 도서관에서 알려드립니다. 도서관 규칙에 대해 안내합니다. 책은 1인당 5권까지 빌릴 수 있습니다. 대출 기간은 2주입니다. 반납이 늦어진 경우 늦어진 일수만큼 새 책을 빌릴 수 없습니다. 관내에서는 조용히 해주세요. 휴대전화 통화는 금지입니다. 음료는 뚜껑 있는 병만 반입할 수 있습니다. 음식 반입은 삼가주세요. 복사기는 1층에 있습니다. 한 장에 10엔입니다. 폐관 시간은 평일이 밤 8시, 토일은 오후 5시입니다. 협조 부탁드립니다.',
  16
);

-- N4-12: 銀行で口座を開く (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '銀行で口座を開く',
  '行員：いらっしゃいませ。\nキム：口座を開きたいのですが。\n行員：新規口座の開設ですね。身分証明書はお持ちですか。\nキム：在留カードがあります。\n行員：ありがとうございます。お勤め先はどちらですか。\nキム：ABCテクノロジーという会社です。\n行員：通帳とキャッシュカードをお作りします。暗証番号を四桁で決めてください。\nキム：はい。\n行員：ネットバンキングもご利用になりますか。\nキム：はい、使いたいです。\n行員：では、こちらの用紙にもう一か所サインをお願いします。\nキム：印鑑は要りますか。\n行員：サインでも結構です。手続きは三十分ほどかかります。',
  'dialogue',
  'N4',
  ARRAY['行員', 'キム'],
  '銀行で新しい口座を開く場面',
  '[{"word":"口座","reading":"こうざ","meaning_ko":"계좌"},{"word":"開設","reading":"かいせつ","meaning_ko":"개설"},{"word":"通帳","reading":"つうちょう","meaning_ko":"통장"},{"word":"暗証番号","reading":"あんしょうばんごう","meaning_ko":"비밀번호"},{"word":"印鑑","reading":"いんかん","meaning_ko":"도장"},{"word":"手続き","reading":"てつづき","meaning_ko":"절차"}]'::jsonb,
  '행원: 어서 오세요.\n김: 계좌를 열고 싶은데요.\n행원: 신규 계좌 개설이군요. 신분증은 가지고 계세요?\n김: 재류카드가 있어요.\n행원: 감사합니다. 근무처는 어디세요?\n김: ABC 테크놀로지라는 회사예요.\n행원: 통장과 캐시카드를 만들어 드리겠습니다. 비밀번호를 4자리로 정해주세요.\n김: 네.\n행원: 인터넷 뱅킹도 이용하시겠어요?\n김: 네, 사용하고 싶어요.\n행원: 그러면 이 용지에 한 곳 더 서명 부탁드립니다.\n김: 도장은 필요한가요?\n행원: 서명으로도 괜찮습니다. 절차는 30분 정도 걸립니다.',
  17
);

-- N4-13: 会社の面接 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '会社の面接',
  '面接官：お座りください。まず、自己紹介をお願いします。\nキム：はい。キム・ミンジュンと申します。韓国のソウルから来ました。大学ではコンピューターサイエンスを勉強しました。日本語能力試験のN3を持っています。\n面接官：日本に来て何年になりますか。\nキム：二年になります。\n面接官：なぜ日本で働きたいと思いましたか。\nキム：日本のIT技術に興味があるからです。特にウェブ開発の分野で働きたいと思っています。\n面接官：得意なプログラミング言語は何ですか。\nキム：JavaScriptとPythonが得意です。\n面接官：チームで仕事をした経験はありますか。\nキム：はい、大学でチームでアプリを作りました。\n面接官：分かりました。結果は来週メールでお知らせします。\nキム：ありがとうございました。',
  'dialogue',
  'N4',
  ARRAY['面接官', 'キム'],
  'IT企業の面接を受ける場面',
  '[{"word":"面接","reading":"めんせつ","meaning_ko":"면접"},{"word":"自己紹介","reading":"じこしょうかい","meaning_ko":"자기소개"},{"word":"能力試験","reading":"のうりょくしけん","meaning_ko":"능력시험"},{"word":"分野","reading":"ぶんや","meaning_ko":"분야"},{"word":"得意","reading":"とくい","meaning_ko":"잘하는"},{"word":"経験","reading":"けいけん","meaning_ko":"경험"}]'::jsonb,
  '면접관: 앉으세요. 먼저 자기소개를 부탁합니다.\n김: 네. 김민준이라고 합니다. 한국 서울에서 왔습니다. 대학에서 컴퓨터 과학을 공부했습니다. 일본어 능력시험 N3을 가지고 있습니다.\n면접관: 일본에 온 지 몇 년 되었나요?\n김: 2년 되었습니다.\n면접관: 왜 일본에서 일하고 싶다고 생각했나요?\n김: 일본의 IT 기술에 관심이 있기 때문입니다. 특히 웹 개발 분야에서 일하고 싶습니다.\n면접관: 잘하는 프로그래밍 언어는 뭔가요?\n김: JavaScript와 Python을 잘합니다.\n면접관: 팀으로 일한 경험이 있나요?\n김: 네, 대학에서 팀으로 앱을 만들었습니다.\n면접관: 알겠습니다. 결과는 다음 주 메일로 알려드리겠습니다.\n김: 감사했습니다.',
  18
);

-- N4-14: 交通事故の報告 (phone_call)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '交通事故の報告',
  '警察：はい、一一〇番です。\nキム：あの、交通事故を目撃しました。\n警察：場所はどこですか。\nキム：中央通りと桜通りの交差点です。コンビニの前です。\n警察：けが人はいますか。\nキム：自転車に乗っていた人が転んでいます。立てないようです。\n警察：救急車は必要ですか。\nキム：はい、呼んでください。足を痛がっています。\n警察：車の運転手はいますか。\nキム：はい、車を止めて降りてきています。\n警察：分かりました。すぐに向かいます。そのまま待っていてください。\nキム：はい、分かりました。',
  'phone_call',
  'N4',
  ARRAY['警察', 'キム'],
  '交通事故を目撃して警察に電話する場面',
  '[{"word":"目撃","reading":"もくげき","meaning_ko":"목격"},{"word":"交差点","reading":"こうさてん","meaning_ko":"교차로"},{"word":"けが人","reading":"けがにん","meaning_ko":"부상자"},{"word":"転ぶ","reading":"ころぶ","meaning_ko":"넘어지다"},{"word":"救急車","reading":"きゅうきゅうしゃ","meaning_ko":"구급차"}]'::jsonb,
  '경찰: 네, 110번입니다.\n김: 저, 교통사고를 목격했어요.\n경찰: 장소가 어디인가요?\n김: 주오도리와 사쿠라도리 교차로예요. 편의점 앞이에요.\n경찰: 부상자가 있나요?\n김: 자전거를 타고 있던 사람이 넘어져 있어요. 일어나지 못하는 것 같아요.\n경찰: 구급차가 필요한가요?\n김: 네, 불러주세요. 다리가 아프다고 하고 있어요.\n경찰: 자동차 운전자는 있나요?\n김: 네, 차를 세우고 내려와 있어요.\n경찰: 알겠습니다. 바로 가겠습니다. 그대로 기다려 주세요.\n김: 네, 알겠습니다.',
  19
);

-- N4-15: 映画の感想 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '映画の感想',
  '田中：昨日の映画、どうだった？\nキム：すごくよかったよ。特に最後のシーンが感動的だった。\n田中：私も泣いちゃった。主人公が手紙を読むところがね。\nキム：うん。音楽もよかったね。\n田中：監督は誰だったっけ？\nキム：山田太郎監督だよ。前の作品も面白かったんだ。\n田中：へえ、知らなかった。今度見てみる。\nキム：原作の小説もあるらしいよ。\n田中：本当？読んでみたいな。\nキム：私は映画のほうが好きかな。映像がきれいだったから。\n田中：また一緒に映画を見に行こうね。\nキム：うん、来月新しい映画が出るから、それを見よう。',
  'dialogue',
  'N4',
  ARRAY['田中', 'キム'],
  '映画を見た後に感想を話し合う場面',
  '[{"word":"感動的","reading":"かんどうてき","meaning_ko":"감동적인"},{"word":"主人公","reading":"しゅじんこう","meaning_ko":"주인공"},{"word":"監督","reading":"かんとく","meaning_ko":"감독"},{"word":"作品","reading":"さくひん","meaning_ko":"작품"},{"word":"原作","reading":"げんさく","meaning_ko":"원작"},{"word":"映像","reading":"えいぞう","meaning_ko":"영상"}]'::jsonb,
  '다나카: 어제 영화 어땠어?\n김: 엄청 좋았어. 특히 마지막 장면이 감동적이었어.\n다나카: 나도 울었어. 주인공이 편지를 읽는 장면 말이야.\n김: 응. 음악도 좋았지.\n다나카: 감독이 누구였더라?\n김: 야마다 타로 감독이야. 전 작품도 재미있었어.\n다나카: 그래? 몰랐어. 다음에 봐봐야지.\n김: 원작 소설도 있대.\n다나카: 정말? 읽어보고 싶다.\n김: 나는 영화 쪽이 더 좋은 것 같아. 영상이 예뻤으니까.\n다나카: 또 같이 영화 보러 가자.\n김: 응, 다음 달에 새 영화가 나오니까 그거 보자.',
  20
);

-- N4-16: 薬局で (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '薬局で',
  '薬剤師：いらっしゃいませ。どうされましたか。\nキム：風邪をひいたみたいで、鼻水が止まらないんです。\n薬剤師：熱はありますか。\nキム：少しあります。三十七度五分ぐらいです。\n薬剤師：のどの痛みはありますか。\nキム：はい、少し痛いです。\n薬剤師：アレルギーはありますか。\nキム：いいえ、ありません。\n薬剤師：では、この薬がいいと思います。一日三回、食後に飲んでください。\nキム：眠くなりますか。\n薬剤師：少し眠くなる場合があります。車の運転はしないでください。\nキム：分かりました。いくらですか。\n薬剤師：千二百円です。お大事に。',
  'dialogue',
  'N4',
  ARRAY['薬剤師', 'キム'],
  '薬局で風邪薬を買う場面',
  '[{"word":"薬剤師","reading":"やくざいし","meaning_ko":"약사"},{"word":"鼻水","reading":"はなみず","meaning_ko":"콧물"},{"word":"アレルギー","reading":"アレルギー","meaning_ko":"알레르기"},{"word":"食後","reading":"しょくご","meaning_ko":"식후"},{"word":"眠い","reading":"ねむい","meaning_ko":"졸리다"}]'::jsonb,
  '약사: 어서 오세요. 어떻게 하셨나요?\n김: 감기에 걸린 것 같아서 콧물이 멈추지 않아요.\n약사: 열이 있나요?\n김: 조금 있어요. 37도 5부 정도예요.\n약사: 목 아픈 건 있나요?\n김: 네, 좀 아파요.\n약사: 알레르기는 있나요?\n김: 아니요, 없어요.\n약사: 그러면 이 약이 좋을 것 같아요. 하루 3번 식후에 드세요.\n김: 졸려지나요?\n약사: 약간 졸릴 수 있어요. 운전은 하지 마세요.\n김: 알겠습니다. 얼마예요?\n약사: 1,200엔이에요. 몸조리 하세요.',
  21
);

-- N4-17: 電車の遅延 (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '電車の遅延',
  'アナウンス：お客様にお知らせいたします。中央線は人身事故の影響で、現在運転を見合わせております。復旧の見通しは午後二時頃を予定しております。振替輸送をご利用のお客様は、改札で証明書をお受け取りください。山手線と地下鉄丸ノ内線は通常通り運行しております。お急ぎの方はそちらをご利用ください。ご迷惑をおかけして申し訳ございません。最新の情報は、駅の掲示板またはホームページでご確認ください。',
  'announcement',
  'N4',
  ARRAY['アナウンス'],
  '電車の遅延に関する駅の案内放送',
  '[{"word":"人身事故","reading":"じんしんじこ","meaning_ko":"인신사고"},{"word":"運転見合わせ","reading":"うんてんみあわせ","meaning_ko":"운행 중단"},{"word":"復旧","reading":"ふっきゅう","meaning_ko":"복구"},{"word":"振替輸送","reading":"ふりかえゆそう","meaning_ko":"대체 수송"},{"word":"証明書","reading":"しょうめいしょ","meaning_ko":"증명서"},{"word":"迷惑","reading":"めいわく","meaning_ko":"폐, 민폐"}]'::jsonb,
  '안내방송: 고객 여러분께 알려드립니다. 주오선은 인신사고의 영향으로 현재 운행을 중단하고 있습니다. 복구 예정은 오후 2시경입니다. 대체 수송을 이용하시는 고객님은 개찰구에서 증명서를 받아주세요. 야마노테선과 지하철 마루노우치선은 정상 운행하고 있습니다. 급하신 분은 그쪽을 이용해 주세요. 불편을 끼쳐 죄송합니다. 최신 정보는 역 게시판 또는 홈페이지에서 확인해 주세요.',
  22
);

-- N4-18: 宅配便の受け取り (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '宅配便の受け取り',
  '配達員：宅配便です。\nキム：はい。\n配達員：キム・ミンジュン様ですか。\nキム：はい、そうです。\n配達員：お届け物がございます。こちらにサインをお願いします。\nキム：はい。これ、誰からですか。\n配達員：韓国からの国際便ですね。\nキム：ああ、母が送ってくれたものだと思います。\n配達員：それから、もう一つあるのですが、冷蔵の荷物です。\nキム：冷蔵ですか。\n配達員：はい、生鮮食品ですので、お早めにお召し上がりください。\nキム：分かりました。ありがとうございます。\n配達員：ありがとうございました。',
  'dialogue',
  'N4',
  ARRAY['配達員', 'キム'],
  '自宅で宅配便を受け取る場面',
  '[{"word":"宅配便","reading":"たくはいびん","meaning_ko":"택배"},{"word":"届け物","reading":"とどけもの","meaning_ko":"배달물"},{"word":"国際便","reading":"こくさいびん","meaning_ko":"국제 배송"},{"word":"冷蔵","reading":"れいぞう","meaning_ko":"냉장"},{"word":"生鮮食品","reading":"せいせんしょくひん","meaning_ko":"신선식품"}]'::jsonb,
  '배달원: 택배입니다.\n김: 네.\n배달원: 김민준 님이세요?\n김: 네, 맞아요.\n배달원: 배달물이 있습니다. 여기에 사인 부탁드립니다.\n김: 네. 이거 누구한테서 온 거예요?\n배달원: 한국에서 온 국제 배송이에요.\n김: 아, 어머니가 보내주신 것 같아요.\n배달원: 그리고 하나 더 있는데요, 냉장 짐이에요.\n김: 냉장이요?\n배달원: 네, 신선식품이니까 빨리 드세요.\n김: 알겠습니다. 감사합니다.\n배달원: 감사합니다.',
  23
);

-- N4-19: ペットを飼いたい (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ペットを飼いたい',
  'キム：最近、ペットを飼いたいと思っているんだ。\n田中：いいね！何を飼いたいの？\nキム：猫がいいなと思って。\n田中：アパートはペットOKなの？\nキム：うん、小さいペットは大丈夫なんだ。\n田中：猫は一人暮らしの人にぴったりだよ。留守番もできるし。\nキム：でも、世話が大変かなと心配で。\n田中：最初は大変かもしれないけど、すぐ慣れるよ。\nキム：ペットショップと保護猫カフェ、どっちがいいかな。\n田中：保護猫をお勧めするよ。かわいい猫がたくさんいるし。\nキム：そうだね。今度見に行ってみる。\n田中：一緒に行こうか？\nキム：うん、お願い！',
  'dialogue',
  'N4',
  ARRAY['キム', '田中'],
  'ペットを飼うことについて友達と相談する場面',
  '[{"word":"飼う","reading":"かう","meaning_ko":"기르다"},{"word":"留守番","reading":"るすばん","meaning_ko":"집 보기"},{"word":"世話","reading":"せわ","meaning_ko":"돌보기"},{"word":"慣れる","reading":"なれる","meaning_ko":"익숙해지다"},{"word":"保護猫","reading":"ほごねこ","meaning_ko":"보호 고양이"}]'::jsonb,
  '김: 요즘 반려동물을 기르고 싶다고 생각하고 있어.\n다나카: 좋다! 뭘 키우고 싶어?\n김: 고양이가 좋을 것 같아서.\n다나카: 아파트가 반려동물 OK야?\n김: 응, 작은 반려동물은 괜찮아.\n다나카: 고양이는 혼자 사는 사람한테 딱이야. 집도 잘 보고.\n김: 그런데 돌보기가 힘들까 봐 걱정이야.\n다나카: 처음에는 힘들 수도 있지만 금방 익숙해져.\n김: 펫숍이랑 보호 고양이 카페, 어디가 좋을까?\n다나카: 보호 고양이를 추천해. 귀여운 고양이가 많아.\n김: 그렇지. 다음에 보러 가봐야지.\n다나카: 같이 갈까?\n김: 응, 부탁해!',
  24
);

-- N4-20: 花見の計画 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '花見の計画',
  '山田：来週の土曜日、花見をしない？\nキム：花見？桜を見るやつ？\n山田：そう。上野公園で。\nキム：いいね！何を持っていく？\n山田：お弁当と飲み物を持っていこうよ。\nキム：私はキンパを作って持っていくよ。\n山田：わあ、嬉しい！私はおにぎりを作るね。\nキム：場所取りは誰がする？\n山田：朝早く行って、場所を取るよ。シートも持っていく。\nキム：寒くないかな。\n山田：天気予報では暖かいって言ってたよ。でも、上着は持ってきたほうがいいね。\nキム：分かった。他に誰か誘う？\n山田：鈴木さんと高橋さんも誘おうよ。\nキム：オーケー。じゃあ、連絡するね。',
  'dialogue',
  'N4',
  ARRAY['山田', 'キム'],
  '友達と花見の計画を立てる場面',
  '[{"word":"花見","reading":"はなみ","meaning_ko":"꽃놀이"},{"word":"場所取り","reading":"ばしょとり","meaning_ko":"자리 잡기"},{"word":"シート","reading":"シート","meaning_ko":"돗자리"},{"word":"天気予報","reading":"てんきよほう","meaning_ko":"일기예보"},{"word":"上着","reading":"うわぎ","meaning_ko":"겉옷"},{"word":"誘う","reading":"さそう","meaning_ko":"초대하다"}]'::jsonb,
  '야마다: 다음 주 토요일에 꽃놀이 안 할래?\n김: 꽃놀이? 벚꽃 보는 거?\n야마다: 응. 우에노 공원에서.\n김: 좋다! 뭘 가져가?\n야마다: 도시락이랑 음료를 가져가자.\n김: 나는 김밥을 만들어서 가져갈게.\n야마다: 와, 기쁘다! 나는 주먹밥을 만들 게.\n김: 자리 잡기는 누가 해?\n야마다: 아침 일찍 가서 자리 잡을게. 돗자리도 가져가.\n김: 춥지 않을까?\n야마다: 일기예보에서는 따뜻하다고 했어. 하지만 겉옷은 가져오는 게 좋겠지.\n김: 알았어. 다른 사람도 초대해?\n야마다: 스즈키 씨랑 다카하시 씨도 초대하자.\n김: 오케이. 그럼 연락할게.',
  25
);

-- N4-21: 自転車の登録 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '自転車の登録',
  '店員：自転車をお買い上げいただき、ありがとうございます。防犯登録をしますね。\nキム：防犯登録って何ですか。\n店員：自転車が盗まれたときに、持ち主を確認するための登録です。\nキム：いくらですか。\n店員：六百円です。法律で決まっていますので、必ず登録してください。\nキム：分かりました。何か書類は要りますか。\n店員：お名前と住所、電話番号をこちらに書いてください。身分証も見せてください。\nキム：はい。鍵はついていますか。\n店員：はい、鍵は二本お付けします。スペアキーは大切に保管してください。\nキム：ライトは自動ですか。\n店員：はい、暗くなると自動で点きます。\nキム：ありがとうございます。',
  'dialogue',
  'N4',
  ARRAY['店員', 'キム'],
  '自転車を購入して防犯登録する場面',
  '[{"word":"防犯登録","reading":"ぼうはんとうろく","meaning_ko":"방범 등록"},{"word":"盗む","reading":"ぬすむ","meaning_ko":"훔치다"},{"word":"持ち主","reading":"もちぬし","meaning_ko":"주인"},{"word":"法律","reading":"ほうりつ","meaning_ko":"법률"},{"word":"スペアキー","reading":"スペアキー","meaning_ko":"여분 열쇠"},{"word":"保管","reading":"ほかん","meaning_ko":"보관"}]'::jsonb,
  '점원: 자전거를 구매해 주셔서 감사합니다. 방범 등록을 할게요.\n김: 방범 등록이 뭐예요?\n점원: 자전거가 도난당했을 때 소유자를 확인하기 위한 등록이에요.\n김: 얼마예요?\n점원: 600엔이에요. 법률로 정해져 있으니 반드시 등록해 주세요.\n김: 알겠습니다. 서류가 필요한가요?\n점원: 이름과 주소, 전화번호를 여기에 써주세요. 신분증도 보여주세요.\n김: 네. 열쇠는 달려 있나요?\n점원: 네, 열쇠는 2개 드립니다. 여분 열쇠는 소중히 보관해 주세요.\n김: 라이트는 자동인가요?\n점원: 네, 어두워지면 자동으로 켜져요.\n김: 감사합니다.',
  26
);

-- N4-22: 結婚式の招待 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '結婚式の招待',
  '佐藤：キムさん、来月の十五日、私の結婚式に来てくれませんか。\nキム：わあ、おめでとうございます！ぜひ出席させていただきます。\n佐藤：ありがとう。場所は横浜のホテルニューグランドです。\nキム：時間は何時からですか。\n佐藤：式は午後一時からで、披露宴は二時半からです。\nキム：服装はスーツでいいですか。\n佐藤：はい、男性はスーツ、ネクタイでお願いします。\nキム：お祝いはいくらぐらい包めばいいですか。\n佐藤：三万円が一般的ですが、気持ちで大丈夫ですよ。\nキム：分かりました。二次会はありますか。\n佐藤：はい、近くのレストランで六時からです。会費は五千円です。\nキム：楽しみにしています。本当におめでとうございます。',
  'dialogue',
  'N4',
  ARRAY['佐藤', 'キム'],
  '友達の結婚式に招待される場面',
  '[{"word":"結婚式","reading":"けっこんしき","meaning_ko":"결혼식"},{"word":"出席","reading":"しゅっせき","meaning_ko":"출석"},{"word":"披露宴","reading":"ひろうえん","meaning_ko":"피로연"},{"word":"服装","reading":"ふくそう","meaning_ko":"복장"},{"word":"お祝い","reading":"おいわい","meaning_ko":"축의금"},{"word":"二次会","reading":"にじかい","meaning_ko":"2차 모임"}]'::jsonb,
  '사토: 김 씨, 다음 달 15일 제 결혼식에 와주실 수 있나요?\n김: 와, 축하합니다! 꼭 참석하겠습니다.\n사토: 감사합니다. 장소는 요코하마 호텔 뉴그랜드예요.\n김: 시간은 몇 시부터인가요?\n사토: 식은 오후 1시부터이고 피로연은 2시 반부터예요.\n김: 복장은 정장으로 괜찮나요?\n사토: 네, 남성은 정장에 넥타이 부탁합니다.\n김: 축의금은 얼마 정도 하면 되나요?\n사토: 3만 엔이 일반적인데 마음으로 괜찮아요.\n김: 알겠습니다. 2차는 있나요?\n사토: 네, 근처 레스토랑에서 6시부터예요. 회비는 5,000엔이에요.\n김: 기대하고 있겠습니다. 정말 축하드려요.',
  27
);

-- N4-23: 市役所で住民登録 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '市役所で住民登録',
  '職員：番号札三十五番の方、二番窓口にお越しください。\nキム：はい。\n職員：本日はどのようなご用件ですか。\nキム：住所変更の届け出をしたいのですが。\n職員：転入届ですね。以前のお住まいはどちらですか。\nキム：大阪市です。\n職員：転出証明書はお持ちですか。\nキム：はい、こちらです。\n職員：ありがとうございます。マイナンバーカードはお持ちですか。\nキム：いいえ、まだ持っていません。\n職員：マイナンバーの通知カードはありますか。\nキム：はい、あります。\n職員：では、こちらの書類にご記入ください。新しい住所と、引っ越し日を書いてください。',
  'dialogue',
  'N4',
  ARRAY['職員', 'キム'],
  '市役所で住所変更の手続きをする場面',
  '[{"word":"番号札","reading":"ばんごうふだ","meaning_ko":"번호표"},{"word":"住所変更","reading":"じゅうしょへんこう","meaning_ko":"주소 변경"},{"word":"届け出","reading":"とどけで","meaning_ko":"신고"},{"word":"転入届","reading":"てんにゅうとどけ","meaning_ko":"전입신고"},{"word":"マイナンバー","reading":"マイナンバー","meaning_ko":"마이넘버(개인번호)"}]'::jsonb,
  '직원: 번호표 35번 고객님, 2번 창구로 와주세요.\n김: 네.\n직원: 오늘은 어떤 용건이세요?\n김: 주소 변경 신고를 하고 싶은데요.\n직원: 전입신고군요. 이전 거주지는 어디세요?\n김: 오사카시예요.\n직원: 전출증명서는 가지고 계세요?\n김: 네, 여기요.\n직원: 감사합니다. 마이넘버 카드는 가지고 계세요?\n김: 아니요, 아직 없어요.\n직원: 마이넘버 통지카드는 있나요?\n김: 네, 있어요.\n직원: 그러면 이 서류에 기입해 주세요. 새 주소와 이사 날짜를 써주세요.',
  28
);

-- N4-24: コンビニバイトの研修 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'コンビニバイトの研修',
  '店長：キムさん、今日はレジの使い方を説明します。まず、バーコードをスキャンします。商品をこちらに通してください。\nキム：はい。\n店長：合計金額が表示されたら、お客様にお伝えしてください。「〇〇円になります」と言います。\nキム：お金を受け取ったらどうしますか。\n店長：まず、お預かり金額を入力します。おつりが自動で出ます。\nキム：袋に入れますか。\n店長：お客様に聞いてください。「レジ袋はご利用ですか」と。有料で三円です。\nキム：温めるものはどうしますか。\n店長：お弁当は「温めますか」と聞いてください。電子レンジで一分半です。\nキム：ポイントカードも聞きますか。\n店長：はい、「ポイントカードはお持ちですか」と聞いてください。\nキム：分かりました。がんばります。',
  'instruction',
  'N4',
  ARRAY['店長', 'キム'],
  'コンビニバイトの研修でレジの使い方を学ぶ場面',
  '[{"word":"研修","reading":"けんしゅう","meaning_ko":"연수"},{"word":"レジ","reading":"レジ","meaning_ko":"계산대"},{"word":"バーコード","reading":"バーコード","meaning_ko":"바코드"},{"word":"合計","reading":"ごうけい","meaning_ko":"합계"},{"word":"有料","reading":"ゆうりょう","meaning_ko":"유료"},{"word":"電子レンジ","reading":"でんしレンジ","meaning_ko":"전자레인지"}]'::jsonb,
  '점장: 김 씨, 오늘은 계산대 사용법을 설명할게요. 먼저 바코드를 스캔합니다. 상품을 이쪽으로 통과시켜 주세요.\n김: 네.\n점장: 합계 금액이 표시되면 고객님께 알려주세요. "OO엔입니다"라고 말합니다.\n김: 돈을 받으면 어떻게 하나요?\n점장: 먼저 받은 금액을 입력합니다. 거스름돈이 자동으로 나와요.\n김: 봉투에 넣나요?\n점장: 고객님께 물어보세요. "비닐봉지 이용하시겠어요?"라고요. 유료로 3엔이에요.\n김: 데울 것은 어떻게 하나요?\n점장: 도시락은 "데워드릴까요?"라고 물어주세요. 전자레인지로 1분 반이에요.\n김: 포인트 카드도 물어보나요?\n점장: 네, "포인트 카드 가지고 계세요?"라고 물어보세요.\n김: 알겠습니다. 열심히 하겠습니다.',
  29
);

-- N4-25: ホームシックの相談 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ホームシックの相談',
  'キム：最近、ちょっとホームシックなんです。\n先輩：そうなんだ。日本に来てどのくらい？\nキム：三か月です。最初は楽しかったけど、最近家族に会いたくて。\n先輩：分かるよ。私も最初はそうだった。\nキム：先輩はどうやって乗り越えましたか。\n先輩：友達をたくさん作ったよ。あと、毎週家族とビデオ通話してる。\nキム：私もビデオ通話はしているけど、やっぱり寂しくて。\n先輩：韓国の料理を作ってみたら？材料は新大久保で買えるよ。\nキム：それはいい考えですね。\n先輩：あと、趣味のサークルに入るのもおすすめだよ。私はバドミントンのサークルに入ったんだ。\nキム：楽しそうですね。考えてみます。\n先輩：いつでも相談してね。',
  'dialogue',
  'N4',
  ARRAY['キム', '先輩'],
  '先輩にホームシックを相談する場面',
  '[{"word":"ホームシック","reading":"ホームシック","meaning_ko":"향수병"},{"word":"乗り越える","reading":"のりこえる","meaning_ko":"극복하다"},{"word":"寂しい","reading":"さびしい","meaning_ko":"외롭다"},{"word":"材料","reading":"ざいりょう","meaning_ko":"재료"},{"word":"サークル","reading":"サークル","meaning_ko":"동아리"},{"word":"相談","reading":"そうだん","meaning_ko":"상담"}]'::jsonb,
  '김: 최근에 좀 향수병이에요.\n선배: 그래? 일본에 온 지 얼마나 됐어?\n김: 3개월이에요. 처음에는 즐거웠는데 요즘 가족이 보고 싶어서.\n선배: 알아. 나도 처음에는 그랬어.\n김: 선배는 어떻게 극복했어요?\n선배: 친구를 많이 만들었어. 그리고 매주 가족이랑 영상통화를 해.\n김: 저도 영상통화는 하고 있는데 역시 외로워서.\n선배: 한국 요리를 만들어 보면 어때? 재료는 신오쿠보에서 살 수 있어.\n김: 그건 좋은 생각이네요.\n선배: 그리고 취미 동아리에 들어가는 것도 추천이야. 나는 배드민턴 동아리에 들어갔거든.\n김: 재미있겠네요. 생각해 볼게요.\n선배: 언제든지 상담해.',
  30
);

-- ============================================
-- N3 Additional Scripts (sort_order 16-30)
-- ============================================

-- N3-6: 会社の新人研修 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '会社の新人研修',
  '部長：皆さん、入社おめでとうございます。本日から二週間の新人研修が始まります。\nキム：よろしくお願いします。\n部長：まず、社内のルールについて説明します。始業時間は九時ですが、十分前には席に着いてください。\n新入社員A：残業は多いですか。\n部長：繁忙期はありますが、基本的には定時退社を推奨しています。残業する場合は上司の承認が必要です。\nキム：名刺交換のマナーも教えていただけますか。\n部長：もちろんです。名刺は両手で渡し、相手の名刺も両手で受け取ります。受け取った名刺はテーブルの上に置いてください。\n新入社員A：報告書のフォーマットはありますか。\n部長：はい、社内ポータルにテンプレートがあります。分からないことは先輩社員に遠慮なく聞いてください。\nキム：はい、がんばります。',
  'dialogue',
  'N3',
  ARRAY['部長', 'キム', '新入社員A'],
  '会社の新人研修で社内ルールを学ぶ場面',
  '[{"word":"入社","reading":"にゅうしゃ","meaning_ko":"입사"},{"word":"始業","reading":"しぎょう","meaning_ko":"업무 시작"},{"word":"定時退社","reading":"ていじたいしゃ","meaning_ko":"정시 퇴근"},{"word":"承認","reading":"しょうにん","meaning_ko":"승인"},{"word":"名刺交換","reading":"めいしこうかん","meaning_ko":"명함 교환"},{"word":"遠慮なく","reading":"えんりょなく","meaning_ko":"사양 없이"}]'::jsonb,
  '부장: 여러분, 입사를 축하합니다. 오늘부터 2주간 신입 연수가 시작됩니다.\n김: 잘 부탁드립니다.\n부장: 먼저 사내 규칙에 대해 설명합니다. 업무 시작 시간은 9시이지만 10분 전에는 자리에 앉아 주세요.\n신입사원A: 야근은 많나요?\n부장: 바쁜 시기는 있지만, 기본적으로 정시 퇴근을 권장하고 있습니다. 야근할 경우 상사의 승인이 필요합니다.\n김: 명함 교환 매너도 가르쳐 주실 수 있나요?\n부장: 물론입니다. 명함은 양손으로 건네고, 상대의 명함도 양손으로 받습니다. 받은 명함은 테이블 위에 놓아주세요.\n신입사원A: 보고서 양식이 있나요?\n부장: 네, 사내 포털에 템플릿이 있습니다. 모르는 것은 선배 사원에게 사양 없이 물어보세요.\n김: 네, 열심히 하겠습니다.',
  16
);

-- N3-7: ITプロジェクトのミーティング (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ITプロジェクトのミーティング',
  'リーダー：それでは、今週の進捗報告をお願いします。田中さんから。\n田中：フロントエンドの画面設計が八割完了しました。来週中にはレビューに出せる予定です。\nリーダー：順調ですね。キムさんは？\nキム：APIの実装を進めていますが、データベースの設計で少し悩んでいます。\nリーダー：具体的にはどの部分ですか。\nキム：ユーザーの権限管理のテーブル設計です。要件が途中で変わったので、修正が必要になりました。\nリーダー：それは田中さんに相談してみてください。以前似たような実装をしていますから。\n田中：はい、午後に一緒に見ましょう。\nキム：ありがとうございます。助かります。\nリーダー：テスト環境の構築はどうなっていますか。\n田中：サーバーの設定が終わりました。明日からテストデータの投入を始めます。\nリーダー：分かりました。次のミーティングは来週の月曜日です。',
  'meeting',
  'N3',
  ARRAY['リーダー', '田中', 'キム'],
  'IT企業の週次プロジェクトミーティング',
  '[{"word":"進捗","reading":"しんちょく","meaning_ko":"진척"},{"word":"画面設計","reading":"がめんせっけい","meaning_ko":"화면 설계"},{"word":"実装","reading":"じっそう","meaning_ko":"구현"},{"word":"権限管理","reading":"けんげんかんり","meaning_ko":"권한 관리"},{"word":"テスト環境","reading":"テストかんきょう","meaning_ko":"테스트 환경"},{"word":"投入","reading":"とうにゅう","meaning_ko":"투입"}]'::jsonb,
  '리더: 그러면 이번 주 진척 보고를 부탁합니다. 다나카 씨부터.\n다나카: 프런트엔드 화면 설계가 80% 완료되었습니다. 다음 주 중으로 리뷰에 올릴 수 있을 예정입니다.\n리더: 순조롭네요. 김 씨는?\n김: API 구현을 진행하고 있는데 데이터베이스 설계에서 좀 고민이 있습니다.\n리더: 구체적으로 어떤 부분인가요?\n김: 사용자 권한 관리 테이블 설계입니다. 요건이 도중에 바뀌어서 수정이 필요해졌습니다.\n리더: 그건 다나카 씨에게 상담해 보세요. 이전에 비슷한 구현을 한 적이 있으니까요.\n다나카: 네, 오후에 같이 봅시다.\n김: 감사합니다. 큰 도움이 됩니다.\n리더: 테스트 환경 구축은 어떻게 되고 있나요?\n다나카: 서버 설정이 끝났습니다. 내일부터 테스트 데이터 투입을 시작합니다.\n리더: 알겠습니다. 다음 미팅은 다음 주 월요일입니다.',
  17
);

-- N3-8: 電話でのクレーム対応 (phone_call)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '電話でのクレーム対応',
  '佐藤：お電話ありがとうございます。カスタマーサポートの佐藤でございます。\n客：先週注文した商品がまだ届かないんですが。\n佐藤：大変申し訳ございません。注文番号を教えていただけますか。\n客：A二三四五六七です。\n佐藤：確認いたします。少々お待ちください。お客様、お待たせいたしました。確認したところ、配送センターでの手違いで発送が遅れておりました。\n客：困るんですよ。今週中に届きますか。\n佐藤：はい、本日中に発送いたします。明日には届くかと思います。\n客：届かなかったらどうするんですか。\n佐藤：万が一届かない場合は、すぐにお電話ください。送料は当社が負担いたします。また、お詫びとして次回ご注文時に使える五百円のクーポンを発行いたします。\n客：分かりました。よろしくお願いします。\n佐藤：ご迷惑をおかけして誠に申し訳ございませんでした。',
  'phone_call',
  'N3',
  ARRAY['佐藤', '客'],
  'カスタマーサポートに商品未着の電話をする場面',
  '[{"word":"クレーム","reading":"クレーム","meaning_ko":"클레임, 불만"},{"word":"注文番号","reading":"ちゅうもんばんごう","meaning_ko":"주문번호"},{"word":"手違い","reading":"てちがい","meaning_ko":"착오"},{"word":"発送","reading":"はっそう","meaning_ko":"발송"},{"word":"送料","reading":"そうりょう","meaning_ko":"배송비"},{"word":"クーポン","reading":"クーポン","meaning_ko":"쿠폰"}]'::jsonb,
  '사토: 전화 감사합니다. 고객지원 사토입니다.\n고객: 지난주에 주문한 상품이 아직 안 왔는데요.\n사토: 대단히 죄송합니다. 주문번호를 알려주시겠어요?\n고객: A234567입니다.\n사토: 확인하겠습니다. 잠시만 기다려 주세요. 고객님, 기다려 주셔서 감사합니다. 확인한 결과, 배송센터의 착오로 발송이 늦어졌습니다.\n고객: 곤란하네요. 이번 주 안에 도착하나요?\n사토: 네, 오늘 중으로 발송하겠습니다. 내일에는 도착할 것으로 생각됩니다.\n고객: 안 도착하면 어떻게 하죠?\n사토: 만약 도착하지 않으면 바로 전화해 주세요. 배송비는 저희가 부담합니다. 또한 사과의 뜻으로 다음 주문 시 사용할 수 있는 500엔 쿠폰을 발행하겠습니다.\n고객: 알겠습니다. 잘 부탁합니다.\n사토: 불편을 끼쳐 정말 죄송했습니다.',
  18
);

-- N3-9: 健康診断の結果説明 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '健康診断の結果説明',
  '医師：キムさん、健康診断の結果が出ましたのでお話しします。\nキム：はい、よろしくお願いします。\n医師：まず、視力は両目とも一・〇で問題ありません。血圧も正常値です。\nキム：安心しました。\n医師：ただ、肝機能の数値が少し気になります。ガンマGTPが基準値を超えています。\nキム：何が原因ですか。\n医師：お酒は飲みますか。\nキム：はい、週に四、五回ぐらい飲みます。\n医師：飲酒量が多いことが原因の可能性があります。週に二回は休肝日を作ってください。\nキム：分かりました。他に気をつけることはありますか。\n医師：体重が去年より三キロ増えています。適度な運動を心がけてください。\nキム：デスクワークが多いので、運動不足なんです。\n医師：通勤時に一駅分歩くだけでも効果がありますよ。\nキム：やってみます。ありがとうございました。',
  'dialogue',
  'N3',
  ARRAY['医師', 'キム'],
  '会社の健康診断の結果を医師から説明される場面',
  '[{"word":"健康診断","reading":"けんこうしんだん","meaning_ko":"건강검진"},{"word":"視力","reading":"しりょく","meaning_ko":"시력"},{"word":"血圧","reading":"けつあつ","meaning_ko":"혈압"},{"word":"肝機能","reading":"かんきのう","meaning_ko":"간 기능"},{"word":"基準値","reading":"きじゅんち","meaning_ko":"기준치"},{"word":"運動不足","reading":"うんどうぶそく","meaning_ko":"운동 부족"}]'::jsonb,
  '의사: 김 씨, 건강검진 결과가 나왔으니 말씀드리겠습니다.\n김: 네, 부탁합니다.\n의사: 먼저 시력은 양쪽 눈 모두 1.0으로 문제없습니다. 혈압도 정상치입니다.\n김: 다행이에요.\n의사: 다만 간 기능 수치가 약간 신경 쓰입니다. 감마GTP가 기준치를 넘었습니다.\n김: 원인이 뭔가요?\n의사: 술은 드세요?\n김: 네, 주 4~5회 정도 마셔요.\n의사: 음주량이 많은 것이 원인일 가능성이 있습니다. 주 2회는 금주일을 만들어 주세요.\n김: 알겠습니다. 다른 주의할 점이 있나요?\n의사: 체중이 작년보다 3킬로 늘었습니다. 적절한 운동을 유의해 주세요.\n김: 사무직이라 운동 부족이에요.\n의사: 출퇴근 시 한 역분을 걷는 것만으로도 효과가 있어요.\n김: 해보겠습니다. 감사했습니다.',
  19
);

-- N3-10: 賃貸契約の更新 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '賃貸契約の更新',
  '大家：キムさん、来月で契約が二年になりますね。更新はどうされますか。\nキム：はい、更新したいと思っています。\n大家：ありがとうございます。更新料は家賃一か月分の七万円になります。\nキム：分割で払うことはできますか。\n大家：申し訳ありませんが、一括でお願いしております。\nキム：分かりました。あの、実は少し相談したいことがあるのですが。\n大家：何でしょうか。\nキム：エアコンの調子が悪くて、冷房が効かないんです。\n大家：それは困りますね。備え付けのエアコンですので、こちらで修理の手配をします。\nキム：ありがとうございます。あと、隣の部屋の方が夜遅くまで音楽をかけていて、少し気になるのですが。\n大家：分かりました。全体に注意の手紙を出しますね。\nキム：よろしくお願いします。\n大家：更新の書類は来週お持ちしますので、印鑑を用意しておいてください。',
  'dialogue',
  'N3',
  ARRAY['大家', 'キム'],
  'アパートの賃貸契約を更新する場面',
  '[{"word":"賃貸","reading":"ちんたい","meaning_ko":"임대"},{"word":"契約","reading":"けいやく","meaning_ko":"계약"},{"word":"更新","reading":"こうしん","meaning_ko":"갱신"},{"word":"更新料","reading":"こうしんりょう","meaning_ko":"갱신료"},{"word":"備え付け","reading":"そなえつけ","meaning_ko":"비치, 설치"},{"word":"手配","reading":"てはい","meaning_ko":"수배, 준비"}]'::jsonb,
  '집주인: 김 씨, 다음 달이면 계약이 2년이 되네요. 갱신은 어떻게 하시겠어요?\n김: 네, 갱신하고 싶습니다.\n집주인: 감사합니다. 갱신료는 월세 1개월분인 7만 엔입니다.\n김: 분할로 낼 수 있나요?\n집주인: 죄송하지만 일시불로 부탁드리고 있습니다.\n김: 알겠습니다. 저, 사실 좀 상담드릴 게 있는데요.\n집주인: 무엇인가요?\n김: 에어컨 상태가 안 좋아서 냉방이 안 돼요.\n집주인: 그건 곤란하네요. 비치된 에어컨이니까 저희 쪽에서 수리 수배를 하겠습니다.\n김: 감사합니다. 그리고 옆방 분이 밤늦게까지 음악을 틀어서 좀 신경 쓰이는데요.\n집주인: 알겠습니다. 전체에 주의 편지를 보내겠습니다.\n김: 잘 부탁드립니다.\n집주인: 갱신 서류는 다음 주에 가져올 테니 도장을 준비해 주세요.',
  20
);

-- N3-11: 日本語能力試験の勉強法 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本語能力試験の勉強法',
  'キム：先生、来月のJLPTのN2を受けようと思っているのですが、勉強法を教えてください。\n先生：まず、過去問を解いてみましたか。\nキム：はい、一回やりましたが、読解が特に難しかったです。\n先生：読解は長い文章に慣れることが大切です。毎日新聞記事を一つ読む習慣をつけましょう。\nキム：リスニングはどう対策すればいいですか。\n先生：日本のドラマやニュースを字幕なしで聞く練習をしてください。最初は分からなくても、キーワードを拾う訓練が大事です。\nキム：語彙はどうやって覚えますか。\n先生：単語帳だけでなく、例文と一緒に覚えてください。使い方を知ることが記憶の定着につながります。\nキム：文法は？\n先生：N2の文法パターンを整理して、似た表現との違いを理解してください。\nキム：試験当日のアドバイスはありますか。\n先生：時間配分に気をつけてください。分からない問題に時間をかけすぎないことが大切です。\nキム：分かりました。がんばります。',
  'dialogue',
  'N3',
  ARRAY['キム', '先生'],
  '日本語の先生にJLPTの勉強法を相談する場面',
  '[{"word":"過去問","reading":"かこもん","meaning_ko":"기출문제"},{"word":"読解","reading":"どっかい","meaning_ko":"독해"},{"word":"対策","reading":"たいさく","meaning_ko":"대책"},{"word":"語彙","reading":"ごい","meaning_ko":"어휘"},{"word":"記憶の定着","reading":"きおくのていちゃく","meaning_ko":"기억의 정착"},{"word":"時間配分","reading":"じかんはいぶん","meaning_ko":"시간 배분"}]'::jsonb,
  '김: 선생님, 다음 달 JLPT N2를 보려고 하는데 공부법을 알려주세요.\n선생님: 우선 기출문제를 풀어봤어요?\n김: 네, 한 번 해봤는데 독해가 특히 어려웠어요.\n선생님: 독해는 긴 문장에 익숙해지는 게 중요해요. 매일 신문 기사를 하나 읽는 습관을 들이세요.\n김: 리스닝은 어떻게 대비하면 되나요?\n선생님: 일본 드라마나 뉴스를 자막 없이 듣는 연습을 하세요. 처음에는 몰라도 키워드를 잡는 훈련이 중요해요.\n김: 어휘는 어떻게 외우나요?\n선생님: 단어장뿐만 아니라 예문과 함께 외우세요. 사용법을 아는 것이 기억 정착으로 이어져요.\n김: 문법은요?\n선생님: N2 문법 패턴을 정리하고, 비슷한 표현과의 차이를 이해하세요.\n김: 시험 당일 조언이 있나요?\n선생님: 시간 배분에 주의하세요. 모르는 문제에 시간을 너무 쓰지 않는 것이 중요합니다.\n김: 알겠습니다. 열심히 하겠습니다.',
  21
);

-- N3-12: 上司への報告 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '上司への報告',
  'キム：課長、少しお時間よろしいですか。\n課長：はい、どうしましたか。\nキム：先週依頼されたレポートの件ですが、完成しましたので確認をお願いしたいのですが。\n課長：ありがとうございます。期限内に仕上げてくれましたね。\nキム：はい。ただ、一つ気になる点があります。先月の売上データに誤りがあるかもしれません。\n課長：どの部分ですか。\nキム：第三四半期の営業部の数字が、経理から来たデータと合わないんです。\n課長：それは確認が必要ですね。経理部の山田さんに問い合わせてもらえますか。\nキム：はい、今日中に確認して、修正があれば報告します。\n課長：そうしてください。それから、来週のクライアントへのプレゼン資料も準備しておいてください。\nキム：分かりました。金曜日までに完成させます。\n課長：よろしくお願いします。何かあればいつでも声をかけてください。',
  'dialogue',
  'N3',
  ARRAY['キム', '課長'],
  '上司にレポートの進捗を報告する場面',
  '[{"word":"依頼","reading":"いらい","meaning_ko":"의뢰"},{"word":"期限","reading":"きげん","meaning_ko":"기한"},{"word":"売上","reading":"うりあげ","meaning_ko":"매출"},{"word":"四半期","reading":"しはんき","meaning_ko":"분기"},{"word":"問い合わせ","reading":"といあわせ","meaning_ko":"문의"},{"word":"プレゼン","reading":"プレゼン","meaning_ko":"프레젠테이션"}]'::jsonb,
  '김: 과장님, 잠시 시간 괜찮으세요?\n과장: 네, 무슨 일이에요?\n김: 지난주 의뢰받은 레포트 건인데요, 완성했으니 확인을 부탁드리고 싶습니다.\n과장: 감사합니다. 기한 내에 완성해 주었네요.\n김: 네. 다만 한 가지 신경 쓰이는 점이 있습니다. 지난달 매출 데이터에 오류가 있을 수도 있습니다.\n과장: 어떤 부분인가요?\n김: 3분기 영업부 수치가 경리에서 온 데이터와 맞지 않아요.\n과장: 그건 확인이 필요하네요. 경리부 야마다 씨에게 문의해 줄 수 있나요?\n김: 네, 오늘 중으로 확인하고 수정이 있으면 보고하겠습니다.\n과장: 그렇게 해주세요. 그리고 다음 주 클라이언트 프레젠 자료도 준비해 주세요.\n김: 알겠습니다. 금요일까지 완성하겠습니다.\n과장: 잘 부탁합니다. 뭐든 있으면 언제든 말씀해 주세요.',
  22
);

-- N3-13: 地震の備え (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '地震の備え',
  '講師：皆さん、日本は地震が多い国です。いつ大きな地震が来てもいいように、日頃から備えておくことが大切です。まず、非常持ち出し袋を準備してください。中には水、食料、懐中電灯、電池、救急セット、常備薬を入れておきましょう。家具は転倒防止器具で固定してください。特に寝室の家具が倒れると危険です。地震が起きたら、まずテーブルの下に隠れてください。揺れが収まったら、火の元を確認し、ドアを開けて避難経路を確保してください。エレベーターは使わないでください。家族との連絡方法も事前に決めておきましょう。災害用伝言ダイヤル一七一の使い方を覚えておくと安心です。最寄りの避難所がどこにあるか、事前に確認しておいてください。',
  'monologue',
  'N3',
  ARRAY['講師'],
  '地域の防災教室での地震対策の説明',
  '[{"word":"備え","reading":"そなえ","meaning_ko":"대비"},{"word":"非常持ち出し袋","reading":"ひじょうもちだしぶくろ","meaning_ko":"비상 대피 배낭"},{"word":"転倒防止","reading":"てんとうぼうし","meaning_ko":"전도 방지"},{"word":"揺れ","reading":"ゆれ","meaning_ko":"흔들림"},{"word":"避難経路","reading":"ひなんけいろ","meaning_ko":"피난 경로"},{"word":"伝言ダイヤル","reading":"でんごんダイヤル","meaning_ko":"전언 다이얼"}]'::jsonb,
  '강사: 여러분, 일본은 지진이 많은 나라입니다. 언제 큰 지진이 와도 괜찮도록 평소에 대비해 두는 것이 중요합니다. 먼저 비상 대피 배낭을 준비해 주세요. 안에는 물, 식량, 손전등, 배터리, 구급 세트, 상비약을 넣어둡시다. 가구는 전도 방지 기구로 고정해 주세요. 특히 침실 가구가 넘어지면 위험합니다. 지진이 발생하면 우선 테이블 아래로 숨으세요. 흔들림이 가라앉으면 불의 원인을 확인하고, 문을 열어 피난 경로를 확보하세요. 엘리베이터는 사용하지 마세요. 가족과의 연락 방법도 사전에 정해둡시다. 재해용 전언 다이얼 171 사용법을 알아두면 안심입니다. 가장 가까운 대피소가 어디에 있는지 사전에 확인해 두세요.',
  23
);

-- N3-14: 環境問題のディスカッション (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '環境問題のディスカッション',
  '先生：今日は環境問題について話し合いましょう。身近にできることは何だと思いますか。\nキム：まず、ゴミの分別をきちんとすることだと思います。韓国でもリサイクルは大切にされていますが、日本の分別はもっと細かいですね。\n鈴木：私はマイバッグとマイボトルを使っています。ペットボトルを買わなくなりました。\n先生：いいですね。他にはどうですか。\n田中：食品ロスも問題だと思います。必要な分だけ買って、賞味期限が近い商品から買うようにしています。\nキム：電気の節約も大切ですよね。私はこまめに電気を消すようにしています。\n鈴木：交通手段も環境に影響しますよね。自転車や公共交通機関を使うことで、二酸化炭素の排出を減らせます。\n先生：皆さん、よく考えていますね。小さな行動の積み重ねが、大きな変化につながります。一人一人の意識が大切です。',
  'meeting',
  'N3',
  ARRAY['先生', 'キム', '鈴木', '田中'],
  '日本語教室での環境問題についてのディスカッション',
  '[{"word":"分別","reading":"ぶんべつ","meaning_ko":"분리수거"},{"word":"食品ロス","reading":"しょくひんロス","meaning_ko":"음식물 쓰레기"},{"word":"賞味期限","reading":"しょうみきげん","meaning_ko":"유통기한"},{"word":"節約","reading":"せつやく","meaning_ko":"절약"},{"word":"二酸化炭素","reading":"にさんかたんそ","meaning_ko":"이산화탄소"},{"word":"排出","reading":"はいしゅつ","meaning_ko":"배출"}]'::jsonb,
  '선생님: 오늘은 환경 문제에 대해 이야기합시다. 가까이에서 할 수 있는 것은 뭐라고 생각해요?\n김: 우선 쓰레기 분리를 제대로 하는 것이라고 생각합니다. 한국에서도 재활용은 중요하게 여기지만 일본의 분리는 더 세밀하네요.\n스즈키: 저는 개인 가방과 개인 물병을 사용하고 있어요. 페트병을 사지 않게 됐어요.\n선생님: 좋네요. 다른 것은요?\n다나카: 음식물 쓰레기도 문제라고 생각해요. 필요한 만큼만 사고, 유통기한이 가까운 상품부터 사도록 하고 있어요.\n김: 전기 절약도 중요하죠. 저는 꼼꼼하게 전기를 끄도록 하고 있어요.\n스즈키: 교통수단도 환경에 영향을 주잖아요. 자전거나 대중교통을 이용함으로써 이산화탄소 배출을 줄일 수 있어요.\n선생님: 여러분, 잘 생각하고 있네요. 작은 행동의 축적이 큰 변화로 이어집니다. 한 사람 한 사람의 의식이 중요합니다.',
  24
);

-- N3-15: 旅行代理店での相談 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '旅行代理店での相談',
  '担当者：いらっしゃいませ。ご旅行のご相談ですか。\nキム：はい、ゴールデンウィークに沖縄に行きたいと思っています。\n担当者：沖縄ですね。何泊のご予定ですか。\nキム：二泊三日で考えています。\n担当者：航空券とホテルのセットプランがお得ですよ。一人六万五千円からです。\nキム：朝食はついていますか。\n担当者：はい、朝食付きです。こちらのホテルはビーチまで歩いて五分です。\nキム：レンタカーもつけられますか。\n担当者：はい、追加一万円でレンタカーを二日間お付けできます。\nキム：観光のおすすめはありますか。\n担当者：美ら海水族館は絶対おすすめです。あと、首里城も人気がありますよ。\nキム：シュノーケリングもしたいのですが。\n担当者：現地のツアーに申し込めます。半日コースで五千円程度です。\nキム：いいですね。このプランで予約をお願いします。\n担当者：かしこまりました。お名前とパスポート番号をお願いします。',
  'dialogue',
  'N3',
  ARRAY['担当者', 'キム'],
  '旅行代理店で沖縄旅行の相談をする場面',
  '[{"word":"旅行代理店","reading":"りょこうだいりてん","meaning_ko":"여행사"},{"word":"セットプラン","reading":"セットプラン","meaning_ko":"세트 플랜"},{"word":"レンタカー","reading":"レンタカー","meaning_ko":"렌터카"},{"word":"水族館","reading":"すいぞくかん","meaning_ko":"수족관"},{"word":"シュノーケリング","reading":"シュノーケリング","meaning_ko":"스노클링"}]'::jsonb,
  '담당자: 어서 오세요. 여행 상담이세요?\n김: 네, 골든위크에 오키나와에 가고 싶은데요.\n담당자: 오키나와요. 며칠 묵으실 예정이에요?\n김: 2박 3일로 생각하고 있어요.\n담당자: 항공권과 호텔 세트 플랜이 할인이에요. 1인당 65,000엔부터입니다.\n김: 아침식사는 포함인가요?\n담당자: 네, 조식 포함이에요. 이 호텔은 해변까지 걸어서 5분이에요.\n김: 렌터카도 추가할 수 있나요?\n담당자: 네, 추가 1만 엔으로 렌터카를 2일간 제공해 드릴 수 있어요.\n김: 관광 추천이 있나요?\n담당자: 추라우미 수족관은 꼭 추천해요. 그리고 슈리성도 인기가 있어요.\n김: 스노클링도 하고 싶은데요.\n담당자: 현지 투어에 신청할 수 있어요. 반나절 코스로 5,000엔 정도예요.\n김: 좋네요. 이 플랜으로 예약 부탁합니다.\n담당자: 알겠습니다. 성함과 여권 번호를 부탁드립니다.',
  25
);

-- N3-16: 社内のIT研修 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '社内のIT研修',
  '講師：今日はセキュリティ研修を行います。まず、パスワードの管理について説明します。パスワードは八文字以上で、大文字、小文字、数字、記号を含めてください。三か月ごとに変更することが推奨されています。同じパスワードを複数のサービスで使い回さないでください。次に、フィッシングメールに注意してください。不審なメールのリンクはクリックしないでください。送信元のアドレスをよく確認してください。添付ファイルも安易に開かないでください。また、社外秘の資料はUSBメモリに保存しないでください。個人のスマートフォンで社内の写真を撮ることも禁止です。何か不審なことがあれば、すぐにIT部門に連絡してください。セキュリティは全社員の責任です。',
  'instruction',
  'N3',
  ARRAY['講師'],
  '会社で行われるセキュリティ研修の講義',
  '[{"word":"セキュリティ","reading":"セキュリティ","meaning_ko":"보안"},{"word":"使い回す","reading":"つかいまわす","meaning_ko":"돌려쓰다"},{"word":"フィッシング","reading":"フィッシング","meaning_ko":"피싱"},{"word":"不審","reading":"ふしん","meaning_ko":"의심스러운"},{"word":"添付ファイル","reading":"てんぷファイル","meaning_ko":"첨부파일"},{"word":"社外秘","reading":"しゃがいひ","meaning_ko":"사외비밀"}]'::jsonb,
  '강사: 오늘은 보안 연수를 진행합니다. 먼저 패스워드 관리에 대해 설명합니다. 패스워드는 8자 이상으로 대문자, 소문자, 숫자, 기호를 포함시켜 주세요. 3개월마다 변경하는 것이 권장됩니다. 같은 패스워드를 여러 서비스에서 돌려쓰지 마세요. 다음으로 피싱 메일에 주의하세요. 의심스러운 메일의 링크는 클릭하지 마세요. 발신자 주소를 잘 확인하세요. 첨부파일도 함부로 열지 마세요. 또한 사외비밀 자료는 USB 메모리에 저장하지 마세요. 개인 스마트폰으로 사내 사진을 찍는 것도 금지입니다. 의심스러운 일이 있으면 바로 IT 부서에 연락하세요. 보안은 전 사원의 책임입니다.',
  26
);

-- N3-17: 引っ越し業者との打ち合わせ (phone_call)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '引っ越し業者との打ち合わせ',
  '業者：お電話ありがとうございます。さくら引越センターです。\nキム：引っ越しの見積もりをお願いしたいのですが。\n業者：ありがとうございます。引っ越し予定日はいつですか。\nキム：来月の十五日を考えています。\n業者：現在のお住まいは？\nキム：新宿区のワンルームです。三階でエレベーターなしです。\n業者：引っ越し先は？\nキム：中野区の1LDKです。こちらは五階でエレベーターありです。\n業者：大型の家具はありますか。\nキム：冷蔵庫と洗濯機とベッドがあります。\n業者：段ボール箱はいくつぐらいになりそうですか。\nキム：二十箱ぐらいだと思います。\n業者：概算で四万五千円程度になります。段ボールは無料でお届けします。\nキム：梱包は自分でやりますが、大型家具はお願いしたいです。\n業者：承知しました。正確なお見積もりは訪問見積もりで出しますので、日程を決めましょう。',
  'phone_call',
  'N3',
  ARRAY['業者', 'キム'],
  '引っ越し業者に電話で見積もりを依頼する場面',
  '[{"word":"見積もり","reading":"みつもり","meaning_ko":"견적"},{"word":"エレベーター","reading":"エレベーター","meaning_ko":"엘리베이터"},{"word":"大型","reading":"おおがた","meaning_ko":"대형"},{"word":"概算","reading":"がいさん","meaning_ko":"대략 계산"},{"word":"梱包","reading":"こんぽう","meaning_ko":"포장"},{"word":"訪問","reading":"ほうもん","meaning_ko":"방문"}]'::jsonb,
  '업체: 전화 감사합니다. 사쿠라 이사센터입니다.\n김: 이사 견적을 부탁하고 싶은데요.\n업체: 감사합니다. 이사 예정일은 언제인가요?\n김: 다음 달 15일을 생각하고 있어요.\n업체: 현재 거주지는요?\n김: 신주쿠구 원룸이에요. 3층이고 엘리베이터 없어요.\n업체: 이사할 곳은요?\n김: 나카노구 1LDK예요. 여기는 5층이고 엘리베이터 있어요.\n업체: 대형 가구가 있나요?\n김: 냉장고와 세탁기와 침대가 있어요.\n업체: 골판지 상자는 몇 개 정도 될까요?\n김: 20상자 정도일 것 같아요.\n업체: 대략 45,000엔 정도 됩니다. 골판지는 무료로 배달해 드려요.\n김: 포장은 제가 하겠지만 대형 가구는 부탁하고 싶어요.\n업체: 알겠습니다. 정확한 견적은 방문 견적으로 내드리니 일정을 정합시다.',
  27
);

-- N3-18: 歓送迎会の幹事 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '歓送迎会の幹事',
  'キム：高橋さん、来週の歓送迎会の件ですが、お店は決まりましたか。\n高橋：駅前の居酒屋を予約しました。個室で、飲み放題つきコースで一人四千五百円です。\nキム：何名で予約しましたか。\n高橋：十五名です。でも、まだ返事をもらっていない人が三人います。\nキム：木曜日までに返事をもらいましょう。私からもう一度メールを送ります。\n高橋：ありがとうございます。アレルギーの確認もしなきゃいけませんね。\nキム：そうですね。田中さんはエビアレルギーだったはずです。\n高橋：お店に伝えておきます。プレゼントの準備はどうですか。\nキム：退職される佐藤さんには花束と寄せ書きを用意します。新しく入る鈴木さんには歓迎のメッセージカードを作ります。\n高橋：乾杯の挨拶は部長にお願いしましょう。\nキム：はい、もう依頼しました。送別のスピーチはキムさんがお願いしますと言われました。\n高橋：えっ、私？それは緊張するな。',
  'dialogue',
  'N3',
  ARRAY['キム', '高橋'],
  '歓送迎会の準備を幹事同士で打ち合わせる場面',
  '[{"word":"歓送迎会","reading":"かんそうげいかい","meaning_ko":"환송영회"},{"word":"幹事","reading":"かんじ","meaning_ko":"간사"},{"word":"飲み放題","reading":"のみほうだい","meaning_ko":"음료 무제한"},{"word":"個室","reading":"こしつ","meaning_ko":"개인실"},{"word":"寄せ書き","reading":"よせがき","meaning_ko":"기념 서명"},{"word":"乾杯","reading":"かんぱい","meaning_ko":"건배"}]'::jsonb,
  '김: 다카하시 씨, 다음 주 환송영회 건인데요, 가게는 정해졌나요?\n다카하시: 역 앞 이자카야를 예약했어요. 개인실이고, 음료 무제한 코스로 1인당 4,500엔이에요.\n김: 몇 명으로 예약했나요?\n다카하시: 15명이에요. 하지만 아직 답을 못 받은 사람이 3명 있어요.\n김: 목요일까지 답을 받읍시다. 제가 한 번 더 메일을 보낼게요.\n다카하시: 감사합니다. 알레르기 확인도 해야 하네요.\n김: 맞아요. 다나카 씨는 새우 알레르기였을 거예요.\n다카하시: 가게에 전해놓을게요. 선물 준비는 어떠세요?\n김: 퇴직하시는 사토 씨에게는 꽃다발과 기념 서명을 준비해요. 새로 오시는 스즈키 씨에게는 환영 메시지 카드를 만들어요.\n다카하시: 건배 인사는 부장님께 부탁합시다.\n김: 네, 이미 의뢰했어요. 송별 스피치는 다카하시 씨가 해달라고 하셨어요.\n다카하시: 에, 나? 긴장되겠다.',
  28
);

-- N3-19: マンションの内見 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'マンションの内見',
  '不動産屋：こちらが1LDKのお部屋です。南向きで日当たりが良いですよ。\nキム：明るくていいですね。築何年ですか。\n不動産屋：築十年です。去年リフォーム済みです。\nキム：キッチンは新しいですね。ガスコンロですか。\n不動産屋：IHです。安全で掃除も楽ですよ。\nキム：収納はどのくらいありますか。\n不動産屋：ウォークインクローゼットが一つと、玄関に靴箱があります。\nキム：インターネットはすぐ使えますか。\n不動産屋：光回線が導入済みで、プロバイダーを契約すればすぐ使えます。\nキム：周辺環境はどうですか。\n不動産屋：スーパーは歩いて三分、コンビニは一分です。病院も近くにあります。\nキム：夜は静かですか。\n不動産屋：住宅街ですので、比較的静かです。\nキム：前向きに検討したいと思います。',
  'dialogue',
  'N3',
  ARRAY['不動産屋', 'キム'],
  '不動産屋とマンションの内見をする場面',
  '[{"word":"内見","reading":"ないけん","meaning_ko":"내부 견학"},{"word":"南向き","reading":"みなみむき","meaning_ko":"남향"},{"word":"日当たり","reading":"ひあたり","meaning_ko":"햇빛 들기"},{"word":"リフォーム","reading":"リフォーム","meaning_ko":"리모델링"},{"word":"収納","reading":"しゅうのう","meaning_ko":"수납"},{"word":"光回線","reading":"ひかりかいせん","meaning_ko":"광통신 회선"}]'::jsonb,
  '부동산: 이쪽이 1LDK 방입니다. 남향이라 햇빛이 잘 들어요.\n김: 밝고 좋네요. 몇 년 된 건물인가요?\n부동산: 10년 됐어요. 작년에 리모델링 완료했어요.\n김: 주방이 새거네요. 가스레인지인가요?\n부동산: IH예요. 안전하고 청소도 편해요.\n김: 수납은 얼마나 있나요?\n부동산: 워크인 클로젯이 하나와 현관에 신발장이 있어요.\n김: 인터넷은 바로 쓸 수 있나요?\n부동산: 광통신이 도입되어 있어서 프로바이더 계약하면 바로 쓸 수 있어요.\n김: 주변 환경은 어떤가요?\n부동산: 슈퍼는 걸어서 3분, 편의점은 1분이에요. 병원도 근처에 있어요.\n김: 밤에는 조용한가요?\n부동산: 주택가라서 비교적 조용해요.\n김: 긍정적으로 검토하고 싶습니다.',
  29
);

-- N3-20: 日本の祝日について (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本の祝日について',
  'キム：日本は祝日が多いですね。韓国より多い気がします。\n田中：そうですね。年間十六日あります。\nキム：お正月は何日休みですか。\n田中：会社によりますが、普通は十二月二十九日から一月三日までの六日間ぐらいです。\nキム：ゴールデンウィークはどうですか。\n田中：四月末から五月初めにかけて祝日が集中しています。会社によっては一週間以上休める人もいます。\nキム：お盆休みはありますか。\n田中：お盆は祝日ではありませんが、多くの会社が八月十三日から十五日前後を休みにしています。\nキム：日本人はお盆に何をしますか。\n田中：実家に帰って、お墓参りをする人が多いです。交通機関はとても混みます。\nキム：韓国のチュソクに似ていますね。\n田中：そうなんですか。どんな行事ですか。\nキム：家族が集まって、先祖に感謝する行事です。松餅というお餅を作ります。\n田中：日本のお盆とよく似ていますね。',
  'dialogue',
  'N3',
  ARRAY['キム', '田中'],
  '日本と韓国の祝日について話す場面',
  '[{"word":"祝日","reading":"しゅくじつ","meaning_ko":"공휴일"},{"word":"お盆","reading":"おぼん","meaning_ko":"오봉(일본 명절)"},{"word":"お墓参り","reading":"おはかまいり","meaning_ko":"성묘"},{"word":"先祖","reading":"せんぞ","meaning_ko":"조상"},{"word":"行事","reading":"ぎょうじ","meaning_ko":"행사"}]'::jsonb,
  '김: 일본은 공휴일이 많네요. 한국보다 많은 것 같아요.\n다나카: 그렇죠. 연간 16일 있어요.\n김: 새해는 며칠 쉬나요?\n다나카: 회사에 따라 다르지만 보통 12월 29일부터 1월 3일까지 6일간 정도예요.\n김: 골든위크는 어떤가요?\n다나카: 4월 말부터 5월 초에 걸쳐 공휴일이 집중되어 있어요. 회사에 따라서는 일주일 이상 쉬는 사람도 있어요.\n김: 오봉 휴가는 있나요?\n다나카: 오봉은 공휴일이 아니지만 많은 회사가 8월 13일부터 15일 전후를 쉬게 해요.\n김: 일본인은 오봉에 뭘 하나요?\n다나카: 고향에 돌아가서 성묘하는 사람이 많아요. 교통기관은 아주 붐비죠.\n김: 한국의 추석과 비슷하네요.\n다나카: 그런가요? 어떤 행사인가요?\n김: 가족이 모여서 조상에게 감사하는 행사예요. 송편이라는 떡을 만들어요.\n다나카: 일본 오봉과 참 비슷하네요.',
  30
);

-- ============================================
-- N2 Additional Scripts (sort_order 21-30)
-- ============================================

-- N2-6: IT企業の技術面接 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'IT企業の技術面接',
  '面接官：本日はよろしくお願いします。まず、前職でのプロジェクト経験についてお聞かせください。\nキム：前職では、ECサイトのバックエンド開発を担当しておりました。マイクロサービスアーキテクチャへの移行プロジェクトで、主にAPI設計とデータベース最適化を行いました。\n面接官：チームの規模はどのくらいでしたか。\nキム：開発チームは八名で、うちバックエンドが四名でした。スクラム開発を採用しておりまして、私はスクラムマスターも兼任しておりました。\n面接官：技術的に最も苦労した点は何ですか。\nキム：レガシーシステムからの移行時にデータの整合性を保つことが最大の課題でした。段階的な移行計画を立て、並行稼動期間を設けることで、ダウンタイムをほぼゼロに抑えることができました。\n面接官：弊社では大規模なトラフィックを処理する必要がありますが、パフォーマンスチューニングの経験はありますか。\nキム：はい、キャッシュ戦略の見直しやクエリの最適化で、レスポンスタイムを四十パーセント改善した経験があります。\n面接官：素晴らしい実績ですね。最後に、なぜ弊社を志望されたのですか。\nキム：御社のクラウドネイティブな技術スタックと、エンジニアが主体的に技術選定に関われる文化に魅力を感じました。\n面接官：分かりました。結果は一週間以内にお知らせします。',
  'dialogue',
  'N2',
  ARRAY['面接官', 'キム'],
  'IT企業の技術面接を受ける場面',
  '[{"word":"マイクロサービス","reading":"マイクロサービス","meaning_ko":"마이크로서비스"},{"word":"整合性","reading":"せいごうせい","meaning_ko":"정합성"},{"word":"並行稼動","reading":"へいこうかどう","meaning_ko":"병행 가동"},{"word":"パフォーマンス","reading":"パフォーマンス","meaning_ko":"성능"},{"word":"技術選定","reading":"ぎじゅつせんてい","meaning_ko":"기술 선정"},{"word":"志望","reading":"しぼう","meaning_ko":"지망"}]'::jsonb,
  '면접관: 오늘 잘 부탁드립니다. 먼저 전 직장에서의 프로젝트 경험에 대해 들려주세요.\n김: 전 직장에서는 EC사이트의 백엔드 개발을 담당했습니다. 마이크로서비스 아키텍처로의 이전 프로젝트에서 주로 API 설계와 데이터베이스 최적화를 수행했습니다.\n면접관: 팀 규모는 어느 정도였나요?\n김: 개발팀은 8명이었고 그 중 백엔드가 4명이었습니다. 스크럼 개발을 채용하고 있었으며 저는 스크럼 마스터도 겸임하고 있었습니다.\n면접관: 기술적으로 가장 고생한 점은 뭔가요?\n김: 레거시 시스템에서의 이전 시 데이터 정합성을 유지하는 것이 최대 과제였습니다. 단계적 이전 계획을 세우고 병행 가동 기간을 두어 다운타임을 거의 제로로 억제할 수 있었습니다.\n면접관: 저희 회사에서는 대규모 트래픽을 처리할 필요가 있는데 성능 튜닝 경험이 있나요?\n김: 네, 캐시 전략 재검토와 쿼리 최적화로 응답 시간을 40% 개선한 경험이 있습니다.\n면접관: 훌륭한 실적이네요. 마지막으로 왜 저희 회사를 지망하셨나요?\n김: 귀사의 클라우드 네이티브 기술 스택과 엔지니어가 주체적으로 기술 선정에 관여할 수 있는 문화에 매력을 느꼈습니다.\n면접관: 알겠습니다. 결과는 1주일 이내에 알려드리겠습니다.',
  21
);

-- N2-7: 新商品企画会議 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '新商品企画会議',
  '部長：では、新商品の企画会議を始めます。マーケティング部から市場調査の報告をお願いします。\n鈴木：調査の結果、二十代から三十代の女性をターゲットにした健康志向のスナック菓子に需要があることが分かりました。競合他社の分析では、低カロリーかつ高タンパクの商品が伸びています。\n佐藤：開発部の立場から言いますと、大豆プロテインを使用した菓子であれば、既存の製造ラインで対応可能です。\n部長：コスト面はどうですか。\n佐藤：原材料費は従来品より約二割増しになりますが、付加価値を考えれば、価格設定次第で十分採算が取れると思います。\n鈴木：パッケージデザインも重要です。SNSで映えるデザインにすることで、口コミでの拡散が期待できます。\n田中：販売チャネルについてですが、コンビニ限定で先行発売し、反応を見てからスーパーに展開するのはいかがでしょうか。\n部長：段階的な展開は理にかなっていますね。では、来月末までにプロトタイプを作って、社内試食会を行いましょう。\n佐藤：承知しました。三種類ほどフレーバーの候補を用意します。\n部長：発売目標は秋口ですので、スケジュール管理をしっかりお願いします。',
  'meeting',
  'N2',
  ARRAY['部長', '鈴木', '佐藤', '田中'],
  '食品メーカーの新商品企画会議',
  '[{"word":"市場調査","reading":"しじょうちょうさ","meaning_ko":"시장 조사"},{"word":"競合他社","reading":"きょうごうたしゃ","meaning_ko":"경쟁사"},{"word":"製造ライン","reading":"せいぞうライン","meaning_ko":"제조 라인"},{"word":"採算","reading":"さいさん","meaning_ko":"채산성"},{"word":"拡散","reading":"かくさん","meaning_ko":"확산"},{"word":"プロトタイプ","reading":"プロトタイプ","meaning_ko":"프로토타입"}]'::jsonb,
  '부장: 그러면 신상품 기획 회의를 시작합니다. 마케팅부에서 시장 조사 보고를 부탁합니다.\n스즈키: 조사 결과, 20~30대 여성을 타겟으로 한 건강 지향 스낵 과자에 수요가 있다는 것이 밝혀졌습니다. 경쟁사 분석에서는 저칼로리이면서 고단백 상품이 성장하고 있습니다.\n사토: 개발부 입장에서 말씀드리면, 대두 프로틴을 사용한 과자라면 기존 제조 라인으로 대응 가능합니다.\n부장: 비용면은 어떤가요?\n사토: 원재료비는 기존 제품보다 약 20% 증가하지만, 부가가치를 고려하면 가격 설정에 따라 충분히 채산이 맞을 것으로 생각합니다.\n스즈키: 패키지 디자인도 중요합니다. SNS에서 사진이 잘 나오는 디자인으로 하면 입소문 확산이 기대됩니다.\n다나카: 판매 채널에 대해서인데, 편의점 한정으로 선행 발매하고 반응을 본 후 슈퍼로 전개하는 것은 어떨까요?\n부장: 단계적 전개는 이치에 맞네요. 그러면 다음 달 말까지 프로토타입을 만들어 사내 시식회를 합시다.\n사토: 알겠습니다. 세 종류 정도 맛 후보를 준비하겠습니다.\n부장: 발매 목표는 초가을이니 일정 관리를 확실히 부탁합니다.',
  22
);

-- N2-8: 不動産投資セミナー (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '不動産投資セミナー',
  '講師：本日は「初めての不動産投資」というテーマでお話しします。不動産投資とは、マンションやアパートなどの物件を購入し、家賃収入を得る投資方法です。株式投資と比較すると、価格変動が緩やかで、安定した収入が期待できるのが特徴です。ただし、いくつかのリスクも存在します。まず、空室リスクです。入居者が見つからない期間はローンの返済が自己負担になります。次に、金利上昇リスクです。変動金利でローンを組んでいる場合、金利が上がると返済額が増えます。また、老朽化による修繕費も考慮に入れる必要があります。物件選びのポイントとしては、まず立地が重要です。駅から徒歩十分以内、周辺に商業施設や病院がある場所が望ましいです。築年数よりも管理状態が良い物件を選ぶことをお勧めします。初心者の方にはワンルームマンション投資から始めることをお勧めします。投資額が比較的少なく済み、管理の手間も少ないためです。',
  'monologue',
  'N2',
  ARRAY['講師'],
  '初心者向けの不動産投資セミナー',
  '[{"word":"不動産投資","reading":"ふどうさんとうし","meaning_ko":"부동산 투자"},{"word":"家賃収入","reading":"やちんしゅうにゅう","meaning_ko":"임대 수입"},{"word":"空室","reading":"くうしつ","meaning_ko":"빈 방"},{"word":"金利上昇","reading":"きんりじょうしょう","meaning_ko":"금리 상승"},{"word":"老朽化","reading":"ろうきゅうか","meaning_ko":"노후화"},{"word":"立地","reading":"りっち","meaning_ko":"입지"}]'::jsonb,
  '강사: 오늘은 "처음 하는 부동산 투자"라는 주제로 말씀드리겠습니다. 부동산 투자란 맨션이나 아파트 등의 물건을 구입하여 임대 수입을 얻는 투자 방법입니다. 주식 투자와 비교하면 가격 변동이 완만하고 안정적인 수입이 기대되는 것이 특징입니다. 다만 몇 가지 리스크도 존재합니다. 먼저 빈 방 리스크입니다. 입주자를 찾지 못하는 기간에는 대출 상환이 자기 부담이 됩니다. 다음으로 금리 상승 리스크입니다. 변동금리로 대출을 받고 있는 경우 금리가 오르면 상환액이 늘어납니다. 또한 노후화에 따른 수선비도 고려해야 합니다. 물건 선택의 포인트로는 우선 입지가 중요합니다. 역에서 도보 10분 이내, 주변에 상업시설이나 병원이 있는 곳이 바람직합니다. 건축 연수보다 관리 상태가 좋은 물건을 선택하는 것을 권합니다. 초보자 분에게는 원룸 맨션 투자부터 시작하는 것을 권합니다. 투자액이 비교적 적게 들고 관리 수고도 적기 때문입니다.',
  23
);

-- N2-9: 会社の労働組合の総会 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '会社の労働組合の総会',
  '委員長：それでは、労働組合の定期総会を開会いたします。まず、今期の活動報告です。春闘では基本給の二・五パーセントのベースアップを獲得しました。これは過去十年で最高の水準です。\n書記長：次に、福利厚生の改善についてです。有給休暇の取得率向上に取り組み、全社平均で七十パーセントを達成しました。また、育児休業の取得期間を最大二年に延長する制度改正が実現しました。\n組合員A：リモートワークの手当についてはどうなりましたか。\n委員長：交渉の結果、在宅勤務手当として月額五千円が支給されることになりました。ただし、出社日数が月の半分を超える場合は対象外です。\n組合員B：メンタルヘルスケアについて、もっと充実させてほしいのですが。\n書記長：来期の重点課題として、カウンセリング制度の拡充と、ストレスチェックの実施頻度を年二回に増やすことを経営側に提案しています。\n委員長：他にご意見やご質問はありますか。組合費の使途については、配布資料の四ページに詳細がございますので、ご確認ください。\n組合員A：残業時間の上限規制についてはどうですか。\n委員長：月四十五時間を厳守するよう、引き続き経営側に働きかけてまいります。',
  'meeting',
  'N2',
  ARRAY['委員長', '書記長', '組合員A', '組合員B'],
  '会社の労働組合の定期総会',
  '[{"word":"労働組合","reading":"ろうどうくみあい","meaning_ko":"노동조합"},{"word":"春闘","reading":"しゅんとう","meaning_ko":"춘투(봄철 임금 투쟁)"},{"word":"ベースアップ","reading":"ベースアップ","meaning_ko":"기본급 인상"},{"word":"有給休暇","reading":"ゆうきゅうきゅうか","meaning_ko":"유급 휴가"},{"word":"育児休業","reading":"いくじきゅうぎょう","meaning_ko":"육아 휴직"},{"word":"ストレスチェック","reading":"ストレスチェック","meaning_ko":"스트레스 검사"}]'::jsonb,
  '위원장: 그러면 노동조합 정기총회를 개회하겠습니다. 먼저 금기 활동 보고입니다. 춘투에서 기본급 2.5% 인상을 획득했습니다. 이것은 과거 10년간 최고 수준입니다.\n서기장: 다음으로 복리후생 개선에 대해서입니다. 유급 휴가 취득률 향상에 힘써 전사 평균 70%를 달성했습니다. 또한 육아 휴직 취득 기간을 최대 2년으로 연장하는 제도 개정이 실현되었습니다.\n조합원A: 원격근무 수당에 대해서는 어떻게 됐나요?\n위원장: 교섭 결과, 재택근무 수당으로 월 5,000엔이 지급되게 되었습니다. 다만 출근 일수가 월의 절반을 넘는 경우는 대상 외입니다.\n조합원B: 정신건강 케어에 대해 더 충실히 해주셨으면 하는데요.\n서기장: 내기 중점 과제로 상담 제도 확충과 스트레스 검사 실시 빈도를 연 2회로 늘리는 것을 경영 측에 제안하고 있습니다.\n위원장: 다른 의견이나 질문 있으신가요? 조합비 사용처에 대해서는 배포 자료 4페이지에 상세가 있으니 확인해 주세요.\n조합원A: 잔업 시간 상한 규제에 대해서는 어떤가요?\n위원장: 월 45시간을 엄수하도록 계속해서 경영 측에 요구해 나가겠습니다.',
  24
);

-- N2-10: 外国人向け生活ガイダンス (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '外国人向け生活ガイダンス',
  '担当者：皆さん、日本での生活を始めるにあたって、いくつかの重要な手続きについてご説明します。まず、住民登録です。入国後十四日以内に、お住まいの市区町村の役所で転入届を出してください。次に、健康保険への加入です。国民健康保険に加入すると、医療費の自己負担が三割になります。保険料は所得に応じて決まります。銀行口座の開設には、在留カードと印鑑が必要です。印鑑がない場合はサインで対応してくれる銀行もあります。携帯電話の契約は、在留期間が一年以上であれば、大手キャリアでの契約が可能です。短期の方は格安SIMをお勧めします。ゴミの分別ルールは自治体によって異なりますので、お住まいの地域のルールを必ず確認してください。最後に、緊急時の連絡先です。警察は一一〇番、消防・救急は一一九番です。災害時には各自治体の防災アプリをインストールしておくと便利です。何かお困りのことがあれば、外国人総合相談センターにお電話ください。多言語で対応しております。',
  'instruction',
  'N2',
  ARRAY['担当者'],
  '自治体主催の外国人向け生活オリエンテーション',
  '[{"word":"住民登録","reading":"じゅうみんとうろく","meaning_ko":"주민 등록"},{"word":"国民健康保険","reading":"こくみんけんこうほけん","meaning_ko":"국민건강보험"},{"word":"自己負担","reading":"じこふたん","meaning_ko":"자기 부담"},{"word":"在留カード","reading":"ざいりゅうカード","meaning_ko":"재류카드"},{"word":"自治体","reading":"じちたい","meaning_ko":"지자체"},{"word":"多言語","reading":"たげんご","meaning_ko":"다국어"}]'::jsonb,
  '담당자: 여러분, 일본에서의 생활을 시작하면서 몇 가지 중요한 절차에 대해 설명합니다. 먼저 주민 등록입니다. 입국 후 14일 이내에 거주지의 시구정촌 관공서에서 전입신고를 내주세요. 다음으로 건강보험 가입입니다. 국민건강보험에 가입하면 의료비 자기 부담이 30%가 됩니다. 보험료는 소득에 따라 정해집니다. 은행 계좌 개설에는 재류카드와 도장이 필요합니다. 도장이 없는 경우 서명으로 대응해 주는 은행도 있습니다. 휴대전화 계약은 재류 기간이 1년 이상이면 대형 통신사 계약이 가능합니다. 단기인 분은 격안 SIM을 권합니다. 쓰레기 분리 규칙은 지자체마다 다르니 거주 지역의 규칙을 반드시 확인해 주세요. 마지막으로 긴급 시 연락처입니다. 경찰은 110번, 소방·구급은 119번입니다. 재해 시에는 각 지자체의 방재 앱을 설치해 두면 편리합니다. 곤란한 일이 있으시면 외국인 종합상담센터에 전화해 주세요. 다국어로 대응하고 있습니다.',
  25
);

-- N2-11: ビジネスプレゼンテーション (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ビジネスプレゼンテーション',
  'キム：本日は弊社の業務効率化ソリューションについてプレゼンテーションさせていただきます。現在、多くの企業が手作業による非効率なプロセスを抱えています。弊社のシステムを導入していただくことで、書類作成時間を平均四十パーセント削減できます。具体的な機能としましては、まず、AIを活用した自動書類生成機能がございます。テンプレートを一度設定すれば、データを入力するだけで各種書類が自動的に作成されます。次に、ワークフロー管理機能です。承認フローを電子化し、どこからでもスマートフォンで承認が可能になります。導入事例といたしましては、A社様では年間千時間の労働時間削減を達成されました。B社様では、ペーパーレス化により印刷コストを八十パーセント削減されています。料金プランは三種類ご用意しております。基本プランは月額五万円から、スタンダードプランは十万円から、エンタープライズプランは個別見積もりとなっております。導入後のサポートも充実しておりまして、専任の担当者がつきます。ご質問やデモのご要望がございましたら、お気軽にお問い合わせください。',
  'monologue',
  'N2',
  ARRAY['キム'],
  '取引先へのビジネスソリューションのプレゼンテーション',
  '[{"word":"業務効率化","reading":"ぎょうむこうりつか","meaning_ko":"업무 효율화"},{"word":"ソリューション","reading":"ソリューション","meaning_ko":"솔루션"},{"word":"ワークフロー","reading":"ワークフロー","meaning_ko":"워크플로"},{"word":"ペーパーレス","reading":"ペーパーレス","meaning_ko":"페이퍼리스"},{"word":"専任","reading":"せんにん","meaning_ko":"전임"},{"word":"見積もり","reading":"みつもり","meaning_ko":"견적"}]'::jsonb,
  '김: 오늘은 저희 회사의 업무 효율화 솔루션에 대해 프레젠테이션하겠습니다. 현재 많은 기업이 수작업에 의한 비효율적인 프로세스를 안고 있습니다. 저희 시스템을 도입하시면 서류 작성 시간을 평균 40% 삭감할 수 있습니다. 구체적인 기능으로는 먼저 AI를 활용한 자동 서류 생성 기능이 있습니다. 템플릿을 한번 설정하면 데이터를 입력하기만 하면 각종 서류가 자동으로 작성됩니다. 다음으로 워크플로 관리 기능입니다. 승인 플로를 전자화하여 어디서든 스마트폰으로 승인이 가능해집니다. 도입 사례로는 A사에서는 연간 1,000시간의 노동시간 삭감을 달성했습니다. B사에서는 페이퍼리스화를 통해 인쇄 비용을 80% 삭감했습니다. 요금 플랜은 3종류 준비하고 있습니다. 기본 플랜은 월 5만 엔부터, 스탠다드 플랜은 10만 엔부터, 엔터프라이즈 플랜은 개별 견적입니다. 도입 후 서포트도 충실하여 전임 담당자가 붙습니다. 질문이나 데모 요망이 있으시면 편하게 문의해 주세요.',
  26
);

-- N2-12: 保険の相談 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '保険の相談',
  '担当者：本日はどのような保険をお考えですか。\nキム：日本に来たばかりなので、基本的な生命保険について相談したいのですが。\n担当者：承知しました。まず、日本の公的保険制度はご存知ですか。\nキム：国民健康保険には加入しています。\n担当者：国民健康保険で医療費の七割はカバーされますが、入院が長引いた場合の差額ベッド代や、先進医療の費用は自己負担になります。\nキム：どのくらいの保障があればいいですか。\n担当者：一般的には、入院日額五千円から一万円程度をお勧めしています。また、万が一のことを考えると、死亡保障も検討されたほうがいいでしょう。\nキム：帰国した場合、保険はどうなりますか。\n担当者：こちらの商品は海外でも保障が継続します。保険金の請求も日本語と英語で対応しております。\nキム：保険料は月いくらですか。\n担当者：お客様の年齢ですと、医療保険と死亡保障を合わせて月額六千円程度です。\nキム：考えさせてください。資料をいただけますか。\n担当者：もちろんです。こちらのパンフレットをお持ちください。',
  'dialogue',
  'N2',
  ARRAY['担当者', 'キム'],
  '保険代理店で生命保険について相談する場面',
  '[{"word":"生命保険","reading":"せいめいほけん","meaning_ko":"생명보험"},{"word":"差額ベッド代","reading":"さがくベッドだい","meaning_ko":"차액 병실료"},{"word":"先進医療","reading":"せんしんいりょう","meaning_ko":"선진 의료"},{"word":"保障","reading":"ほしょう","meaning_ko":"보장"},{"word":"死亡保障","reading":"しぼうほしょう","meaning_ko":"사망 보장"},{"word":"保険金","reading":"ほけんきん","meaning_ko":"보험금"}]'::jsonb,
  '담당자: 오늘은 어떤 보험을 생각하고 계세요?\n김: 일본에 온 지 얼마 안 돼서 기본적인 생명보험에 대해 상담하고 싶은데요.\n담당자: 알겠습니다. 먼저 일본의 공적보험 제도는 알고 계세요?\n김: 국민건강보험에는 가입해 있어요.\n담당자: 국민건강보험으로 의료비의 70%는 커버되지만, 입원이 길어진 경우의 차액 병실료나 선진 의료 비용은 자기 부담이 됩니다.\n김: 어느 정도의 보장이 있으면 되나요?\n담당자: 일반적으로 입원 일당 5,000엔에서 10,000엔 정도를 권합니다. 또한 만약의 경우를 생각하면 사망 보장도 검토하시는 게 좋겠습니다.\n김: 귀국한 경우 보험은 어떻게 되나요?\n담당자: 이 상품은 해외에서도 보장이 계속됩니다. 보험금 청구도 일본어와 영어로 대응하고 있습니다.\n김: 보험료는 월 얼마인가요?\n담당자: 고객님의 나이면 의료보험과 사망 보장을 합쳐 월 6,000엔 정도입니다.\n김: 생각해 볼게요. 자료를 받을 수 있나요?\n담당자: 물론입니다. 이 팸플릿을 가져가세요.',
  27
);

-- N2-13: 災害ボランティアの説明会 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '災害ボランティアの説明会',
  'コーディネーター：本日は災害ボランティアの事前説明会にお越しいただきありがとうございます。先月の豪雨災害で被災した地域の復旧支援に参加していただきます。活動内容は、泥のかき出し、家財道具の運び出し、床下の清掃などです。活動時間は午前九時から午後三時までです。休憩は一時間ごとに十五分取ってください。熱中症対策として、こまめに水分を補給してください。服装は長袖、長ズボン、長靴を着用してください。マスクとゴーグルも必ずつけてください。作業中に体調が悪くなった場合は、無理をせずすぐにスタッフに申し出てください。被災された方への接し方についてですが、こちらから声をかける必要はありません。声をかけられたら、丁寧に対応してください。写真撮影やSNSへの投稿は、被災者のプライバシー保護のため、原則禁止です。ボランティア保険に加入していない方は、本日受付で加入してください。費用は五百円です。何かご質問はありますか。',
  'instruction',
  'N2',
  ARRAY['コーディネーター'],
  '災害ボランティアの事前説明会',
  '[{"word":"豪雨","reading":"ごうう","meaning_ko":"폭우"},{"word":"被災","reading":"ひさい","meaning_ko":"이재"},{"word":"復旧支援","reading":"ふっきゅうしえん","meaning_ko":"복구 지원"},{"word":"家財道具","reading":"かざいどうぐ","meaning_ko":"가재도구"},{"word":"熱中症","reading":"ねっちゅうしょう","meaning_ko":"열사병"},{"word":"プライバシー","reading":"プライバシー","meaning_ko":"프라이버시"}]'::jsonb,
  '코디네이터: 오늘은 재해 자원봉사 사전 설명회에 와주셔서 감사합니다. 지난달 폭우 재해로 피해를 입은 지역의 복구 지원에 참가해 주시게 됩니다. 활동 내용은 진흙 제거, 가재도구 반출, 바닥 밑 청소 등입니다. 활동 시간은 오전 9시부터 오후 3시까지입니다. 휴식은 1시간마다 15분씩 취해 주세요. 열사병 대책으로 꼼꼼하게 수분을 보충해 주세요. 복장은 긴소매, 긴바지, 장화를 착용해 주세요. 마스크와 고글도 반드시 착용하세요. 작업 중 컨디션이 나빠지면 무리하지 말고 바로 스탭에게 알려주세요. 피해를 입은 분들에 대한 접근 방법인데, 이쪽에서 먼저 말을 걸 필요는 없습니다. 말을 걸어오시면 정중히 대응해 주세요. 사진 촬영이나 SNS 게시는 피재자의 프라이버시 보호를 위해 원칙 금지입니다. 자원봉사 보험에 가입하지 않으신 분은 오늘 접수에서 가입해 주세요. 비용은 500엔입니다. 질문 있으신가요?',
  28
);

-- N2-14: 確定申告の相談 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '確定申告の相談',
  'キム：すみません、確定申告について相談したいのですが。\n職員：はい、どのようなご質問ですか。\nキム：会社員ですが、副業の収入があります。確定申告は必要ですか。\n職員：副業の収入が年間二十万円を超える場合は、確定申告が必要です。いくらぐらいの収入がありましたか。\nキム：フリーランスでウェブサイトの制作を受けまして、年間五十万円ほどの収入がありました。\n職員：では、確定申告が必要ですね。経費は計上されていますか。\nキム：パソコンやソフトウェアの購入費は経費になりますか。\n職員：はい、業務に使用するものであれば経費として認められます。領収書は保管してありますか。\nキム：はい、全部取ってあります。\n職員：確定申告の期間は二月十六日から三月十五日までです。電子申告のe-Taxを使えば、自宅からオンラインで申告できますよ。\nキム：マイナンバーカードは必要ですか。\n職員：e-Taxを利用する場合は必要です。お持ちでなければ、税務署に直接提出することもできます。\nキム：還付金はいつ頃振り込まれますか。\n職員：申告から一か月から一か月半程度で指定の口座に振り込まれます。',
  'dialogue',
  'N2',
  ARRAY['キム', '職員'],
  '税務署で確定申告について相談する場面',
  '[{"word":"確定申告","reading":"かくていしんこく","meaning_ko":"확정 신고"},{"word":"副業","reading":"ふくぎょう","meaning_ko":"부업"},{"word":"経費","reading":"けいひ","meaning_ko":"경비"},{"word":"計上","reading":"けいじょう","meaning_ko":"계상"},{"word":"領収書","reading":"りょうしゅうしょ","meaning_ko":"영수증"},{"word":"還付金","reading":"かんぷきん","meaning_ko":"환급금"}]'::jsonb,
  '김: 실례합니다, 확정 신고에 대해 상담하고 싶은데요.\n직원: 네, 어떤 질문이세요?\n김: 회사원인데 부업 수입이 있어요. 확정 신고가 필요한가요?\n직원: 부업 수입이 연간 20만 엔을 초과하는 경우 확정 신고가 필요합니다. 얼마 정도의 수입이 있었나요?\n김: 프리랜서로 웹사이트 제작을 받아서 연간 50만 엔 정도의 수입이 있었어요.\n직원: 그러면 확정 신고가 필요하네요. 경비는 계상하셨나요?\n김: 컴퓨터나 소프트웨어 구입비는 경비가 되나요?\n직원: 네, 업무에 사용하는 것이라면 경비로 인정됩니다. 영수증은 보관해 두셨나요?\n김: 네, 전부 가지고 있어요.\n직원: 확정 신고 기간은 2월 16일부터 3월 15일까지입니다. 전자 신고 e-Tax를 사용하면 자택에서 온라인으로 신고할 수 있어요.\n김: 마이넘버 카드가 필요한가요?\n직원: e-Tax를 이용하는 경우 필요합니다. 가지고 계시지 않으면 세무서에 직접 제출할 수도 있습니다.\n김: 환급금은 언제쯤 입금되나요?\n직원: 신고 후 1개월에서 1개월 반 정도에 지정 계좌로 입금됩니다.',
  29
);

-- N2-15: 社内コンプライアンス研修 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '社内コンプライアンス研修',
  '講師：本日はコンプライアンス研修として、ハラスメント防止について学びます。ハラスメントには、パワーハラスメント、セクシュアルハラスメント、マタニティハラスメントなどがあります。パワハラの典型的な例としては、人格を否定するような暴言、業務上不必要な叱責、過大な要求や逆に仕事を与えないことなどが挙げられます。上司と部下の関係だけでなく、同僚間や部下から上司への行為も該当する場合があります。セクハラについては、性的な言動によって相手に不快感を与える行為全般が含まれます。外見に関する不必要なコメントや、プライベートな質問の強要も対象です。ハラスメントを受けた場合、または目撃した場合は、社内の相談窓口に報告してください。匿名での相談も可能です。報復行為は厳しく禁止されていますので、安心して相談してください。加害者には厳正な処分が下されます。一人一人がお互いの人格を尊重し、働きやすい職場環境を作ることが、私たち全員の責任です。',
  'instruction',
  'N2',
  ARRAY['講師'],
  '会社のコンプライアンス研修でハラスメント防止を学ぶ場面',
  '[{"word":"コンプライアンス","reading":"コンプライアンス","meaning_ko":"컴플라이언스(법규 준수)"},{"word":"ハラスメント","reading":"ハラスメント","meaning_ko":"괴롭힘"},{"word":"叱責","reading":"しっせき","meaning_ko":"질책"},{"word":"該当","reading":"がいとう","meaning_ko":"해당"},{"word":"匿名","reading":"とくめい","meaning_ko":"익명"},{"word":"報復","reading":"ほうふく","meaning_ko":"보복"}]'::jsonb,
  '강사: 오늘은 컴플라이언스 연수로서 괴롭힘 방지에 대해 학습합니다. 괴롭힘에는 파워 하라스먼트, 성희롱, 임산부 괴롭힘 등이 있습니다. 파워하라의 전형적인 예로는 인격을 부정하는 폭언, 업무상 불필요한 질책, 과도한 요구나 반대로 일을 주지 않는 것 등이 있습니다. 상사와 부하 관계뿐만 아니라 동료 간이나 부하에서 상사에 대한 행위도 해당하는 경우가 있습니다. 성희롱에 대해서는 성적인 언동으로 상대에게 불쾌감을 주는 행위 전반이 포함됩니다. 외모에 관한 불필요한 코멘트나 사적인 질문 강요도 대상입니다. 괴롭힘을 당한 경우 또는 목격한 경우에는 사내 상담 창구에 보고해 주세요. 익명 상담도 가능합니다. 보복 행위는 엄격히 금지되어 있으니 안심하고 상담해 주세요. 가해자에게는 엄정한 처분이 내려집니다. 한 사람 한 사람이 서로의 인격을 존중하고 일하기 쉬운 직장 환경을 만드는 것이 우리 모두의 책임입니다.',
  30
);

-- ============================================
-- N1 Additional Scripts (sort_order 26-30)
-- ============================================

-- N1-6: AI倫理に関する学会討論 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'AI倫理に関する学会討論',
  '座長：本セッションでは「人工知能の倫理的課題と法的規制の在り方」について討論いたします。まず、基調報告として、東京工業大学の中村教授にお願いします。\n中村教授：ありがとうございます。生成AIの急速な発展に伴い、著作権侵害、偽情報の拡散、雇用への影響など、多岐にわたる倫理的問題が顕在化しております。特に懸念されるのは、AIの判断過程がブラックボックス化している点です。医療診断や与信審査など、人間の生活に重大な影響を与える領域でAIが活用される際、その判断根拠の透明性をいかに確保するかが喫緊の課題です。\n山田教授：法学の立場から申し上げますと、現行の法体系ではAIが生成したコンテンツの権利帰属が曖昧であり、早急な法整備が求められています。EUのAI規制法を参考にしつつも、日本の産業競争力を損なわない形での規制の枠組みを構築する必要があります。\n企業代表：産業界としましては、過度な規制がイノベーションを阻害することを懸念しております。自主規制と法的規制のバランスが重要であり、業界ごとのガイドラインの策定と、それを監督する第三者機関の設置が現実的な解決策ではないかと考えます。\n中村教授：自主規制には限界があるという点は認識しておく必要があります。AIの開発競争が激化する中で、倫理的配慮が後回しにされるリスクは常に存在します。\n座長：活発なご議論ありがとうございます。技術の進歩と社会的責任の両立は、今後も継続的に議論していくべき課題ですね。',
  'meeting',
  'N1',
  ARRAY['座長', '中村教授', '山田教授', '企業代表'],
  'AI倫理と法規制に関する学術会議のパネルディスカッション',
  '[{"word":"倫理","reading":"りんり","meaning_ko":"윤리"},{"word":"喫緊","reading":"きっきん","meaning_ko":"긴급한"},{"word":"権利帰属","reading":"けんりきぞく","meaning_ko":"권리 귀속"},{"word":"法整備","reading":"ほうせいび","meaning_ko":"법 정비"},{"word":"阻害","reading":"そがい","meaning_ko":"저해"},{"word":"第三者機関","reading":"だいさんしゃきかん","meaning_ko":"제3자 기관"}]'::jsonb,
  '좌장: 이 세션에서는 "인공지능의 윤리적 과제와 법적 규제의 방향"에 대해 토론하겠습니다. 먼저 기조 보고로 도쿄공업대학 나카무라 교수님께 부탁드립니다.\n나카무라 교수: 감사합니다. 생성 AI의 급속한 발전에 따라 저작권 침해, 허위 정보 확산, 고용에 대한 영향 등 다방면에 걸친 윤리적 문제가 현재화하고 있습니다. 특히 우려되는 것은 AI의 판단 과정이 블랙박스화되고 있는 점입니다. 의료 진단이나 여신 심사 등 인간 생활에 중대한 영향을 미치는 영역에서 AI가 활용될 때, 그 판단 근거의 투명성을 어떻게 확보할 것인가가 긴급 과제입니다.\n야마다 교수: 법학의 입장에서 말씀드리면, 현행 법체계에서는 AI가 생성한 콘텐츠의 권리 귀속이 모호하며, 조속한 법 정비가 요구되고 있습니다. EU의 AI 규제법을 참고하면서도 일본의 산업 경쟁력을 훼손하지 않는 형태의 규제 프레임워크를 구축할 필요가 있습니다.\n기업 대표: 산업계로서는 과도한 규제가 혁신을 저해하는 것을 우려하고 있습니다. 자율 규제와 법적 규제의 균형이 중요하며, 업종별 가이드라인 책정과 그것을 감독하는 제3자 기관 설치가 현실적인 해결책이 아닌가 생각합니다.\n나카무라 교수: 자율 규제에는 한계가 있다는 점은 인식해 둘 필요가 있습니다. AI 개발 경쟁이 격화되는 가운데 윤리적 배려가 뒤로 밀리는 리스크는 항상 존재합니다.\n좌장: 활발한 토론 감사합니다. 기술의 진보와 사회적 책임의 양립은 앞으로도 지속적으로 논의해야 할 과제입니다.',
  26
);

-- N1-7: 医療倫理委員会の審議 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '医療倫理委員会の審議',
  '委員長：本日の医療倫理委員会では、遺伝子治療の臨床試験申請について審議いたします。申請者の佐藤教授、概要をご説明ください。\n佐藤教授：ありがとうございます。本研究は、遺伝性の筋ジストロフィーに対する遺伝子治療の安全性と有効性を検証するものです。対象は十歳以上の患者で、従来の治療法では十分な効果が得られなかった方を対象とします。\n外部委員：インフォームドコンセントの手続きについて伺います。未成年の患者が含まれますが、本人の同意と保護者の同意はどのように取得されますか。\n佐藤教授：十六歳以上の患者には本人からも書面での同意を取得します。十歳から十五歳の患者については、保護者の同意に加え、年齢に応じた説明を行い、本人の理解と賛同を得ます。\n法律委員：万が一、重篤な副作用が発生した場合の補償制度はどのようになっていますか。\n佐藤教授：臨床試験保険に加入しており、治療に起因する健康被害については、過失の有無にかかわらず補償する体制を整えております。\n委員長：データの管理体制についてはいかがですか。遺伝情報は極めて機密性の高い個人情報ですが。\n佐藤教授：すべてのデータは匿名化処理を施し、アクセス権限は研究責任者と指定された研究員のみに限定しております。\n委員長：条件付きで承認とし、三か月ごとの中間報告を義務付けることを提案します。異議のある方はいらっしゃいますか。',
  'meeting',
  'N1',
  ARRAY['委員長', '佐藤教授', '外部委員', '法律委員'],
  '大学病院の医療倫理委員会での遺伝子治療臨床試験の審議',
  '[{"word":"臨床試験","reading":"りんしょうしけん","meaning_ko":"임상 시험"},{"word":"インフォームドコンセント","reading":"インフォームドコンセント","meaning_ko":"인폼드 컨센트(설명에 의한 동의)"},{"word":"重篤","reading":"じゅうとく","meaning_ko":"중독(중증)"},{"word":"補償","reading":"ほしょう","meaning_ko":"보상"},{"word":"匿名化","reading":"とくめいか","meaning_ko":"익명화"},{"word":"中間報告","reading":"ちゅうかんほうこく","meaning_ko":"중간 보고"}]'::jsonb,
  '위원장: 오늘 의료윤리위원회에서는 유전자 치료 임상시험 신청에 대해 심의합니다. 신청자인 사토 교수님, 개요를 설명해 주세요.\n사토 교수: 감사합니다. 본 연구는 유전성 근디스트로피에 대한 유전자 치료의 안전성과 유효성을 검증하는 것입니다. 대상은 10세 이상 환자로, 기존 치료법으로 충분한 효과를 얻지 못한 분을 대상으로 합니다.\n외부 위원: 인폼드 컨센트 절차에 대해 여쭙겠습니다. 미성년 환자가 포함되는데 본인의 동의와 보호자의 동의는 어떻게 취득하나요?\n사토 교수: 16세 이상 환자에게는 본인으로부터도 서면 동의를 취득합니다. 10세에서 15세 환자에 대해서는 보호자 동의에 더해 연령에 맞는 설명을 하고 본인의 이해와 찬동을 얻습니다.\n법률 위원: 만약 중증 부작용이 발생한 경우 보상 제도는 어떻게 되어 있나요?\n사토 교수: 임상시험 보험에 가입하고 있으며, 치료에 기인하는 건강 피해에 대해서는 과실 유무에 관계없이 보상하는 체제를 갖추고 있습니다.\n위원장: 데이터 관리 체제는 어떤가요? 유전 정보는 극히 기밀성이 높은 개인정보인데요.\n사토 교수: 모든 데이터는 익명화 처리를 하고, 접근 권한은 연구 책임자와 지정된 연구원만으로 한정하고 있습니다.\n위원장: 조건부 승인으로 하고 3개월마다 중간 보고를 의무화하는 것을 제안합니다. 이의 있으신 분 계신가요?',
  27
);

-- N1-8: 日本企業の海外展開戦略 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本企業の海外展開戦略',
  '講演者：本日は「日本の中小企業における海外展開の課題と戦略」についてお話しします。経済のグローバル化が進む中、国内市場の縮小に直面する中小企業にとって、海外展開は成長戦略の重要な柱となっています。しかしながら、中小企業が海外市場に参入する際には、多くの障壁が存在します。第一に、現地の法規制や商慣習への対応です。各国の規制は複雑かつ頻繁に改正されるため、専門家との連携が不可欠です。第二に、人材の確保です。語学力に加え、異文化コミュニケーション能力を持つ人材の育成が急務です。第三に、資金調達の問題があります。海外展開には初期投資が必要であり、公的支援制度の活用が有効です。JETROや各自治体の支援プログラムを積極的に活用すべきでしょう。成功事例として、東北地方の食品メーカーがASEAN市場への進出に成功した例を紹介します。この企業は、現地パートナーとの合弁事業という形態を選択し、リスクを分散させながら市場開拓を行いました。味付けを現地の嗜好に合わせてカスタマイズし、かつ「日本品質」というブランド価値を維持するという、ローカライゼーションとスタンダード化のバランスが奏功しました。重要なのは、海外展開を単なる販路拡大ではなく、企業のイノベーション創出の機会と捉えることです。',
  'monologue',
  'N1',
  ARRAY['講演者'],
  '中小企業の海外展開に関する経営セミナーの講演',
  '[{"word":"海外展開","reading":"かいがいてんかい","meaning_ko":"해외 진출"},{"word":"商慣習","reading":"しょうかんしゅう","meaning_ko":"상관습"},{"word":"異文化","reading":"いぶんか","meaning_ko":"이문화"},{"word":"合弁事業","reading":"ごうべんじぎょう","meaning_ko":"합작 사업"},{"word":"嗜好","reading":"しこう","meaning_ko":"기호"},{"word":"奏功","reading":"そうこう","meaning_ko":"주효함"}]'::jsonb,
  '강연자: 오늘은 "일본 중소기업의 해외 진출 과제와 전략"에 대해 말씀드리겠습니다. 경제의 글로벌화가 진행되는 가운데, 국내 시장 축소에 직면한 중소기업에게 해외 진출은 성장 전략의 중요한 기둥이 되고 있습니다. 그러나 중소기업이 해외 시장에 참입할 때에는 많은 장벽이 존재합니다. 첫째, 현지 법규제와 상관습에 대한 대응입니다. 각국의 규제는 복잡하고 빈번하게 개정되므로 전문가와의 연계가 불가결합니다. 둘째, 인재 확보입니다. 어학력에 더해 이문화 커뮤니케이션 능력을 가진 인재 육성이 급선무입니다. 셋째, 자금 조달 문제가 있습니다. 해외 진출에는 초기 투자가 필요하며 공적 지원 제도의 활용이 유효합니다. JETRO나 각 지자체의 지원 프로그램을 적극 활용해야 할 것입니다. 성공 사례로 도호쿠 지방 식품 제조사가 ASEAN 시장 진출에 성공한 예를 소개합니다. 이 기업은 현지 파트너와의 합작 사업이라는 형태를 선택하여 리스크를 분산시키면서 시장 개척을 했습니다. 맛을 현지 기호에 맞추어 커스터마이즈하고, 동시에 "일본 품질"이라는 브랜드 가치를 유지하는, 로컬라이제이션과 표준화의 균형이 주효했습니다. 중요한 것은 해외 진출을 단순한 판로 확대가 아닌 기업의 혁신 창출 기회로 파악하는 것입니다.',
  28
);

-- N1-9: 裁判員制度の説明会 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '裁判員制度の説明会',
  '裁判官：本日は裁判員制度についてご説明いたします。裁判員制度とは、国民の中から無作為に選ばれた裁判員が、裁判官とともに刑事裁判に参加する制度です。裁判員は原則として六名が選任され、三名の裁判官と合議体を構成します。対象となる事件は、殺人、強盗致死傷、放火など、重大な犯罪に限定されています。裁判員の義務としましては、公判に出席すること、評議に参加して意見を述べること、そして守秘義務があります。評議の内容や、各裁判員がどのような意見を述べたかは、生涯にわたって秘密にしていただく必要があります。裁判員を辞退できる場合としましては、七十歳以上の方、学生、重い病気や介護の事情がある方などが認められています。日当は一日一万円以内、交通費も支給されます。裁判員裁判では、法律の専門知識は必要ありません。皆さまの社会経験や良識に基づいた判断をしていただくことが求められています。証拠に基づいて、被告人が有罪か無罪かを判断し、有罪の場合はどのような刑罰が適切かを裁判官とともに決定していただきます。',
  'instruction',
  'N1',
  ARRAY['裁判官'],
  '裁判員候補者への裁判員制度の説明会',
  '[{"word":"裁判員","reading":"さいばんいん","meaning_ko":"재판원"},{"word":"無作為","reading":"むさくい","meaning_ko":"무작위"},{"word":"合議体","reading":"ごうぎたい","meaning_ko":"합의체"},{"word":"守秘義務","reading":"しゅひぎむ","meaning_ko":"비밀 유지 의무"},{"word":"辞退","reading":"じたい","meaning_ko":"사퇴"},{"word":"被告人","reading":"ひこくにん","meaning_ko":"피고인"}]'::jsonb,
  '재판관: 오늘은 재판원 제도에 대해 설명드리겠습니다. 재판원 제도란 국민 중에서 무작위로 선발된 재판원이 재판관과 함께 형사재판에 참가하는 제도입니다. 재판원은 원칙적으로 6명이 선임되며, 3명의 재판관과 합의체를 구성합니다. 대상이 되는 사건은 살인, 강도치사상, 방화 등 중대한 범죄로 한정되어 있습니다. 재판원의 의무로는 공판에 출석하는 것, 평의에 참가하여 의견을 말하는 것, 그리고 비밀 유지 의무가 있습니다. 평의 내용이나 각 재판원이 어떤 의견을 말했는지는 평생에 걸쳐 비밀로 해주셔야 합니다. 재판원을 사퇴할 수 있는 경우로는 70세 이상인 분, 학생, 중병이나 간호 사정이 있는 분 등이 인정됩니다. 일당은 하루 1만 엔 이내이며 교통비도 지급됩니다. 재판원 재판에서는 법률 전문 지식은 필요하지 않습니다. 여러분의 사회 경험과 양식에 기반한 판단을 해주시는 것이 요구됩니다. 증거에 기초하여 피고인이 유죄인지 무죄인지를 판단하고, 유죄의 경우 어떤 형벌이 적절한지를 재판관과 함께 결정해 주시게 됩니다.',
  29
);

-- N1-10: 日本の人口問題に関する国会答弁 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本の人口問題に関する国会答弁',
  '議員：少子化対策について伺います。合計特殊出生率は過去最低の一・二〇を記録しました。政府はこの危機的状況をどのように認識し、いかなる対策を講じる考えですか。\n大臣：ご指摘の通り、少子化は我が国が直面する最重要課題の一つであると認識しております。政府としましては、「次元の異なる少子化対策」として、三つの柱で取り組んでまいります。第一に、経済的支援の拡充です。児童手当の所得制限撤廃と支給額の引き上げを来年度から実施いたします。第二に、子育てと仕事の両立支援です。育児休業給付金の引き上げと、男性の育休取得率を二〇三〇年までに八十五パーセントに引き上げることを目標としています。第三に、教育費の負担軽減です。高等教育の無償化対象を拡大し、奨学金制度の充実を図ります。\n議員：問題は、これまでも類似の対策を講じてきたにもかかわらず、出生率の低下に歯止めがかかっていないことです。根本的な要因は、若者の将来に対する漠然とした不安にあるのではないでしょうか。雇用の不安定化、実質賃金の低下、社会保障への不信感、これらの構造的問題に切り込まなければ、小手先の対策では効果は限定的です。\n大臣：ご指摘は真摯に受け止めます。雇用の安定化と賃上げの推進は、少子化対策の基盤として不可欠であると考えており、経済政策と一体的に推進してまいります。',
  'dialogue',
  'N1',
  ARRAY['議員', '大臣'],
  '国会の委員会で少子化対策について質疑応答する場面',
  '[{"word":"合計特殊出生率","reading":"ごうけいとくしゅしゅっしょうりつ","meaning_ko":"합계특수출생률"},{"word":"次元の異なる","reading":"じげんのことなる","meaning_ko":"차원이 다른"},{"word":"児童手当","reading":"じどうてあて","meaning_ko":"아동수당"},{"word":"奨学金","reading":"しょうがくきん","meaning_ko":"장학금"},{"word":"歯止め","reading":"はどめ","meaning_ko":"억제"},{"word":"小手先","reading":"こてさき","meaning_ko":"소수단, 미봉책"}]'::jsonb,
  '의원: 저출산 대책에 대해 여쭙겠습니다. 합계특수출생률은 역대 최저인 1.20을 기록했습니다. 정부는 이 위기적 상황을 어떻게 인식하고 어떤 대책을 마련할 생각이십니까?\n대신: 지적하신 대로, 저출산은 우리나라가 직면한 최중요 과제 중 하나라고 인식하고 있습니다. 정부로서는 "차원이 다른 저출산 대책"으로 세 가지 기둥으로 힘쓰겠습니다. 첫째, 경제적 지원 확충입니다. 아동수당의 소득 제한 철폐와 지급액 인상을 내년도부터 실시합니다. 둘째, 육아와 일의 양립 지원입니다. 육아휴직 급여금 인상과 남성의 육휴 취득률을 2030년까지 85%로 끌어올리는 것을 목표로 하고 있습니다. 셋째, 교육비 부담 경감입니다. 고등교육 무상화 대상을 확대하고 장학금 제도 충실을 도모합니다.\n의원: 문제는 지금까지도 유사한 대책을 마련해 왔음에도 불구하고 출생률 저하에 브레이크가 걸리지 않고 있다는 것입니다. 근본적 요인은 젊은이들의 장래에 대한 막연한 불안에 있는 것이 아닌가요? 고용 불안정화, 실질임금 하락, 사회보장에 대한 불신감, 이러한 구조적 문제에 파고들지 않으면 미봉책으로는 효과가 한정적입니다.\n대신: 지적을 진지하게 받아들이겠습니다. 고용 안정화와 임금 인상 추진은 저출산 대책의 기반으로 불가결하다고 생각하며, 경제정책과 일체적으로 추진해 나가겠습니다.',
  30
);

-- ============================================
-- N4 Additional Scripts Part 2 (sort_order 31-35)
-- ============================================

-- N4-26: 日本の会社文化 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本の会社文化',
  '先輩：キムさん、日本の会社に慣れましたか。\nキム：はい、だいぶ慣れました。でも、まだ分からないことがあります。\n先輩：何ですか。\nキム：「ほうれんそう」って何ですか。野菜のことですか。\n先輩：ああ、それは報告・連絡・相談のことですよ。仕事で大切なことです。\nキム：なるほど。他に気をつけることはありますか。\n先輩：名前の呼び方は大切です。上司には「〇〇部長」「〇〇課長」と役職をつけて呼びます。\nキム：同僚はどうですか。\n先輩：「〇〇さん」が一般的です。親しくなっても、会社では「さん」をつけましょう。\nキム：メールの書き方も韓国と違いますか。\n先輩：はい、「お疲れ様です」から始めて、「よろしくお願いいたします」で終わるのが基本です。\nキム：飲み会のマナーも教えてください。\n先輩：上司にお酌をするのが一般的です。最初の乾杯はビールが多いですね。',
  'dialogue',
  'N4',
  ARRAY['先輩', 'キム'],
  '先輩に日本の会社文化について教えてもらう場面',
  '[{"word":"報告","reading":"ほうこく","meaning_ko":"보고"},{"word":"連絡","reading":"れんらく","meaning_ko":"연락"},{"word":"相談","reading":"そうだん","meaning_ko":"상담"},{"word":"役職","reading":"やくしょく","meaning_ko":"직위"},{"word":"お酌","reading":"おしゃく","meaning_ko":"술을 따르기"},{"word":"乾杯","reading":"かんぱい","meaning_ko":"건배"}]'::jsonb,
  '선배: 김 씨, 일본 회사에 익숙해졌어요?\n김: 네, 많이 익숙해졌어요. 하지만 아직 모르는 게 있어요.\n선배: 뭔데요?\n김: "호렌소"가 뭐예요? 시금치 말인가요?\n선배: 아, 그건 보고·연락·상담을 말하는 거예요. 업무에서 중요한 거예요.\n김: 그렇군요. 다른 주의할 점이 있나요?\n선배: 이름 부르는 법이 중요해요. 상사에게는 "OO부장" "OO과장"처럼 직위를 붙여서 불러요.\n김: 동료는 어떻게 해요?\n선배: "OO씨"가 일반적이에요. 친해져도 회사에서는 "씨"를 붙이세요.\n김: 메일 쓰는 법도 한국과 다른가요?\n선배: 네, "수고하셨습니다"로 시작하고 "잘 부탁드립니다"로 끝내는 게 기본이에요.\n김: 회식 매너도 가르쳐 주세요.\n선배: 상사에게 술을 따르는 게 일반적이에요. 첫 건배는 맥주가 많아요.',
  31
);

-- N4-27: 日本語学校の遠足 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本語学校の遠足',
  '先生：来週の金曜日、遠足で鎌倉に行きます。集合時間は朝八時半です。学校の前に集まってください。\nキム：バスで行きますか。\n先生：はい、バスで約一時間半です。まず鶴岡八幡宮に行って、その後、大仏を見ます。\nリン：お弁当は持っていきますか。\n先生：いいえ、小町通りで自由に昼食を取ります。食べ歩きもできますよ。\nキム：買い物の時間はありますか。\n先生：午後二時から三時まで自由行動の時間があります。お土産を買えますよ。\nリン：雨が降ったらどうなりますか。\n先生：小雨なら行きます。大雨の場合は中止です。前日の夜に連絡します。\nキム：服装はどうすればいいですか。\n先生：歩きやすい靴を履いてきてください。帽子も持ってきてください。\nリン：楽しみです！\n先生：参加費は二千円です。明日までに払ってくださいね。',
  'dialogue',
  'N4',
  ARRAY['先生', 'キム', 'リン'],
  '日本語学校の遠足の説明を聞く場面',
  '[{"word":"遠足","reading":"えんそく","meaning_ko":"소풍"},{"word":"集合","reading":"しゅうごう","meaning_ko":"집합"},{"word":"大仏","reading":"だいぶつ","meaning_ko":"대불"},{"word":"自由行動","reading":"じゆうこうどう","meaning_ko":"자유 행동"},{"word":"小雨","reading":"こさめ","meaning_ko":"이슬비"},{"word":"参加費","reading":"さんかひ","meaning_ko":"참가비"}]'::jsonb,
  '선생님: 다음 주 금요일에 소풍으로 가마쿠라에 갑니다. 집합 시간은 아침 8시 반이에요. 학교 앞에 모여주세요.\n김: 버스로 가나요?\n선생님: 네, 버스로 약 1시간 반이에요. 먼저 쓰루가오카 하치만구에 가고, 그다음 대불을 봅니다.\n린: 도시락을 가져가나요?\n선생님: 아니요, 코마치도리에서 자유롭게 점심을 먹어요. 먹거리를 사먹을 수도 있어요.\n김: 쇼핑 시간이 있나요?\n선생님: 오후 2시부터 3시까지 자유 행동 시간이 있어요. 기념품을 살 수 있어요.\n린: 비가 오면 어떻게 되나요?\n선생님: 이슬비면 가요. 폭우면 취소예요. 전날 밤에 연락할게요.\n김: 복장은 어떻게 하면 돼요?\n선생님: 걷기 편한 신발을 신고 오세요. 모자도 가져오세요.\n린: 기대돼요!\n선생님: 참가비는 2,000엔이에요. 내일까지 내주세요.',
  32
);

-- N4-28: 体調不良で欠勤の電話 (phone_call)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '体調不良で欠勤の電話',
  'キム：おはようございます。キムです。課長はいらっしゃいますか。\n同僚：おはようございます。課長は今会議中ですが。\nキム：すみません、実は今朝から熱があって、お休みをいただきたいのですが。\n同僚：大丈夫ですか。熱はどのくらいですか。\nキム：三十八度二分です。のどの痛みと咳もあります。\n同僚：それは大変ですね。課長に伝えておきますね。\nキム：ありがとうございます。今日の午後の打ち合わせなのですが、資料はデスクの上にあります。\n同僚：分かりました。\nキム：もし急ぎの用件があれば、メールをいただければ対応できます。\n同僚：無理しないでゆっくり休んでくださいね。\nキム：ありがとうございます。ご迷惑をおかけして申し訳ありません。\n同僚：お大事に。',
  'phone_call',
  'N4',
  ARRAY['キム', '同僚'],
  '体調不良で会社に欠勤の連絡をする場面',
  '[{"word":"欠勤","reading":"けっきん","meaning_ko":"결근"},{"word":"会議中","reading":"かいぎちゅう","meaning_ko":"회의 중"},{"word":"打ち合わせ","reading":"うちあわせ","meaning_ko":"미팅"},{"word":"急ぎ","reading":"いそぎ","meaning_ko":"긴급"},{"word":"用件","reading":"ようけん","meaning_ko":"용건"},{"word":"迷惑","reading":"めいわく","meaning_ko":"폐"}]'::jsonb,
  '김: 안녕하세요. 김입니다. 과장님 계세요?\n동료: 안녕하세요. 과장님은 지금 회의 중인데요.\n김: 죄송한데요, 사실 오늘 아침부터 열이 있어서 쉬고 싶은데요.\n동료: 괜찮아요? 열이 얼마나 돼요?\n김: 38도 2부예요. 목 아픈 것과 기침도 있어요.\n동료: 그건 힘들겠네요. 과장님께 전해 놓을게요.\n김: 감사합니다. 오늘 오후 미팅인데요, 자료는 책상 위에 있어요.\n동료: 알겠어요.\n김: 만약 긴급한 용건이 있으면 메일 보내주시면 대응할 수 있어요.\n동료: 무리하지 말고 푹 쉬세요.\n김: 감사합니다. 폐를 끼쳐 죄송합니다.\n동료: 몸조리 하세요.',
  33
);

-- N4-29: ボランティア活動 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ボランティア活動',
  '田中：キムさん、今度の土曜日、地域の清掃ボランティアに参加しない？\nキム：清掃ボランティア？どこでやるの？\n田中：駅前の公園と商店街だよ。朝九時から十一時まで。\nキム：いいね。何を持っていけばいい？\n田中：軍手とゴミ袋は用意してくれるから、動きやすい服で来てくれればいいよ。\nキム：帽子も要る？\n田中：うん、日差しが強いから持ってきたほうがいいよ。\nキム：何人ぐらい参加するの？\n田中：前回は三十人ぐらいだった。いろんな年齢の人が来るよ。\nキム：参加費はかかるの？\n田中：無料だよ。終わった後にジュースとお菓子がもらえるんだ。\nキム：楽しそう。申し込みは？\n田中：町内会のウェブサイトから申し込めるよ。一緒に申し込もうか。\nキム：うん、お願い。',
  'dialogue',
  'N4',
  ARRAY['田中', 'キム'],
  '地域の清掃ボランティアに誘う場面',
  '[{"word":"清掃","reading":"せいそう","meaning_ko":"청소"},{"word":"ボランティア","reading":"ボランティア","meaning_ko":"자원봉사"},{"word":"商店街","reading":"しょうてんがい","meaning_ko":"상점가"},{"word":"軍手","reading":"ぐんて","meaning_ko":"면장갑"},{"word":"日差し","reading":"ひざし","meaning_ko":"햇빛"},{"word":"町内会","reading":"ちょうないかい","meaning_ko":"동네회"}]'::jsonb,
  '다나카: 김 씨, 이번 주 토요일에 지역 청소 자원봉사에 참가 안 할래?\n김: 청소 자원봉사? 어디서 해?\n다나카: 역 앞 공원이랑 상점가야. 아침 9시부터 11시까지.\n김: 좋네. 뭘 가져가면 돼?\n다나카: 면장갑이랑 쓰레기봉투는 준비해 주니까, 움직이기 편한 옷으로 오면 돼.\n김: 모자도 필요해?\n다나카: 응, 햇빛이 강하니까 가져오는 게 좋아.\n김: 몇 명 정도 참가해?\n다나카: 지난번에는 30명 정도였어. 다양한 나이의 사람들이 와.\n김: 참가비 내야 해?\n다나카: 무료야. 끝나고 주스랑 과자를 받을 수 있어.\n김: 재미있겠다. 신청은?\n다나카: 동네회 웹사이트에서 신청할 수 있어. 같이 신청할까?\n김: 응, 부탁해.',
  34
);

-- N4-30: 年末の挨拶 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '年末の挨拶',
  'キム：課長、今年一年、大変お世話になりました。\n課長：こちらこそ。キムさんも今年はよくがんばりましたね。\nキム：まだまだですが、来年もよろしくお願いいたします。\n課長：お正月は帰国するんですか。\nキム：はい、五日間韓国に帰ります。\n課長：いいですね。ゆっくり休んでください。お土産は気にしなくていいですよ。\nキム：ありがとうございます。あ、年賀状のことですが、課長のご自宅の住所を教えていただけますか。\n課長：年賀状は社内メールでも大丈夫ですよ。最近はメールで送る人も多いですから。\nキム：そうですか。では、メールでお送りします。\n課長：来年は大きなプロジェクトがあるから、一緒にがんばりましょう。\nキム：はい、楽しみにしています。よいお年をお迎えください。\n課長：キムさんもよいお年を。',
  'dialogue',
  'N4',
  ARRAY['キム', '課長'],
  '年末に上司に一年の挨拶をする場面',
  '[{"word":"お世話になる","reading":"おせわになる","meaning_ko":"신세를 지다"},{"word":"お正月","reading":"おしょうがつ","meaning_ko":"설날"},{"word":"年賀状","reading":"ねんがじょう","meaning_ko":"연하장"},{"word":"よいお年を","reading":"よいおとしを","meaning_ko":"좋은 새해 되세요"},{"word":"プロジェクト","reading":"プロジェクト","meaning_ko":"프로젝트"}]'::jsonb,
  '김: 과장님, 올해 한 해 대단히 신세졌습니다.\n과장: 저야말로요. 김 씨도 올해 잘 열심히 했어요.\n김: 아직 부족하지만, 내년에도 잘 부탁드립니다.\n과장: 설에는 귀국하나요?\n김: 네, 5일간 한국에 돌아갑니다.\n과장: 좋겠네요. 푹 쉬세요. 기념품은 신경 쓰지 않아도 돼요.\n김: 감사합니다. 아, 연하장 건인데요, 과장님 댁 주소를 알려주실 수 있나요?\n과장: 연하장은 사내 메일로도 괜찮아요. 요즘은 메일로 보내는 사람도 많으니까요.\n김: 그렇군요. 그러면 메일로 보내겠습니다.\n과장: 내년에는 큰 프로젝트가 있으니까 같이 힘냅시다.\n김: 네, 기대하고 있습니다. 좋은 새해 되세요.\n과장: 김 씨도 좋은 새해 되세요.',
  35
);

-- ============================================
-- N3 Additional Scripts Part 2 (sort_order 31-40)
-- ============================================

-- N3-21: ハッカソンの参加 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ハッカソンの参加',
  'キム：田中さん、来月のハッカソンに一緒に参加しませんか。\n田中：ハッカソン？テーマは何ですか。\nキム：「地域の課題をITで解決する」というテーマです。二日間で開発します。\n田中：面白そうですね。チームは何人ですか。\nキム：三人から五人です。あと一人フロントエンドができる人がほしいんです。\n田中：私はReactが使えますよ。デザインも少しできます。\nキム：完璧です！バックエンドは私がやります。データベースの設計も任せてください。\n田中：賞品はありますか。\nキム：優勝チームには賞金十万円と、企業のインキュベーションプログラムへの推薦があるそうです。\n田中：すごい！やる気が出ますね。\nキム：申し込み期限は来週の金曜日です。企画書のアイデアも考えておいてください。\n田中：分かりました。防災アプリとか、面白いかもしれませんね。\nキム：いいですね。詳しく話しましょう。',
  'dialogue',
  'N3',
  ARRAY['キム', '田中'],
  'ハッカソンへの参加を誘い、チームを組む場面',
  '[{"word":"ハッカソン","reading":"ハッカソン","meaning_ko":"해커톤"},{"word":"フロントエンド","reading":"フロントエンド","meaning_ko":"프런트엔드"},{"word":"バックエンド","reading":"バックエンド","meaning_ko":"백엔드"},{"word":"賞金","reading":"しょうきん","meaning_ko":"상금"},{"word":"企画書","reading":"きかくしょ","meaning_ko":"기획서"},{"word":"防災","reading":"ぼうさい","meaning_ko":"방재"}]'::jsonb,
  '김: 다나카 씨, 다음 달 해커톤에 같이 참가하지 않을래요?\n다나카: 해커톤? 테마가 뭐예요?\n김: "지역의 과제를 IT로 해결한다"는 테마예요. 이틀간 개발해요.\n다나카: 재미있겠네요. 팀은 몇 명이에요?\n김: 3명에서 5명이에요. 한 명 더 프런트엔드 할 수 있는 사람이 필요해요.\n다나카: 저는 React 쓸 수 있어요. 디자인도 좀 할 수 있어요.\n김: 완벽해요! 백엔드는 제가 할게요. 데이터베이스 설계도 맡겨주세요.\n다나카: 상품이 있나요?\n김: 우승팀에게 상금 10만 엔과 기업 인큐베이션 프로그램 추천이 있대요.\n다나카: 대단해! 의욕이 생기네요.\n김: 신청 기한은 다음 주 금요일이에요. 기획서 아이디어도 생각해 둬주세요.\n다나카: 알겠어요. 방재 앱 같은 거 재미있을지도 모르겠네요.\n김: 좋네요. 자세히 이야기합시다.',
  31
);

-- N3-22: 交通事故の保険手続き (phone_call)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '交通事故の保険手続き',
  '担当者：お電話ありがとうございます。ABC損害保険でございます。\nキム：自転車で転んでけがをしまして、保険の請求をしたいのですが。\n担当者：お体は大丈夫ですか。まず、事故の状況を教えてください。\nキム：昨日の夕方、雨で道が滑って転びました。右腕を骨折しました。\n担当者：それは大変でしたね。病院には行かれましたか。\nキム：はい、救急外来で治療を受けました。ギプスをしています。\n担当者：診断書は受け取りましたか。\nキム：まだです。次の診察で書いてもらう予定です。\n担当者：保険金の請求には、診断書と領収書が必要です。治療が完了してからまとめて請求することも可能です。\nキム：通院は何回まで補償されますか。\n担当者：通院保険金は一日につき二千円で、九十日が限度です。入院の場合は一日五千円です。\nキム：仕事を休む場合はどうなりますか。\n担当者：休業補償もございます。会社の休業証明書が必要になりますので、ご準備ください。',
  'phone_call',
  'N3',
  ARRAY['担当者', 'キム'],
  '自転車事故の保険請求について保険会社に電話する場面',
  '[{"word":"損害保険","reading":"そんがいほけん","meaning_ko":"손해보험"},{"word":"請求","reading":"せいきゅう","meaning_ko":"청구"},{"word":"骨折","reading":"こっせつ","meaning_ko":"골절"},{"word":"診断書","reading":"しんだんしょ","meaning_ko":"진단서"},{"word":"通院","reading":"つういん","meaning_ko":"통원"},{"word":"休業補償","reading":"きゅうぎょうほしょう","meaning_ko":"휴업 보상"}]'::jsonb,
  '담당자: 전화 감사합니다. ABC 손해보험입니다.\n김: 자전거에서 넘어져서 다쳤는데 보험 청구를 하고 싶습니다.\n담당자: 몸은 괜찮으세요? 먼저 사고 상황을 알려주세요.\n김: 어제 저녁에 비로 길이 미끄러워서 넘어졌어요. 오른팔이 골절됐어요.\n담당자: 그건 힘드셨겠네요. 병원에는 가셨나요?\n김: 네, 응급외래에서 치료를 받았어요. 깁스를 하고 있어요.\n담당자: 진단서는 받으셨나요?\n김: 아직이요. 다음 진찰에서 써달라고 할 예정이에요.\n담당자: 보험금 청구에는 진단서와 영수증이 필요합니다. 치료가 완료된 후에 한꺼번에 청구하는 것도 가능합니다.\n김: 통원은 몇 회까지 보상되나요?\n담당자: 통원 보험금은 하루당 2,000엔으로 90일이 한도입니다. 입원의 경우 하루 5,000엔입니다.\n김: 일을 쉬는 경우는 어떻게 되나요?\n담당자: 휴업 보상도 있습니다. 회사의 휴업 증명서가 필요하니 준비해 주세요.',
  32
);

-- N3-23: オンラインショッピングのトラブル (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'オンラインショッピングのトラブル',
  'キム：田中さん、ちょっと困ったことがあって。\n田中：どうしたの？\nキム：ネットで買った靴が、サイズが全然合わないんだ。\n田中：返品できないの？\nキム：規約を見たら、開封済みの商品は返品不可って書いてあって。\n田中：でも、サイズが合わないのは商品の問題じゃないの？消費者センターに相談してみたら？\nキム：消費者センターって何？\n田中：消費者トラブルの相談ができる公的な機関だよ。電話番号は一八八番。\nキム：まず、ショップにメールで連絡してみようかな。\n田中：うん、メールで経緯を説明して、交換か返金を求めたほうがいいよ。\nキム：レビューを見たら、同じ苦情が何件もあった。サイズ表記が実際と違うみたい。\n田中：それなら、商品説明に問題があるから、返品に応じてもらえる可能性は高いと思うよ。\nキム：やってみる。アドバイスありがとう。',
  'dialogue',
  'N3',
  ARRAY['キム', '田中'],
  'オンラインショッピングでサイズが合わない商品のトラブルを相談する場面',
  '[{"word":"返品","reading":"へんぴん","meaning_ko":"반품"},{"word":"規約","reading":"きやく","meaning_ko":"규약"},{"word":"開封済み","reading":"かいふうずみ","meaning_ko":"개봉 완료"},{"word":"消費者センター","reading":"しょうひしゃセンター","meaning_ko":"소비자센터"},{"word":"経緯","reading":"けいい","meaning_ko":"경위"},{"word":"苦情","reading":"くじょう","meaning_ko":"불만"}]'::jsonb,
  '김: 다나카 씨, 좀 곤란한 일이 있어서.\n다나카: 무슨 일이야?\n김: 인터넷으로 산 신발이 사이즈가 전혀 안 맞아.\n다나카: 반품 못 해?\n김: 규약을 보니까 개봉한 상품은 반품 불가라고 적혀 있어서.\n다나카: 하지만 사이즈가 안 맞는 건 상품 문제 아니야? 소비자센터에 상담해 보면 어때?\n김: 소비자센터가 뭐야?\n다나카: 소비자 트러블 상담할 수 있는 공적 기관이야. 전화번호는 188번.\n김: 먼저 쇼핑몰에 메일로 연락해 볼까.\n다나카: 응, 메일로 경위를 설명하고 교환이나 환불을 요구하는 게 좋아.\n김: 리뷰를 보니까 같은 불만이 여러 건 있었어. 사이즈 표기가 실제와 다른 것 같아.\n다나카: 그거면 상품 설명에 문제가 있으니까 반품에 응해줄 가능성이 높다고 봐.\n김: 해볼게. 조언 고마워.',
  33
);

-- N3-24: 在留資格の更新 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '在留資格の更新',
  'キム：入管に在留資格の更新に来たのですが、窓口はどこですか。\n案内係：在留期間更新許可申請ですね。B棟の二階です。番号札を取ってお待ちください。\nキム：ありがとうございます。\n審査官：キムさん、申請書類を確認します。パスポート、在留カード、会社の在職証明書はありますか。\nキム：はい、全部持ってきました。こちらです。\n審査官：住民税の課税証明書と納税証明書もありますか。\nキム：はい、市役所で取ってきました。\n審査官：勤務先が変わっていないですね。給与は月額いくらですか。\nキム：月二十八万円です。\n審査官：書類は問題ないようです。在留カードは後日郵送されます。届くまで二週間から一か月ほどかかります。\nキム：その間、在留カードがないのですが、身分証明はどうすればいいですか。\n審査官：こちらの受理票が証明になります。パスポートと一緒に携帯してください。\nキム：分かりました。ありがとうございます。',
  'dialogue',
  'N3',
  ARRAY['キム', '案内係', '審査官'],
  '入国管理局で在留資格の更新手続きをする場面',
  '[{"word":"在留資格","reading":"ざいりゅうしかく","meaning_ko":"재류 자격"},{"word":"更新","reading":"こうしん","meaning_ko":"갱신"},{"word":"在職証明書","reading":"ざいしょくしょうめいしょ","meaning_ko":"재직증명서"},{"word":"課税証明書","reading":"かぜいしょうめいしょ","meaning_ko":"과세증명서"},{"word":"納税証明書","reading":"のうぜいしょうめいしょ","meaning_ko":"납세증명서"},{"word":"受理票","reading":"じゅりひょう","meaning_ko":"접수증"}]'::jsonb,
  '김: 입관에 재류자격 갱신하러 왔는데 창구가 어디인가요?\n안내원: 재류기간 갱신 허가 신청이군요. B동 2층이에요. 번호표를 뽑고 기다려 주세요.\n김: 감사합니다.\n심사관: 김 씨, 신청 서류를 확인합니다. 여권, 재류카드, 회사의 재직증명서 있나요?\n김: 네, 전부 가져왔습니다. 여기요.\n심사관: 주민세 과세증명서와 납세증명서도 있나요?\n김: 네, 시청에서 받아왔어요.\n심사관: 근무처가 바뀌지 않았네요. 급여는 월 얼마인가요?\n김: 월 28만 엔입니다.\n심사관: 서류는 문제없는 것 같습니다. 재류카드는 추후 우편으로 발송됩니다. 도착까지 2주에서 1개월 정도 걸립니다.\n김: 그 사이 재류카드가 없는데 신분 증명은 어떻게 하나요?\n심사관: 이 접수증이 증명이 됩니다. 여권과 함께 휴대해 주세요.\n김: 알겠습니다. 감사합니다.',
  34
);

-- N3-25: 確定申告の準備 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '確定申告の準備',
  'キム：先輩、確定申告ってしなきゃいけないんですか。\n先輩：会社員だけなら、基本的に会社が年末調整をしてくれるから不要だよ。でも、副業をしていたり、医療費がたくさんかかったりした場合は必要になることがある。\nキム：実は、去年歯医者に通って十五万円ぐらいかかったんです。\n先輩：医療費控除が使えるかもしれないね。年間十万円を超えた分が控除の対象になるよ。\nキム：どうやって申請するんですか。\n先輩：確定申告書に医療費の明細を添付して税務署に提出する。e-Taxならオンラインでもできるよ。\nキム：領収書は全部取ってあります。\n先輩：それは大事だね。交通費も医療費に含められるから、通院のための電車賃もメモしておくといいよ。\nキム：還付金はいくらぐらいもらえますか。\n先輩：所得にもよるけど、五万円の控除額で、税率が十パーセントなら五千円ぐらい戻ってくる計算になる。\nキム：少ないけど、やらないよりはいいですね。\n先輩：そうだね。来年からはふるさと納税もおすすめだよ。',
  'dialogue',
  'N3',
  ARRAY['キム', '先輩'],
  '先輩に確定申告について教えてもらう場面',
  '[{"word":"確定申告","reading":"かくていしんこく","meaning_ko":"확정 신고"},{"word":"年末調整","reading":"ねんまつちょうせい","meaning_ko":"연말정산"},{"word":"医療費控除","reading":"いりょうひこうじょ","meaning_ko":"의료비 공제"},{"word":"明細","reading":"めいさい","meaning_ko":"명세"},{"word":"還付金","reading":"かんぷきん","meaning_ko":"환급금"},{"word":"ふるさと納税","reading":"ふるさとのうぜい","meaning_ko":"고향납세"}]'::jsonb,
  '김: 선배, 확정 신고를 해야 하나요?\n선배: 회사원만이면 기본적으로 회사가 연말정산을 해주니까 불필요해. 하지만 부업을 하거나 의료비가 많이 들었으면 필요한 경우가 있어.\n김: 사실 작년에 치과에 다녀서 15만 엔 정도 들었어요.\n선배: 의료비 공제를 쓸 수 있을지도 몰라. 연간 10만 엔을 넘은 분이 공제 대상이야.\n김: 어떻게 신청하나요?\n선배: 확정신고서에 의료비 명세를 첨부해서 세무서에 제출해. e-Tax면 온라인으로도 할 수 있어.\n김: 영수증은 전부 가지고 있어요.\n선배: 그건 중요해. 교통비도 의료비에 포함할 수 있으니까, 통원용 전차비도 메모해 두면 좋아.\n김: 환급금은 얼마 정도 받을 수 있나요?\n선배: 소득에 따라 다르지만, 5만 엔 공제액에 세율이 10%면 5,000엔 정도 돌아오는 계산이야.\n김: 적지만 안 하는 것보다는 낫네요.\n선배: 맞아. 내년부터는 고향납세도 추천이야.',
  35
);

-- N3-26: 防犯のお知らせ (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '防犯のお知らせ',
  'アナウンス：地域の皆さまにお知らせいたします。最近、この地域で振り込め詐欺の被害が増えています。警察や市役所を名乗る人物から「あなたの口座が犯罪に使われています」「還付金があるのでATMで手続きをしてください」といった電話がかかってくることがあります。これらは全て詐欺です。公的機関がATMでの操作を求めることは絶対にありません。不審な電話を受けた場合は、すぐに電話を切り、警察署または消費者ホットラインに相談してください。また、一人暮らしの高齢者の方は特に狙われやすいため、ご近所の方はお声がけいただけますと助かります。留守番電話に設定しておくことも有効な対策の一つです。犯人は録音を嫌がる傾向があります。皆さまの防犯意識の向上が、被害の減少につながります。',
  'announcement',
  'N3',
  ARRAY['アナウンス'],
  '地域の防犯に関する注意喚起の放送',
  '[{"word":"振り込め詐欺","reading":"ふりこめさぎ","meaning_ko":"보이스피싱"},{"word":"名乗る","reading":"なのる","meaning_ko":"사칭하다"},{"word":"公的機関","reading":"こうてききかん","meaning_ko":"공공기관"},{"word":"不審","reading":"ふしん","meaning_ko":"의심스러운"},{"word":"高齢者","reading":"こうれいしゃ","meaning_ko":"고령자"},{"word":"防犯意識","reading":"ぼうはんいしき","meaning_ko":"방범 의식"}]'::jsonb,
  '안내방송: 지역 여러분께 알려드립니다. 최근 이 지역에서 보이스피싱 피해가 늘고 있습니다. 경찰이나 시청을 사칭하는 인물이 "당신의 계좌가 범죄에 사용되고 있습니다" "환급금이 있으니 ATM에서 수속해 주세요"라는 전화를 걸어오는 경우가 있습니다. 이것들은 전부 사기입니다. 공공기관이 ATM 조작을 요구하는 일은 절대 없습니다. 의심스러운 전화를 받으면 바로 전화를 끊고 경찰서 또는 소비자 핫라인에 상담하세요. 또한 혼자 사시는 고령자 분은 특히 표적이 되기 쉬우니 이웃분들은 말씀을 걸어주시면 도움이 됩니다. 자동응답으로 설정해 두는 것도 유효한 대책 중 하나입니다. 범인은 녹음을 꺼리는 경향이 있습니다. 여러분의 방범 의식 향상이 피해 감소로 이어집니다.',
  36
);

-- N3-27: 日本のマナー講座 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本のマナー講座',
  '講師：今日は日本のビジネスマナーについてお話しします。まず、お辞儀の角度についてです。挨拶の時は十五度、お礼やお詫びの時は三十度、深いお詫びや大切なお客様には四十五度が目安です。次に、エレベーターのマナーですが、お客様や上司が先に乗り降りするようにしましょう。操作盤の前に立つ人が開閉ボタンを操作します。名刺交換の際は、テーブル越しではなく、相手の近くに移動してから行います。両手で差し出し、相手の名刺は両手で受け取ります。受け取った名刺にすぐメモを書くのは失礼にあたります。席順にも決まりがあります。会議室では出入り口から遠い席が上座で、お客様や上司が座ります。タクシーでは運転手の後ろが上座です。これらのマナーは最初は難しく感じるかもしれませんが、練習すれば自然にできるようになります。',
  'instruction',
  'N3',
  ARRAY['講師'],
  '外国人社員向けのビジネスマナー講座',
  '[{"word":"お辞儀","reading":"おじぎ","meaning_ko":"인사(절)"},{"word":"操作盤","reading":"そうさばん","meaning_ko":"조작반"},{"word":"名刺交換","reading":"めいしこうかん","meaning_ko":"명함 교환"},{"word":"失礼","reading":"しつれい","meaning_ko":"실례"},{"word":"上座","reading":"かみざ","meaning_ko":"상석"},{"word":"席順","reading":"せきじゅん","meaning_ko":"자리 배치"}]'::jsonb,
  '강사: 오늘은 일본의 비즈니스 매너에 대해 이야기합니다. 먼저 인사의 각도에 대해서입니다. 인사할 때는 15도, 감사나 사과할 때는 30도, 깊은 사과나 중요한 고객에게는 45도가 기준입니다. 다음으로 엘리베이터 매너인데, 고객이나 상사가 먼저 타고 내리도록 합시다. 조작반 앞에 서는 사람이 개폐 버튼을 조작합니다. 명함 교환 시에는 테이블 너머가 아니라 상대 가까이로 이동한 후에 합니다. 양손으로 내밀고 상대의 명함은 양손으로 받습니다. 받은 명함에 바로 메모를 쓰는 것은 실례에 해당합니다. 자리 배치에도 규칙이 있습니다. 회의실에서는 출입구에서 먼 자리가 상석이고, 고객이나 상사가 앉습니다. 택시에서는 운전사 뒤가 상석입니다. 이런 매너는 처음에는 어렵게 느껴질 수 있지만, 연습하면 자연스럽게 할 수 있게 됩니다.',
  37
);

-- N3-28: 新しいサービスの提案 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '新しいサービスの提案',
  'キム：チームリーダーに提案があるのですが、よろしいですか。\nリーダー：はい、どうぞ。\nキム：社内の業務効率化のために、チャットボットを導入してはどうかと考えています。\nリーダー：具体的にはどんな業務に使うイメージですか。\nキム：まず、総務への問い合わせ対応です。有給の申請方法や経費精算のルールなど、よくある質問にチャットボットが自動で回答できます。\nリーダー：確かに、総務への問い合わせは多いですね。開発工数はどのくらい見込んでいますか。\nキム：既存のフレームワークを使えば、基本機能は二週間程度で開発できると思います。FAQデータの整備には総務部の協力が必要です。\nリーダー：コストはどうですか。\nキム：クラウドサービスの利用料が月二万円程度、開発は社内リソースで対応可能です。\nリーダー：効果の測定はどうしますか。\nキム：導入前後の総務への問い合わせ件数と、社員の満足度アンケートで測定します。\nリーダー：いい提案ですね。まず企画書を作成して、部長に報告しましょう。',
  'meeting',
  'N3',
  ARRAY['キム', 'リーダー'],
  'チームリーダーに新しいサービスを提案する場面',
  '[{"word":"チャットボット","reading":"チャットボット","meaning_ko":"챗봇"},{"word":"導入","reading":"どうにゅう","meaning_ko":"도입"},{"word":"経費精算","reading":"けいひせいさん","meaning_ko":"경비 정산"},{"word":"開発工数","reading":"かいはつこうすう","meaning_ko":"개발 공수"},{"word":"フレームワーク","reading":"フレームワーク","meaning_ko":"프레임워크"},{"word":"リソース","reading":"リソース","meaning_ko":"리소스"}]'::jsonb,
  '김: 팀 리더님께 제안이 있는데 괜찮으세요?\n리더: 네, 말씀하세요.\n김: 사내 업무 효율화를 위해 챗봇을 도입하면 어떨까 생각하고 있습니다.\n리더: 구체적으로 어떤 업무에 쓸 이미지인가요?\n김: 먼저 총무부 문의 대응이에요. 유급 신청 방법이나 경비 정산 규칙 등 자주 있는 질문에 챗봇이 자동으로 답변할 수 있어요.\n리더: 확실히 총무부 문의는 많죠. 개발 공수는 어느 정도 예상하고 있나요?\n김: 기존 프레임워크를 사용하면 기본 기능은 2주 정도로 개발할 수 있다고 생각합니다. FAQ 데이터 정비에는 총무부 협력이 필요해요.\n리더: 비용은 어떤가요?\n김: 클라우드 서비스 이용료가 월 2만 엔 정도이고, 개발은 사내 리소스로 대응 가능합니다.\n리더: 효과 측정은 어떻게 하나요?\n김: 도입 전후의 총무부 문의 건수와 사원 만족도 설문으로 측정합니다.\n리더: 좋은 제안이네요. 먼저 기획서를 작성해서 부장님께 보고합시다.',
  38
);

-- N3-29: 台風接近の注意報 (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '台風接近の注意報',
  'アナウンス：台風十二号に関する情報をお伝えします。台風は現在、四国沖を北東に進んでおり、明日の午前中に関東地方に最接近する見込みです。最大瞬間風速は四十メートル、一時間に六十ミリの激しい雨が予想されています。交通機関への影響が予想されますので、不要不急の外出は控えてください。JR各線は明日の始発から運転を見合わせる可能性があります。最新の運行情報は各鉄道会社のウェブサイトで確認してください。お住まいの地域にハザードマップで浸水の危険がある方は、早めに避難してください。停電に備えて、懐中電灯や携帯電話の充電を確認してください。窓ガラスにはテープを貼り、飛びやすいものは室内に入れてください。会社や学校の休みについては、それぞれの判断に従ってください。引き続き、最新の気象情報にご注意ください。',
  'announcement',
  'N3',
  ARRAY['アナウンス'],
  '台風接近に伴う注意喚起の放送',
  '[{"word":"台風","reading":"たいふう","meaning_ko":"태풍"},{"word":"最接近","reading":"さいせっきん","meaning_ko":"최접근"},{"word":"瞬間風速","reading":"しゅんかんふうそく","meaning_ko":"순간 풍속"},{"word":"不要不急","reading":"ふようふきゅう","meaning_ko":"불요불급"},{"word":"浸水","reading":"しんすい","meaning_ko":"침수"},{"word":"停電","reading":"ていでん","meaning_ko":"정전"}]'::jsonb,
  '안내방송: 태풍 12호에 관한 정보를 전합니다. 태풍은 현재 시코쿠 앞바다를 북동으로 진행하고 있으며, 내일 오전 중에 관동 지방에 최접근할 전망입니다. 최대 순간 풍속은 40미터, 시간당 60밀리의 격렬한 비가 예상됩니다. 교통기관에 영향이 예상되니 불요불급의 외출은 삼가주세요. JR 각 노선은 내일 첫차부터 운행을 중단할 가능성이 있습니다. 최신 운행 정보는 각 철도회사 웹사이트에서 확인하세요. 거주 지역에 해저드맵상 침수 위험이 있는 분은 일찍 대피하세요. 정전에 대비해 손전등과 휴대전화 충전을 확인하세요. 창유리에는 테이프를 붙이고 날아가기 쉬운 물건은 실내로 들이세요. 회사나 학교 휴무에 대해서는 각각의 판단에 따라주세요. 계속해서 최신 기상 정보에 주의하세요.',
  39
);

-- N3-30: 技術勉強会の発表 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '技術勉強会の発表',
  'キム：今日は、先月リリースされたTypeScript五・〇の新機能について発表します。大きな変更点は三つあります。一つ目は、デコレータが正式にサポートされたことです。これにより、メタプログラミングがより簡潔に書けるようになりました。二つ目は、型推論の改善です。複雑なジェネリクスの型も、コンパイラが自動的に正しい型を推論してくれるようになりました。三つ目は、パフォーマンスの改善です。ビルド時間が前バージョンと比べて約二十パーセント短縮されています。実際のプロジェクトへの導入にあたっては、まず既存のコードとの互換性を確認する必要があります。パッケージの依存関係もチェックしてください。マイグレーションガイドが公式サイトに公開されていますので、参考にしてください。私のチームでは先週から試験的に導入していますが、特に大きな問題は発生していません。質問があればどうぞ。',
  'monologue',
  'N3',
  ARRAY['キム'],
  '社内の技術勉強会でTypeScriptの新機能を発表する場面',
  '[{"word":"リリース","reading":"リリース","meaning_ko":"릴리스"},{"word":"デコレータ","reading":"デコレータ","meaning_ko":"데코레이터"},{"word":"型推論","reading":"かたすいろん","meaning_ko":"타입 추론"},{"word":"互換性","reading":"ごかんせい","meaning_ko":"호환성"},{"word":"マイグレーション","reading":"マイグレーション","meaning_ko":"마이그레이션"},{"word":"試験的","reading":"しけんてき","meaning_ko":"시험적"}]'::jsonb,
  '김: 오늘은 지난달 릴리스된 TypeScript 5.0의 새 기능에 대해 발표합니다. 큰 변경점은 세 가지입니다. 첫 번째는 데코레이터가 정식으로 지원된 것입니다. 이를 통해 메타프로그래밍을 더 간결하게 작성할 수 있게 되었습니다. 두 번째는 타입 추론 개선입니다. 복잡한 제네릭스의 타입도 컴파일러가 자동으로 올바른 타입을 추론해 줍니다. 세 번째는 퍼포먼스 개선입니다. 빌드 시간이 전 버전과 비교해 약 20% 단축되었습니다. 실제 프로젝트 도입에 있어서는 먼저 기존 코드와의 호환성을 확인할 필요가 있습니다. 패키지 의존 관계도 체크하세요. 마이그레이션 가이드가 공식 사이트에 공개되어 있으니 참고하세요. 제 팀에서는 지난주부터 시험적으로 도입하고 있는데 특별히 큰 문제는 발생하지 않았습니다. 질문 있으시면 해주세요.',
  40
);

-- ============================================
-- N2 Additional Scripts Part 2 (sort_order 6-20)
-- ============================================

-- N2-16: 外国人エンジニアの座談会 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '外国人エンジニアの座談会',
  '司会：本日は「外国人ITエンジニアが日本で働くということ」をテーマに座談会を行います。まず、日本に来た理由を教えてください。\nキム：韓国のIT業界は競争が激しく、日本の方が技術者を大切にする文化があると感じたからです。\nリン：私は中国出身です。日本のものづくりの精神に惹かれて来ました。品質に対するこだわりは、ソフトウェア開発にも通じるものがあります。\n司会：日本で働いて苦労したことは何ですか。\nキム：コードレビューで「もう少し丁寧に」と言われるのですが、具体的にどこを直せばいいか分からないことがありました。曖昧な表現に慣れるのに時間がかかりましたね。\nリン：同感です。会議で「検討します」と言われると進むのかと思ったら、実質的に断られていたということもありました。\n司会：逆に、良かった点は？\nキム：チームの結束力が強いことです。一人が困っていると、みんなが助けてくれます。\nリン：ワークライフバランスが改善されてきていることです。以前の会社と比べて残業が少なく、有給も取りやすいです。\n司会：後輩の外国人エンジニアへのアドバイスはありますか。\nキム：日本語力は武器になります。N2以上を目指して、技術用語だけでなくビジネス日本語も学んでください。',
  'meeting',
  'N2',
  ARRAY['司会', 'キム', 'リン'],
  '外国人ITエンジニアの座談会',
  '[{"word":"ものづくり","reading":"ものづくり","meaning_ko":"모노즈쿠리(제조업 정신)"},{"word":"こだわり","reading":"こだわり","meaning_ko":"고집, 집착"},{"word":"曖昧","reading":"あいまい","meaning_ko":"애매"},{"word":"結束力","reading":"けっそくりょく","meaning_ko":"결속력"},{"word":"ワークライフバランス","reading":"ワークライフバランス","meaning_ko":"워라밸"}]'::jsonb,
  '사회자: 오늘은 "외국인 IT 엔지니어가 일본에서 일한다는 것"을 주제로 좌담회를 진행합니다. 먼저 일본에 온 이유를 알려주세요.\n김: 한국의 IT 업계는 경쟁이 치열하고, 일본이 기술자를 소중히 하는 문화가 있다고 느꼈기 때문입니다.\n린: 저는 중국 출신입니다. 일본의 모노즈쿠리 정신에 끌려서 왔어요. 품질에 대한 고집은 소프트웨어 개발에도 통하는 것이 있습니다.\n사회자: 일본에서 일하며 고생한 것은 뭔가요?\n김: 코드 리뷰에서 "좀 더 정중하게"라고 하는데, 구체적으로 어디를 고치면 되는지 모를 때가 있었어요. 애매한 표현에 익숙해지는 데 시간이 걸렸죠.\n린: 동감이에요. 회의에서 "검토하겠습니다"라고 해서 진행되는 줄 알았는데 실질적으로 거절당한 적도 있었어요.\n사회자: 반대로 좋았던 점은?\n김: 팀의 결속력이 강한 것이에요. 한 사람이 곤란해하면 모두가 도와줍니다.\n린: 워라밸이 개선되고 있는 것이에요. 이전 회사와 비교해 야근이 적고 유급도 쓰기 쉬워요.\n사회자: 후배 외국인 엔지니어에게 조언이 있나요?\n김: 일본어 실력은 무기가 됩니다. N2 이상을 목표로 기술 용어뿐만 아니라 비즈니스 일본어도 배우세요.',
  6
);

-- N2-17: 住宅ローンの相談 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '住宅ローンの相談',
  '銀行員：本日はどのようなご相談でしょうか。\nキム：住宅の購入を考えておりまして、住宅ローンについて相談したいのですが。\n銀行員：承知しました。ご購入予定の物件はお決まりですか。\nキム：はい、三千五百万円のマンションを検討しています。頭金として五百万円を用意しています。\n銀行員：では、三千万円の融資ということになりますね。ご年収はいくらですか。\nキム：税込みで五百五十万円です。\n銀行員：返済比率が年収の三十五パーセント以内に収まるのが理想的です。三十五年ローンですと、月々の返済額は変動金利で約八万五千円、固定金利で約九万二千円になります。\nキム：変動と固定、どちらがいいですか。\n銀行員：変動金利は現在の水準が低いのでお得ですが、将来上がるリスクがあります。固定金利は返済額が変わらないので、計画が立てやすいです。\nキム：外国人でも審査は通りますか。\n銀行員：永住権をお持ちであれば、日本人と同じ条件で審査いたします。永住権がない場合は、条件が厳しくなることがあります。\nキム：永住権は去年取得しました。\n銀行員：では、問題ございません。事前審査の申し込みをされますか。',
  'dialogue',
  'N2',
  ARRAY['銀行員', 'キム'],
  '銀行で住宅ローンの相談をする場面',
  '[{"word":"住宅ローン","reading":"じゅうたくローン","meaning_ko":"주택 대출"},{"word":"頭金","reading":"あたまきん","meaning_ko":"계약금"},{"word":"融資","reading":"ゆうし","meaning_ko":"융자"},{"word":"返済比率","reading":"へんさいひりつ","meaning_ko":"상환 비율"},{"word":"変動金利","reading":"へんどうきんり","meaning_ko":"변동 금리"},{"word":"永住権","reading":"えいじゅうけん","meaning_ko":"영주권"}]'::jsonb,
  '행원: 오늘은 어떤 상담이세요?\n김: 주택 구매를 생각하고 있어서 주택 대출에 대해 상담하고 싶습니다.\n행원: 알겠습니다. 구매 예정 물건은 정해지셨나요?\n김: 네, 3,500만 엔짜리 맨션을 검토하고 있어요. 계약금으로 500만 엔을 준비했습니다.\n행원: 그러면 3,000만 엔 융자가 되겠네요. 연수입은 얼마이세요?\n김: 세전 550만 엔입니다.\n행원: 상환 비율이 연수입의 35% 이내에 드는 것이 이상적입니다. 35년 대출이면 월 상환액은 변동금리로 약 85,000엔, 고정금리로 약 92,000엔이 됩니다.\n김: 변동과 고정 중 어느 쪽이 좋나요?\n행원: 변동금리는 현재 수준이 낮아서 이득이지만 장래 오를 리스크가 있습니다. 고정금리는 상환액이 변하지 않아 계획을 세우기 쉽습니다.\n김: 외국인도 심사가 통과되나요?\n행원: 영주권을 가지고 계시면 일본인과 같은 조건으로 심사합니다. 영주권이 없는 경우 조건이 까다로워질 수 있습니다.\n김: 영주권은 작년에 취득했습니다.\n행원: 그러면 문제없습니다. 사전 심사 신청을 하시겠어요?',
  7
);

-- N2-18: 日本の働き方改革 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本の働き方改革',
  '講師：本日は日本における働き方改革の現状と課題についてお話しします。二〇一九年に施行された働き方改革関連法により、時間外労働の上限規制や、同一労働同一賃金の原則が導入されました。その結果、年間総実労働時間は減少傾向にあり、有給休暇の取得率も改善してきています。しかし、課題も残っています。テレワークの普及はコロナ禍で一時的に進みましたが、出社回帰の動きも見られます。多くの企業がハイブリッドワークを模索していますが、コミュニケーション不足や、評価の公平性をどう担保するかが問題となっています。また、非正規雇用者と正規雇用者の格差是正は道半ばです。同一労働同一賃金の理念は浸透しつつありますが、実際の運用では企業間のばらつきが大きい状況です。さらに、副業解禁の流れがありますが、労務管理の複雑さから、解禁に踏み切れない企業も少なくありません。一方、ジョブ型雇用への移行を進める大手企業も増えており、年功序列から成果主義への転換が緩やかに進んでいます。',
  'monologue',
  'N2',
  ARRAY['講師'],
  '人事セミナーでの働き方改革に関する講演',
  '[{"word":"施行","reading":"しこう","meaning_ko":"시행"},{"word":"時間外労働","reading":"じかんがいろうどう","meaning_ko":"시간 외 노동"},{"word":"同一労働同一賃金","reading":"どういつろうどうどういつちんぎん","meaning_ko":"동일노동 동일임금"},{"word":"非正規雇用","reading":"ひせいきこよう","meaning_ko":"비정규 고용"},{"word":"年功序列","reading":"ねんこうじょれつ","meaning_ko":"연공서열"},{"word":"ジョブ型雇用","reading":"ジョブがたこよう","meaning_ko":"직무형 고용"}]'::jsonb,
  '강사: 오늘은 일본의 일하는 방식 개혁의 현황과 과제에 대해 말씀드리겠습니다. 2019년에 시행된 일하는 방식 개혁 관련법에 의해 시간 외 노동의 상한 규제와 동일노동 동일임금 원칙이 도입되었습니다. 그 결과 연간 총 실노동 시간은 감소 추세에 있으며 유급 휴가 취득률도 개선되어 오고 있습니다. 그러나 과제도 남아 있습니다. 재택근무 보급은 코로나 사태로 일시적으로 진행되었지만 출근 회귀 움직임도 보입니다. 많은 기업이 하이브리드 워크를 모색하고 있지만 커뮤니케이션 부족과 평가의 공평성을 어떻게 담보할지가 문제가 되고 있습니다. 또한 비정규 고용자와 정규 고용자의 격차 시정은 절반도 안 된 상태입니다. 동일노동 동일임금의 이념은 침투하고 있지만 실제 운용에서는 기업 간 편차가 큰 상황입니다. 나아가 부업 해금 흐름이 있지만 노무 관리의 복잡함 때문에 해금에 나서지 못하는 기업도 적지 않습니다. 한편 직무형 고용으로의 이행을 진행하는 대기업도 늘고 있으며, 연공서열에서 성과주의로의 전환이 완만하게 진행되고 있습니다.',
  8
);

-- N2-19: 日韓ビジネス文化の比較 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日韓ビジネス文化の比較',
  '教授：キムさんは日韓両方のIT企業で働いた経験がありますね。文化の違いを教えてください。\nキム：はい。まず意思決定のスピードが大きく異なります。韓国は比較的トップダウンで、決定が速いです。一方、日本は「根回し」や「稟議」といったプロセスを経るため、決定に時間がかかります。\n教授：それはデメリットだけですか。\nキム：いいえ。日本式の合意形成は時間がかかりますが、決定した後の実行力は高いです。全員が納得しているので、方向転換が少ない。韓国は決定は速いですが、途中で方針が変わることがよくあります。\n教授：開発スタイルの違いはありますか。\nキム：韓国ではスピードが重視され、「まず出して改善する」という考え方が主流です。日本は品質を重視し、リリース前のテストが徹底しています。どちらにも一長一短があります。\n教授：コミュニケーションの違いは？\nキム：韓国は直接的な表現を好みますが、日本は間接的です。「ちょっと難しいかもしれません」は、実質的に「無理です」という意味だと理解するのに時間がかかりました。\n教授：非常に興味深い比較ですね。両方の良いところを取り入れることが理想的ですね。',
  'dialogue',
  'N2',
  ARRAY['教授', 'キム'],
  '大学のセミナーで日韓ビジネス文化を比較する場面',
  '[{"word":"意思決定","reading":"いしけってい","meaning_ko":"의사결정"},{"word":"根回し","reading":"ねまわし","meaning_ko":"사전 조율"},{"word":"稟議","reading":"りんぎ","meaning_ko":"품의"},{"word":"合意形成","reading":"ごういけいせい","meaning_ko":"합의 형성"},{"word":"一長一短","reading":"いっちょういったん","meaning_ko":"일장일단"},{"word":"間接的","reading":"かんせつてき","meaning_ko":"간접적"}]'::jsonb,
  '교수: 김 씨는 한일 양쪽의 IT 기업에서 일한 경험이 있죠. 문화의 차이를 알려주세요.\n김: 네. 먼저 의사결정 속도가 크게 다릅니다. 한국은 비교적 톱다운으로 결정이 빠릅니다. 반면 일본은 "사전 조율"이나 "품의"라는 프로세스를 거치기 때문에 결정에 시간이 걸립니다.\n교수: 그것은 단점뿐인가요?\n김: 아닙니다. 일본식 합의 형성은 시간이 걸리지만 결정 후의 실행력은 높습니다. 전원이 납득하고 있으니 방향 전환이 적어요. 한국은 결정은 빠르지만 도중에 방침이 바뀌는 경우가 많습니다.\n교수: 개발 스타일의 차이는 있나요?\n김: 한국에서는 속도가 중시되어 "우선 내놓고 개선한다"는 사고방식이 주류입니다. 일본은 품질을 중시하고 릴리스 전 테스트가 철저합니다. 어느 쪽에나 일장일단이 있습니다.\n교수: 커뮤니케이션의 차이는?\n김: 한국은 직접적 표현을 좋아하지만 일본은 간접적입니다. "좀 어려울지도 모릅니다"가 실질적으로 "무리입니다"라는 의미라고 이해하는 데 시간이 걸렸습니다.\n교수: 매우 흥미로운 비교네요. 양쪽의 좋은 점을 취하는 것이 이상적이겠죠.',
  9
);

-- N2-20: 介護問題に関する講演 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '介護問題に関する講演',
  '講師：本日は「超高齢社会における介護の現状と課題」についてお話しします。日本の六十五歳以上の高齢者人口は三千六百万人を超え、総人口の約二十九パーセントを占めています。要介護認定者数は年々増加しており、介護人材の不足は深刻な社会問題となっています。現在、介護職員は約二十万人不足していると推計されています。その背景には、重労働でありながら賃金水準が低いという構造的な問題があります。政府は処遇改善加算の拡充や、外国人介護人材の受け入れ拡大を進めていますが、抜本的な解決には至っていません。在宅介護と施設介護のバランスも課題です。介護離職を防ぐためには、仕事と介護の両立を支援する制度の整備が急務です。介護休業制度を利用する人は依然として少なく、制度の周知と利用しやすい職場環境の整備が求められています。テクノロジーの活用も重要な鍵を握っています。介護ロボットやICTを活用した見守りシステムの導入により、介護者の負担軽減と、高齢者のQOL向上を同時に実現することが期待されています。',
  'monologue',
  'N2',
  ARRAY['講師'],
  '福祉関連セミナーでの介護問題に関する講演',
  '[{"word":"超高齢社会","reading":"ちょうこうれいしゃかい","meaning_ko":"초고령사회"},{"word":"要介護認定","reading":"ようかいごにんてい","meaning_ko":"요간호 인정"},{"word":"処遇改善","reading":"しょぐうかいぜん","meaning_ko":"처우 개선"},{"word":"介護離職","reading":"かいごりしょく","meaning_ko":"간호 이직"},{"word":"見守り","reading":"みまもり","meaning_ko":"돌봄"},{"word":"QOL","reading":"キューオーエル","meaning_ko":"삶의 질"}]'::jsonb,
  '강사: 오늘은 "초고령사회의 간호 현황과 과제"에 대해 말씀드리겠습니다. 일본의 65세 이상 고령자 인구는 3,600만 명을 넘어 총인구의 약 29%를 차지하고 있습니다. 요간호 인정자 수는 해마다 증가하고 있으며, 간호 인력 부족은 심각한 사회 문제가 되고 있습니다. 현재 간호 직원이 약 20만 명 부족하다고 추계되고 있습니다. 그 배경에는 중노동이면서도 임금 수준이 낮다는 구조적 문제가 있습니다. 정부는 처우 개선 가산 확충이나 외국인 간호 인재의 수용 확대를 진행하고 있지만, 근본적인 해결에는 이르지 못하고 있습니다. 재택 간호와 시설 간호의 균형도 과제입니다. 간호 이직을 방지하기 위해서는 일과 간호의 양립을 지원하는 제도 정비가 급선무입니다. 간호 휴직 제도를 이용하는 사람은 여전히 적고 제도의 주지와 이용하기 쉬운 직장 환경 정비가 요구되고 있습니다. 기술 활용도 중요한 열쇠를 쥐고 있습니다. 간호 로봇이나 ICT를 활용한 돌봄 시스템 도입을 통해 간호자의 부담 경감과 고령자의 삶의 질 향상을 동시에 실현하는 것이 기대되고 있습니다.',
  10
);

-- ============================================
-- N1 Additional Scripts Part 2 (sort_order 31-50)
-- ============================================

-- N1-11: 量子コンピューティングの最前線 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '量子コンピューティングの最前線',
  '教授：量子コンピューティングの研究における直近の進展についてご報告します。従来型コンピュータが二進法のビットで計算するのに対し、量子コンピュータは量子ビット、いわゆるキュービットを用いて、重ね合わせとエンタングルメントという量子力学的性質を利用します。これにより、特定の計算問題において、古典的コンピュータでは実質的に不可能な規模の計算を、現実的な時間内に遂行できる可能性があります。現在の最大の技術的課題は、量子ビットのデコヒーレンスです。外部環境のノイズによって量子状態が崩壊してしまう問題に対し、我々の研究グループでは、トポロジカル量子ビットを用いた誤り耐性量子計算の実現に取り組んでおります。昨年、エラー率を従来の十分の一に低減することに成功しました。産業応用としては、創薬シミュレーション、金融リスク計算、物流最適化など、多岐にわたる分野での活用が見込まれています。ただし、汎用量子コンピュータの実現にはまだ十年から二十年を要するというのが、多くの研究者の共通認識です。',
  'monologue',
  'N1',
  ARRAY['教授'],
  '学術シンポジウムでの量子コンピューティングに関する講演',
  '[{"word":"量子コンピューティング","reading":"りょうしコンピューティング","meaning_ko":"양자 컴퓨팅"},{"word":"重ね合わせ","reading":"かさねあわせ","meaning_ko":"중첩"},{"word":"デコヒーレンス","reading":"デコヒーレンス","meaning_ko":"결어긋남"},{"word":"誤り耐性","reading":"あやまりたいせい","meaning_ko":"오류 내성"},{"word":"創薬","reading":"そうやく","meaning_ko":"신약 개발"},{"word":"汎用","reading":"はんよう","meaning_ko":"범용"}]'::jsonb,
  '교수: 양자 컴퓨팅 연구의 최근 진전에 대해 보고드리겠습니다. 기존형 컴퓨터가 이진법의 비트로 계산하는 것에 반해 양자 컴퓨터는 양자 비트, 이른바 큐비트를 사용하여 중첩과 얽힘이라는 양자역학적 성질을 이용합니다. 이를 통해 특정 계산 문제에서 고전적 컴퓨터로는 실질적으로 불가능한 규모의 계산을 현실적인 시간 내에 수행할 수 있는 가능성이 있습니다. 현재 최대의 기술적 과제는 양자 비트의 결어긋남입니다. 외부 환경의 노이즈에 의해 양자 상태가 붕괴되는 문제에 대해 저희 연구 그룹에서는 토폴로지컬 양자 비트를 이용한 오류 내성 양자 계산의 실현에 힘쓰고 있습니다. 작년에 에러율을 기존의 10분의 1로 저감하는 데 성공했습니다. 산업 응용으로는 신약 개발 시뮬레이션, 금융 리스크 계산, 물류 최적화 등 다방면에 걸친 분야의 활용이 예상됩니다. 다만 범용 양자 컴퓨터의 실현에는 아직 10년에서 20년이 필요하다는 것이 많은 연구자의 공통 인식입니다.',
  31
);

-- N1-12: 国際通商紛争の分析 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '国際通商紛争の分析',
  '教授A：米中の半導体を巡る通商摩擦が激化しておりますが、日本の産業界への影響をどのように分析されていますか。\n教授B：サプライチェーンの分断リスクが最も懸念される点です。日本の半導体製造装置メーカーは、中国市場への依存度が高く、輸出規制の強化は売上に直接的な影響を及ぼします。一方で、フレンドショアリングの流れの中で、台湾や韓国に加え、日本国内への工場誘致が進んでおり、これは日本の半導体産業復興にとって追い風と言えるでしょう。\n企業代表：実務的な観点から申し上げますと、デカップリングは完全には不可能です。グローバルなサプライチェーンは高度に相互依存しており、一国の規制だけでは制御しきれない現実があります。むしろ、チャイナプラスワンの戦略として、生産拠点を分散させるリスク管理が現実的です。\n教授A：地経学的な視点では、半導体は現代の石油とも言うべき戦略物資であり、経済安全保障の文脈で議論する必要があります。日本政府のラピダスへの巨額投資も、この文脈で理解すべきでしょう。\n教授B：技術覇権を巡る競争が、多国間の通商秩序を根底から揺るがしているのは憂慮すべき事態です。WTOの紛争解決機能が機能不全に陥っている中、新たな国際的なルール形成が急がれます。',
  'meeting',
  'N1',
  ARRAY['教授A', '教授B', '企業代表'],
  '国際経済フォーラムでの通商問題に関するパネル討論',
  '[{"word":"通商摩擦","reading":"つうしょうまさつ","meaning_ko":"통상 마찰"},{"word":"サプライチェーン","reading":"サプライチェーン","meaning_ko":"공급망"},{"word":"フレンドショアリング","reading":"フレンドショアリング","meaning_ko":"프렌드쇼어링"},{"word":"デカップリング","reading":"デカップリング","meaning_ko":"디커플링"},{"word":"地経学","reading":"ちけいがく","meaning_ko":"지경학"},{"word":"覇権","reading":"はけん","meaning_ko":"패권"}]'::jsonb,
  '교수A: 미중 반도체를 둘러싼 통상 마찰이 격화되고 있는데 일본 산업계에 대한 영향을 어떻게 분석하고 계신가요?\n교수B: 공급망 분단 리스크가 가장 우려되는 점입니다. 일본의 반도체 제조 장비 메이커는 중국 시장 의존도가 높아 수출 규제 강화가 매출에 직접적 영향을 미칩니다. 한편, 프렌드쇼어링 흐름 속에서 대만이나 한국에 더해 일본 국내로의 공장 유치가 진행되고 있으며, 이것은 일본 반도체 산업 부흥에 순풍이라 할 수 있겠습니다.\n기업 대표: 실무적 관점에서 말씀드리면 디커플링은 완전히 불가능합니다. 글로벌 공급망은 고도로 상호 의존하고 있으며 한 나라의 규제만으로는 통제하기 어려운 현실이 있습니다. 오히려 차이나 플러스 원 전략으로 생산 거점을 분산시키는 리스크 관리가 현실적입니다.\n교수A: 지경학적 관점에서는 반도체는 현대의 석유라고도 할 전략 물자이며 경제 안보 맥락에서 논의할 필요가 있습니다. 일본 정부의 라피더스에 대한 거액 투자도 이 맥락에서 이해해야 할 것입니다.\n교수B: 기술 패권을 둘러싼 경쟁이 다국간 통상 질서를 근저부터 흔들고 있는 것은 우려할 사태입니다. WTO의 분쟁 해결 기능이 기능 부전에 빠져 있는 가운데, 새로운 국제적 규칙 형성이 시급합니다.',
  32
);

-- N1-13: 脱炭素社会に向けた政策提言 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '脱炭素社会に向けた政策提言',
  '委員：環境審議会からの政策提言を発表いたします。二〇五〇年カーボンニュートラルの達成に向け、以下の五つの重点施策を提言いたします。第一に、再生可能エネルギーの導入加速です。洋上風力発電の大規模展開と、次世代太陽光パネルの技術開発を推進します。二〇三五年までに電力供給の五十パーセントを再エネで賄うことを目標とします。第二に、水素社会の実現です。グリーン水素の製造コストを現在の三分の一に低減し、運輸・産業部門での水素利用を拡大します。第三に、カーボンプライシングの導入です。排出量取引制度と炭素税の組み合わせにより、市場メカニズムを通じた排出削減を促進します。ただし、国際競争力への影響を考慮し、段階的な導入とすべきです。第四に、グリーンファイナンスの拡充です。気候変動関連の情報開示を義務化し、ESG投資の流れを加速させます。第五に、公正な移行の確保です。石炭火力発電所の廃止に伴う雇用への影響に対し、職業訓練や地域経済の転換支援を行います。これらの施策を統合的に推進することで、経済成長と環境保全の両立を図ります。',
  'monologue',
  'N1',
  ARRAY['委員'],
  '環境審議会での脱炭素政策に関する提言発表',
  '[{"word":"カーボンニュートラル","reading":"カーボンニュートラル","meaning_ko":"탄소 중립"},{"word":"再生可能エネルギー","reading":"さいせいかのうエネルギー","meaning_ko":"재생 가능 에너지"},{"word":"カーボンプライシング","reading":"カーボンプライシング","meaning_ko":"탄소 가격제"},{"word":"ESG投資","reading":"イーエスジーとうし","meaning_ko":"ESG 투자"},{"word":"公正な移行","reading":"こうせいないこう","meaning_ko":"공정한 전환"},{"word":"情報開示","reading":"じょうほうかいじ","meaning_ko":"정보 공개"}]'::jsonb,
  '위원: 환경심의회의 정책 제언을 발표하겠습니다. 2050년 탄소 중립 달성을 향해 다음 5가지 중점 시책을 제언합니다. 첫째, 재생 가능 에너지 도입 가속입니다. 해상 풍력발전의 대규모 전개와 차세대 태양광 패널의 기술 개발을 추진합니다. 2035년까지 전력 공급의 50%를 재에너지로 충당하는 것을 목표로 합니다. 둘째, 수소 사회의 실현입니다. 그린 수소의 제조 비용을 현재의 3분의 1로 저감하고, 운수·산업 부문의 수소 이용을 확대합니다. 셋째, 탄소 가격제 도입입니다. 배출량 거래 제도와 탄소세의 조합을 통해 시장 메커니즘을 활용한 배출 삭감을 촉진합니다. 다만 국제 경쟁력에 대한 영향을 고려하여 단계적 도입으로 해야 합니다. 넷째, 그린 파이낸스 확충입니다. 기후변동 관련 정보 공개를 의무화하고 ESG 투자 흐름을 가속화합니다. 다섯째, 공정한 전환의 확보입니다. 석탄 화력발전소 폐지에 따른 고용 영향에 대해 직업 훈련과 지역 경제 전환 지원을 합니다. 이러한 시책을 통합적으로 추진하여 경제 성장과 환경 보전의 양립을 도모합니다.',
  33
);

-- N1-14: 文学賞選考委員会の議論 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '文学賞選考委員会の議論',
  '委員長：最終候補作三作品について、順に議論してまいります。まず、「消えゆく言葉」について、山田委員からご意見をお願いします。\n山田委員：言語の消滅をテーマにした意欲作です。著者の筆力は確かで、方言話者の最後の世代を描く筆致には胸を打たれます。しかし、後半の展開がやや説教臭くなるのが惜しまれます。\n佐藤委員：私は異なる見解です。後半の展開こそが、この作品の核心ではないでしょうか。言語の消失が文化の消失に直結するという命題を、個人の物語を通して普遍的なテーマに昇華させている点を高く評価します。\n委員長：次に「鋼の庭」についてはいかがでしょうか。\n山田委員：都市再開発に翻弄される住民の姿を、緻密な取材に基づいて描いた力作です。社会小説としての完成度は三作品の中で最も高いと思います。\n佐藤委員：構成の巧みさは認めますが、登場人物の造形にやや類型的な面が見られます。善悪の二項対立に陥っている点が、文学作品としての奥行きを損なっています。\n委員長：最後に「海の向こうの灯」について。\n佐藤委員：文体の革新性において、他の二作品を凌駕しています。複数の時間軸を行き来しながらも、読者を引き込む語りの力は卓越しています。今回の受賞にふさわしいのは、この作品だと考えます。',
  'meeting',
  'N1',
  ARRAY['委員長', '山田委員', '佐藤委員'],
  '文学賞の選考委員会での最終候補作品に関する議論',
  '[{"word":"筆力","reading":"ひつりょく","meaning_ko":"필력"},{"word":"筆致","reading":"ひっち","meaning_ko":"필치"},{"word":"昇華","reading":"しょうか","meaning_ko":"승화"},{"word":"緻密","reading":"ちみつ","meaning_ko":"치밀"},{"word":"造形","reading":"ぞうけい","meaning_ko":"조형"},{"word":"凌駕","reading":"りょうが","meaning_ko":"능가"}]'::jsonb,
  '위원장: 최종 후보작 3작품에 대해 순서대로 논의하겠습니다. 먼저 "사라져 가는 말"에 대해 야마다 위원의 의견을 부탁합니다.\n야마다 위원: 언어의 소멸을 주제로 한 의욕작입니다. 저자의 필력은 확실하고, 방언 화자의 마지막 세대를 그리는 필치에 가슴이 뭉클합니다. 다만 후반부 전개가 다소 설교조가 되는 것이 아쉽습니다.\n사토 위원: 저는 다른 견해입니다. 후반부 전개야말로 이 작품의 핵심이 아닐까요? 언어의 소실이 문화의 소실로 직결된다는 명제를 개인의 이야기를 통해 보편적 주제로 승화시킨 점을 높이 평가합니다.\n위원장: 다음으로 "강철의 정원"은 어떠신가요?\n야마다 위원: 도시 재개발에 휘둘리는 주민의 모습을 치밀한 취재에 기반해 그린 역작입니다. 사회소설로서의 완성도는 세 작품 중 가장 높다고 생각합니다.\n사토 위원: 구성의 교묘함은 인정하지만 등장인물 조형에 다소 유형적인 면이 보입니다. 선악의 이항 대립에 빠진 점이 문학 작품으로서의 깊이를 해치고 있습니다.\n위원장: 마지막으로 "바다 건너의 불빛"에 대해.\n사토 위원: 문체의 혁신성에서 다른 두 작품을 능가합니다. 복수의 시간축을 오가면서도 독자를 끌어들이는 서사의 힘은 탁월합니다. 이번 수상에 어울리는 것은 이 작품이라고 생각합니다.',
  34
);

-- N1-15: 災害医療の最前線 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '災害医療の最前線',
  '司会：本日は「能登半島地震における医療支援の教訓」と題し、DMATの活動報告をいただきます。\n医師：DMATは、発災後四十八時間以内に被災地に入り、急性期の医療支援を行う専門チームです。今回の地震では、半島特有の地理的制約により、道路の寸断が甚大で、初動に大きな課題がありました。ヘリコプターによる搬送が不可欠でしたが、着陸可能な場所が限られており、搬送の優先順位付け、いわゆるトリアージの判断が極めて重要でした。\n看護師：避難所における感染症対策も深刻な問題でした。インフルエンザやノロウイルスのクラスターが複数発生し、限られた医薬品と人員で対応せざるを得ませんでした。避難所の衛生環境の整備に関するガイドラインの見直しが急務です。\n医師：慢性疾患を抱える患者さんへの対応も課題でした。常備薬を持ち出せなかった方や、透析が必要な患者さんの搬送は、命に関わる緊急の課題でした。お薬手帳の電子化や、医療情報の広域共有システムの構築が、今後の災害に備える上で不可欠です。\n司会：平時からの備えが、有事の際の対応力を決定づけるということですね。\n医師：その通りです。「備えあれば憂いなし」という言葉がありますが、災害医療においてはまさにその通りであり、訓練と準備を怠ってはなりません。',
  'dialogue',
  'N1',
  ARRAY['司会', '医師', '看護師'],
  '災害医療シンポジウムでのDMAT活動報告',
  '[{"word":"DMAT","reading":"ディーマット","meaning_ko":"재해의료지원팀"},{"word":"寸断","reading":"すんだん","meaning_ko":"단절"},{"word":"トリアージ","reading":"トリアージ","meaning_ko":"환자분류"},{"word":"クラスター","reading":"クラスター","meaning_ko":"집단 감염"},{"word":"透析","reading":"とうせき","meaning_ko":"투석"},{"word":"お薬手帳","reading":"おくすりてちょう","meaning_ko":"약 수첩"}]'::jsonb,
  '사회자: 오늘은 "노토반도 지진에서의 의료 지원의 교훈"이라는 주제로 DMAT의 활동 보고를 듣겠습니다.\n의사: DMAT는 발재 후 48시간 이내에 피해 지역에 들어가 급성기 의료 지원을 하는 전문 팀입니다. 이번 지진에서는 반도 특유의 지리적 제약으로 도로 단절이 심각하여 초동에 큰 과제가 있었습니다. 헬리콥터에 의한 수송이 불가결했지만 착륙 가능한 장소가 제한되어 수송 우선순위, 이른바 트리아지 판단이 극히 중요했습니다.\n간호사: 대피소에서의 감염증 대책도 심각한 문제였습니다. 인플루엔자와 노로바이러스 집단 감염이 복수 발생했고, 제한된 의약품과 인원으로 대응할 수밖에 없었습니다. 대피소의 위생 환경 정비에 관한 가이드라인 재검토가 급선무입니다.\n의사: 만성 질환을 가진 환자분들에 대한 대응도 과제였습니다. 상비약을 가지고 나오지 못한 분이나 투석이 필요한 환자의 수송은 생명과 관련된 긴급 과제였습니다. 약 수첩의 전자화나 의료 정보의 광역 공유 시스템 구축이 향후 재해에 대비하는 데 불가결합니다.\n사회자: 평시의 대비가 유사시 대응력을 결정짓는다는 것이군요.\n의사: 맞습니다. "대비가 있으면 근심이 없다"는 말이 있지만, 재해 의료에서는 정말 그대로이며, 훈련과 준비를 게을리해서는 안 됩니다.',
  35
);

-- N2-21: 製品リコールの社内対応 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '製品リコールの社内対応',
  '部長：緊急会議を始めます。先ほど品質管理部から報告がありましたが、当社の電子レンジ「クックマスター3000」について、発火の恐れがあることが判明しました。すでに全国で三件の事故報告が上がっています。\n課長：具体的にどの部品に問題があるのでしょうか。\n部長：電源基板のコンデンサーが経年劣化により過熱する可能性があります。対象は二〇二三年六月から十二月に製造されたロットで、約五万台が該当します。\n品質管理担当：消費者庁への届出は本日中に完了させます。リコール告知はウェブサイト、新聞広告、そして販売店への通知を並行して進めます。\n部長：お客様対応のコールセンターは明日から増員してください。交換品の手配はいつ頃になりますか。\n課長：代替品の在庫確認を急いでおります。二週間以内に発送開始できる見込みです。\n部長：とにかく安全を最優先にしてください。費用の問題は後回しです。',
  'meeting',
  'N2',
  ARRAY['部長', '課長', '品質管理担当'],
  '製品の安全性問題に関する社内緊急会議',
  '[{"word":"リコール","reading":"リコール","meaning_ko":"리콜"},{"word":"発火","reading":"はっか","meaning_ko":"발화"},{"word":"コンデンサー","reading":"コンデンサー","meaning_ko":"콘덴서"},{"word":"経年劣化","reading":"けいねんれっか","meaning_ko":"경년 열화"},{"word":"届出","reading":"とどけで","meaning_ko":"신고"}]'::jsonb,
  '부장: 긴급 회의를 시작합니다. 방금 품질관리부에서 보고가 있었는데, 우리 회사의 전자레인지 "쿡마스터 3000"에 발화 우려가 있는 것으로 판명되었습니다. 이미 전국에서 3건의 사고 보고가 올라왔습니다.\n과장: 구체적으로 어떤 부품에 문제가 있는 건가요?\n부장: 전원 기판의 콘덴서가 경년 열화로 과열될 가능성이 있습니다. 대상은 2023년 6월부터 12월에 제조된 로트로, 약 5만 대가 해당됩니다.\n품질관리 담당: 소비자청 신고는 오늘 중으로 완료하겠습니다. 리콜 고지는 웹사이트, 신문 광고, 그리고 판매점 통지를 병행하여 진행합니다.\n부장: 고객 대응 콜센터는 내일부터 인원을 증원해 주세요. 교환품 수배는 언제쯤 가능합니까?\n과장: 대체품 재고 확인을 서두르고 있습니다. 2주 이내에 발송 개시할 수 있을 전망입니다.\n부장: 어쨌든 안전을 최우선으로 해 주세요. 비용 문제는 후순위입니다.',
  11
);

-- N2-22: 留学生向け奨学金説明会 (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '留学生向け奨学金説明会',
  '担当者：本日は、来年度の留学生向け奨学金制度についてご説明いたします。まず、文部科学省の国費奨学金についてです。こちらは月額十四万四千円が支給され、授業料も全額免除となります。応募資格は、学部三年生以上で、GPAが三・〇以上の方です。\n次に、学内独自の奨学金についてご案内します。「グローバルリーダー奨学金」は年間五十万円の給付型で、返済の必要はありません。ただし、毎学期の成績報告と、留学生交流イベントへの参加が条件となっています。\n最後に、民間企業の奨学金ですが、今年度は三社から募集が来ております。いずれも月額五万円から八万円の給付で、卒業後にその企業への就職義務はありませんが、インターンシップへの参加が求められます。\n書類の提出期限は来月末です。不明な点があれば、国際交流課の窓口までお越しください。',
  'announcement',
  'N2',
  ARRAY['担当者'],
  '大学の留学生向け奨学金制度説明会',
  '[{"word":"奨学金","reading":"しょうがくきん","meaning_ko":"장학금"},{"word":"国費","reading":"こくひ","meaning_ko":"국비"},{"word":"支給","reading":"しきゅう","meaning_ko":"지급"},{"word":"給付型","reading":"きゅうふがた","meaning_ko":"급부형"},{"word":"免除","reading":"めんじょ","meaning_ko":"면제"}]'::jsonb,
  '담당자: 오늘은 내년도 유학생용 장학금 제도에 대해 설명드리겠습니다. 먼저 문부과학성의 국비 장학금입니다. 월 14만 4천 엔이 지급되며 수업료도 전액 면제됩니다. 응모 자격은 학부 3학년 이상으로 GPA 3.0 이상인 분입니다.\n다음으로 학내 자체 장학금에 대해 안내합니다. "글로벌 리더 장학금"은 연간 50만 엔의 급부형으로 상환 필요가 없습니다. 다만 매 학기 성적 보고와 유학생 교류 이벤트 참가가 조건입니다.\n마지막으로 민간 기업 장학금인데, 올해는 3개사에서 모집이 왔습니다. 모두 월 5만 엔에서 8만 엔의 급부로, 졸업 후 해당 기업 취직 의무는 없지만 인턴십 참가가 요구됩니다.\n서류 제출 기한은 다음 달 말입니다. 불명확한 점이 있으면 국제교류과 창구로 오세요.',
  12
);

-- N2-23: ITシステム障害の報告 (phone_call)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'ITシステム障害の報告',
  'エンジニア：お疲れ様です。システム運用課の田中です。本日午前九時三十分頃から、社内の受発注システムに障害が発生しております。\nマネージャー：影響範囲はどの程度ですか。\nエンジニア：現在、全社の受注入力ができない状態です。原因はデータベースサーバーのディスク容量不足で、ログファイルが想定以上に肥大化していたことが判明しています。\nマネージャー：復旧の見込みは。\nエンジニア：不要なログの削除と、一時的なディスク領域の拡張を進めており、正午までには復旧できる見込みです。ただし、根本的な対策として、ログのローテーション設定の見直しとディスク監視の閾値変更が必要です。\nマネージャー：各部署への影響はどう対応していますか。\nエンジニア：営業部と物流部には既に連絡済みで、復旧までの間はFAXと電話で受注を受け付けるよう代替手順を案内しています。\nマネージャー：了解しました。復旧し次第、全社メールで報告してください。',
  'phone_call',
  'N2',
  ARRAY['エンジニア', 'マネージャー'],
  'システム障害発生時の上司への電話報告',
  '[{"word":"受発注","reading":"じゅはっちゅう","meaning_ko":"수발주"},{"word":"障害","reading":"しょうがい","meaning_ko":"장애"},{"word":"肥大化","reading":"ひだいか","meaning_ko":"비대화"},{"word":"復旧","reading":"ふっきゅう","meaning_ko":"복구"},{"word":"閾値","reading":"しきいち","meaning_ko":"임계값"}]'::jsonb,
  '엔지니어: 수고하십니다. 시스템 운용과의 다나카입니다. 오늘 오전 9시 30분경부터 사내 수발주 시스템에 장애가 발생하고 있습니다.\n매니저: 영향 범위는 어느 정도입니까?\n엔지니어: 현재 전사의 수주 입력이 불가능한 상태입니다. 원인은 데이터베이스 서버의 디스크 용량 부족으로, 로그 파일이 예상 이상으로 비대화된 것으로 판명되었습니다.\n매니저: 복구 전망은요?\n엔지니어: 불필요한 로그 삭제와 일시적인 디스크 영역 확장을 진행 중이며, 정오까지는 복구할 수 있을 전망입니다. 다만 근본적 대책으로 로그 로테이션 설정 재검토와 디스크 감시 임계값 변경이 필요합니다.\n매니저: 각 부서에 대한 영향은 어떻게 대응하고 있습니까?\n엔지니어: 영업부와 물류부에는 이미 연락을 마쳤으며, 복구까지 팩스와 전화로 수주를 받도록 대체 절차를 안내하고 있습니다.\n매니저: 알겠습니다. 복구되는 대로 전사 메일로 보고해 주세요.',
  13
);

-- N2-24: 新入社員研修のスケジュール (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '新入社員研修のスケジュール',
  '人事担当：新入社員の皆さん、入社おめでとうございます。これから二週間の研修スケジュールについてご説明します。\n初日と二日目は、会社の経営理念と組織構成についての座学です。三日目からは、ビジネスマナー研修に入ります。名刺交換、電話応対、メールの書き方など、社会人としての基本を学んでいただきます。\n二週目は各部署へのローテーション研修です。営業、企画、技術、管理の四部署を各一日ずつ回り、業務内容を体験していただきます。最終日には配属希望のアンケートを実施します。\n研修期間中の出退勤は、午前八時半から午後五時半です。昼休みは十二時から一時間です。社員食堂は一階にありますので、社員証を提示して利用してください。\nなお、研修中に体調不良等がありましたら、遠慮なく人事課までご連絡ください。',
  'announcement',
  'N2',
  ARRAY['人事担当'],
  '新入社員向けの研修オリエンテーション',
  '[{"word":"経営理念","reading":"けいえいりねん","meaning_ko":"경영 이념"},{"word":"座学","reading":"ざがく","meaning_ko":"좌학, 이론 수업"},{"word":"ローテーション","reading":"ローテーション","meaning_ko":"로테이션"},{"word":"配属","reading":"はいぞく","meaning_ko":"배속"},{"word":"出退勤","reading":"しゅったいきん","meaning_ko":"출퇴근"}]'::jsonb,
  '인사 담당: 신입사원 여러분, 입사를 축하합니다. 지금부터 2주간의 연수 스케줄에 대해 설명드리겠습니다.\n첫째 날과 둘째 날은 회사의 경영 이념과 조직 구성에 대한 이론 수업입니다. 셋째 날부터는 비즈니스 매너 연수에 들어갑니다. 명함 교환, 전화 응대, 메일 작성법 등 직장인으로서의 기본을 배우게 됩니다.\n둘째 주는 각 부서 로테이션 연수입니다. 영업, 기획, 기술, 관리 4개 부서를 각 1일씩 돌며 업무 내용을 체험합니다. 마지막 날에는 배속 희망 설문을 실시합니다.\n연수 기간 중 출퇴근은 오전 8시 30분부터 오후 5시 30분입니다. 점심시간은 12시부터 1시간입니다. 사원 식당은 1층에 있으니 사원증을 제시하여 이용해 주세요.\n참고로 연수 중 컨디션 불량 등이 있으시면 주저하지 마시고 인사과로 연락 주세요.',
  14
);

-- N2-25: マンション管理組合の総会 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  'マンション管理組合の総会',
  '理事長：第二十回定期総会を開会いたします。本日の議題は三つです。まず第一号議案、昨年度の決算報告について、会計担当よりご説明いたします。\n会計：昨年度の管理費収入は一千二百万円、支出は一千百五十万円で、五十万円の黒字となりました。修繕積立金の残高は現在三千万円です。\n理事長：続いて第二号議案、エレベーターの更新工事についてです。築二十五年を経過し、部品の供給が終了するため、全面的な入れ替えが必要となります。見積もりは二社から取っており、A社が二千五百万円、B社が二千八百万円です。\n住民A：修繕積立金だけでは足りないと思いますが、不足分はどうするのでしょうか。\n理事長：金融機関からの借り入れを検討しております。返済は月々の管理費に上乗せする形で、一戸あたり月額三千円程度の負担増となる見込みです。\n住民B：工事期間中、エレベーターは使えなくなるのですか。\n理事長：約一か月間、使用できなくなります。高層階の方にはご不便をおかけしますが、ご理解をお願いいたします。',
  'meeting',
  'N2',
  ARRAY['理事長', '会計', '住民A', '住民B'],
  'マンション管理組合の定期総会',
  '[{"word":"管理組合","reading":"かんりくみあい","meaning_ko":"관리조합"},{"word":"決算","reading":"けっさん","meaning_ko":"결산"},{"word":"修繕積立金","reading":"しゅうぜんつみたてきん","meaning_ko":"수선 적립금"},{"word":"更新工事","reading":"こうしんこうじ","meaning_ko":"교체 공사"},{"word":"見積もり","reading":"みつもり","meaning_ko":"견적"}]'::jsonb,
  '이사장: 제20회 정기총회를 개회합니다. 오늘 의제는 3가지입니다. 먼저 제1호 안건, 작년도 결산 보고에 대해 회계 담당이 설명드리겠습니다.\n회계: 작년도 관리비 수입은 1,200만 엔, 지출은 1,150만 엔으로 50만 엔 흑자가 되었습니다. 수선 적립금 잔액은 현재 3,000만 엔입니다.\n이사장: 이어서 제2호 안건, 엘리베이터 교체 공사에 대해서입니다. 건축 후 25년이 경과하여 부품 공급이 종료되므로 전면 교체가 필요합니다. 견적은 2개사에서 받았으며, A사 2,500만 엔, B사 2,800만 엔입니다.\n주민A: 수선 적립금만으로는 부족할 것 같은데, 부족분은 어떻게 하시는 건가요?\n이사장: 금융기관에서의 차입을 검토하고 있습니다. 상환은 월 관리비에 가산하는 형태로, 한 세대당 월 3,000엔 정도의 부담 증가가 될 전망입니다.\n주민B: 공사 기간 중 엘리베이터를 사용할 수 없게 되나요?\n이사장: 약 1개월간 사용할 수 없게 됩니다. 고층 세대분들께는 불편을 끼치게 되지만 양해를 부탁드립니다.',
  15
);

-- N2-26: 環境配慮型オフィスの紹介 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '環境配慮型オフィスの紹介',
  'ガイド：当社の新オフィスは、環境に配慮した最先端の設計となっております。まず、屋上には太陽光パネルを設置しており、オフィスで使用する電力の約三十パーセントをまかなっています。また、雨水を集めてトイレの洗浄水や植栽の水やりに再利用するシステムも導入しました。\n窓ガラスには断熱性の高い複層ガラスを採用し、冷暖房の効率を大幅に向上させています。照明はすべてLEDで、人感センサーにより無駄な点灯を防いでいます。\nオフィス家具にも工夫があります。デスクや棚は再生木材を使用しており、椅子にはリサイクルプラスチックが使われています。壁面には緑化パネルを設置し、空気の浄化とともに社員のリラックス効果も期待しています。\nこうした取り組みにより、従来のオフィスと比較して、CO2排出量を約四十パーセント削減することに成功しました。',
  'monologue',
  'N2',
  ARRAY['ガイド'],
  '環境配慮型の新オフィスのガイドツアー',
  '[{"word":"太陽光パネル","reading":"たいようこうパネル","meaning_ko":"태양광 패널"},{"word":"複層ガラス","reading":"ふくそうガラス","meaning_ko":"복층 유리"},{"word":"人感センサー","reading":"じんかんセンサー","meaning_ko":"인체 감지 센서"},{"word":"再生木材","reading":"さいせいもくざい","meaning_ko":"재생 목재"},{"word":"緑化","reading":"りょくか","meaning_ko":"녹화"}]'::jsonb,
  '가이드: 우리 회사의 새 사무실은 환경을 배려한 최첨단 설계로 되어 있습니다. 먼저 옥상에는 태양광 패널을 설치하여 사무실에서 사용하는 전력의 약 30%를 충당하고 있습니다. 또한 빗물을 모아 화장실 세정수나 식재 물주기에 재이용하는 시스템도 도입했습니다.\n창유리에는 단열성이 높은 복층 유리를 채용하여 냉난방 효율을 대폭 향상시키고 있습니다. 조명은 전부 LED이며, 인체 감지 센서로 불필요한 점등을 방지합니다.\n사무용 가구에도 공을 들였습니다. 책상과 선반은 재생 목재를 사용하고 있으며, 의자에는 재활용 플라스틱이 사용되었습니다. 벽면에는 녹화 패널을 설치하여 공기 정화와 함께 직원의 릴랙스 효과도 기대하고 있습니다.\n이러한 노력으로 기존 사무실 대비 CO2 배출량을 약 40% 삭감하는 데 성공했습니다.',
  16
);

-- N2-27: 保険の見直し相談 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '保険の見直し相談',
  'お客様：子供が生まれたので、保険を見直したいと思っているんですが。\n担当者：おめでとうございます。お子様が生まれると、必要な保障の内容が大きく変わりますので、見直しは良いタイミングですね。現在ご加入の保険を確認させていただけますか。\nお客様：今は医療保険だけ入っています。月額三千円ぐらいです。\n担当者：なるほど。お子様がいらっしゃる場合、万が一のことを考えて、生命保険への加入をおすすめします。一家の大黒柱に何かあった場合の生活費や、お子様の教育費を考慮する必要があります。\nお客様：教育費というと、どのくらい必要なんでしょうか。\n担当者：大学まで公立の場合で約一千万円、私立ですと二千万円以上かかることもあります。学資保険という選択肢もございます。毎月一定額を積み立てて、お子様の進学時にまとまった金額を受け取れます。\nお客様：生命保険と学資保険、両方入ったほうがいいですか。\n担当者：ご家庭の状況によりますが、まずは生命保険を優先し、余裕があれば学資保険もご検討ください。',
  'dialogue',
  'N2',
  ARRAY['お客様', '担当者'],
  '保険窓口での見直し相談',
  '[{"word":"保障","reading":"ほしょう","meaning_ko":"보장"},{"word":"加入","reading":"かにゅう","meaning_ko":"가입"},{"word":"大黒柱","reading":"だいこくばしら","meaning_ko":"대들보, 가장"},{"word":"学資保険","reading":"がくしほけん","meaning_ko":"학자금 보험"},{"word":"積み立て","reading":"つみたて","meaning_ko":"적립"}]'::jsonb,
  '고객: 아이가 태어나서 보험을 재검토하고 싶은데요.\n담당자: 축하합니다. 자녀분이 태어나면 필요한 보장 내용이 크게 달라지므로 재검토하기 좋은 타이밍이시네요. 현재 가입하신 보험을 확인해도 될까요?\n고객: 지금은 의료보험만 들어 있습니다. 월 3,000엔 정도요.\n담당자: 그렇군요. 자녀분이 계신 경우, 만일의 사태를 생각하여 생명보험 가입을 권해 드립니다. 가장에게 무슨 일이 생겼을 때의 생활비나 자녀분의 교육비를 고려할 필요가 있습니다.\n고객: 교육비라 하면 얼마나 필요한 건가요?\n담당자: 대학까지 공립인 경우 약 1,000만 엔, 사립이면 2,000만 엔 이상 들 수도 있습니다. 학자금 보험이라는 선택지도 있습니다. 매월 일정액을 적립하여 자녀분의 진학 시에 목돈을 받을 수 있습니다.\n고객: 생명보험과 학자금 보험 둘 다 드는 게 좋을까요?\n담당자: 가정 상황에 따르지만, 먼저 생명보험을 우선하시고 여유가 있으시면 학자금 보험도 검토해 주세요.',
  17
);

-- N2-28: 地域防災訓練のお知らせ (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '地域防災訓練のお知らせ',
  '自治会長：みなさん、こんにちは。来月十五日に予定している地域防災訓練についてお知らせします。\n今年は、震度六強の地震が発生したという想定で訓練を行います。朝九時にサイレンが鳴りますので、まず各自で身の安全を確保してください。揺れが収まったら、最寄りの一時集合場所に移動してください。第一地区は中央公園、第二地区は市立小学校です。\n集合場所では安否確認を行った後、避難所の設営訓練を実施します。テントの組み立て、簡易トイレの設置、非常食の配布など、実際の災害を想定した実践的な訓練です。\nまた、今年から新たに、ペット同行避難の訓練も取り入れます。ペットを飼っている方は、ケージやリードを持参してください。\n消防署からは起震車も来ますので、お子さん連れの方もぜひご参加ください。雨天の場合は翌日に延期します。',
  'announcement',
  'N2',
  ARRAY['自治会長'],
  '地域の防災訓練に関する説明会',
  '[{"word":"防災訓練","reading":"ぼうさいくんれん","meaning_ko":"방재 훈련"},{"word":"震度","reading":"しんど","meaning_ko":"진도"},{"word":"安否確認","reading":"あんぴかくにん","meaning_ko":"안부 확인"},{"word":"非常食","reading":"ひじょうしょく","meaning_ko":"비상식량"},{"word":"起震車","reading":"きしんしゃ","meaning_ko":"지진 체험차"}]'::jsonb,
  '자치회장: 여러분 안녕하세요. 다음 달 15일에 예정된 지역 방재 훈련에 대해 알려드립니다.\n올해는 진도 6강의 지진이 발생했다는 가정으로 훈련을 실시합니다. 아침 9시에 사이렌이 울리면 먼저 각자 신변 안전을 확보해 주세요. 흔들림이 멈추면 가장 가까운 일시 집합 장소로 이동해 주세요. 제1지구는 중앙공원, 제2지구는 시립 초등학교입니다.\n집합 장소에서는 안부 확인을 한 후 대피소 설영 훈련을 실시합니다. 텐트 조립, 간이 화장실 설치, 비상식량 배포 등 실제 재해를 상정한 실전적 훈련입니다.\n또한 올해부터 새롭게 반려동물 동반 대피 훈련도 도입합니다. 반려동물을 키우시는 분은 케이지나 리드를 지참해 주세요.\n소방서에서 지진 체험차도 오니 자녀를 동반한 분들도 꼭 참가해 주세요. 우천 시에는 다음 날로 연기합니다.',
  18
);

-- N2-29: 転職エージェントとの面談 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '転職エージェントとの面談',
  'エージェント：本日はご来社いただきありがとうございます。ご登録いただいた情報を拝見しましたが、現在はIT企業でシステムエンジニアをされているんですね。\n求職者：はい、三年ほど勤めています。スキルアップのために転職を考えているんですが。\nエージェント：なるほど。希望する条件をお聞かせいただけますか。\n求職者：年収は今より上がればいいなと思っています。現在は四百五十万円です。あと、リモートワークができる会社が希望です。\nエージェント：ITエンジニアの求人は現在非常に多いです。年収五百万円以上でリモートワーク可能な案件もたくさんあります。使える言語や技術をもう少し詳しく教えていただけますか。\n求職者：JavaとPythonが得意で、AWSの経験が二年ほどあります。\nエージェント：クラウドの経験があるのは強みですね。まずは三社ほどピックアップして、書類選考に進めてみましょう。面接対策もサポートしますので、ご安心ください。\n求職者：よろしくお願いします。在職中なので、面接は夕方以降だと助かります。',
  'dialogue',
  'N2',
  ARRAY['エージェント', '求職者'],
  '転職エージェントのオフィスでの初回面談',
  '[{"word":"転職","reading":"てんしょく","meaning_ko":"이직"},{"word":"求人","reading":"きゅうじん","meaning_ko":"구인"},{"word":"案件","reading":"あんけん","meaning_ko":"안건, 건"},{"word":"書類選考","reading":"しょるいせんこう","meaning_ko":"서류 전형"},{"word":"在職中","reading":"ざいしょくちゅう","meaning_ko":"재직 중"}]'::jsonb,
  '에이전트: 오늘 방문해 주셔서 감사합니다. 등록해 주신 정보를 봤는데, 현재 IT 기업에서 시스템 엔지니어로 근무하고 계시군요.\n구직자: 네, 3년 정도 근무하고 있습니다. 스킬 향상을 위해 이직을 생각하고 있는데요.\n에이전트: 그렇군요. 희망하시는 조건을 알려주시겠습니까?\n구직자: 연봉은 지금보다 올랐으면 좋겠습니다. 현재는 450만 엔입니다. 그리고 리모트 워크가 가능한 회사를 희망합니다.\n에이전트: IT 엔지니어 구인은 현재 매우 많습니다. 연봉 500만 엔 이상에 리모트 워크 가능한 건도 많이 있습니다. 사용 가능한 언어나 기술을 좀 더 자세히 알려주시겠습니까?\n구직자: Java와 Python이 특기이고, AWS 경험이 2년 정도 있습니다.\n에이전트: 클라우드 경험이 있으신 건 강점이시네요. 우선 3개사 정도 선정하여 서류 전형을 진행해 보겠습니다. 면접 대책도 지원하니 안심하세요.\n구직자: 잘 부탁드립니다. 재직 중이라 면접은 저녁 이후가 좋겠습니다.',
  19
);

-- N2-30: 料理教室の案内 (instruction)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '料理教室の案内',
  '先生：今日は和食の基本、肉じゃがを作りましょう。まず材料の確認です。じゃがいも三個、にんじん一本、玉ねぎ一個、牛肉の薄切り二百グラム、そして調味料はしょうゆ、みりん、砂糖、だしの素です。\nまず、じゃがいもは皮をむいて四等分に切ります。水にさらしてでんぷんを抜いてください。にんじんは乱切り、玉ねぎはくし切りにします。\n鍋にサラダ油を熱して、まず牛肉を炒めます。色が変わったら、玉ねぎを加えてしんなりするまで炒めてください。次に、じゃがいもとにんじんを加えて、全体に油が回るように炒めます。\nだし汁を材料がひたひたになるまで注ぎ、砂糖大さじ二、みりん大さじ二、しょうゆ大さじ三を加えます。落としぶたをして、中火で十五分ほど煮込みます。じゃがいもに竹串がすっと通れば完成です。\n煮物は冷める時に味がしみ込むので、少し置いてから食べると、よりおいしくいただけますよ。',
  'instruction',
  'N2',
  ARRAY['先生'],
  '和食料理教室での肉じゃが調理指導',
  '[{"word":"薄切り","reading":"うすぎり","meaning_ko":"얇게 자르기"},{"word":"乱切り","reading":"らんぎり","meaning_ko":"어슷썰기"},{"word":"くし切り","reading":"くしぎり","meaning_ko":"빗살 모양 자르기"},{"word":"落としぶた","reading":"おとしぶた","meaning_ko":"떨어뜨림 뚜껑"},{"word":"しみ込む","reading":"しみこむ","meaning_ko":"배어들다"}]'::jsonb,
  '선생님: 오늘은 일식의 기본, 니쿠자가를 만들어 봅시다. 먼저 재료 확인입니다. 감자 3개, 당근 1개, 양파 1개, 소고기 얇게 썬 것 200g, 그리고 양념은 간장, 미림, 설탕, 다시노모토입니다.\n먼저 감자는 껍질을 벗겨 4등분으로 자릅니다. 물에 담가 전분을 빼 주세요. 당근은 어슷썰기, 양파는 빗살 모양으로 자릅니다.\n냄비에 식용유를 달구고 먼저 소고기를 볶습니다. 색이 변하면 양파를 넣어 숨이 죽을 때까지 볶아 주세요. 다음으로 감자와 당근을 넣어 전체에 기름이 돌도록 볶습니다.\n육수를 재료가 잠길 정도로 붓고 설탕 큰술 2, 미림 큰술 2, 간장 큰술 3을 넣습니다. 떨어뜨림 뚜껑을 하고 중불에서 15분 정도 끓입니다. 감자에 꼬치가 쑥 들어가면 완성입니다.\n조림 요리는 식을 때 맛이 배어들기 때문에 잠시 두었다가 먹으면 더 맛있게 드실 수 있어요.',
  20
);

-- N1-16: 国際金融市場の動向分析 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '国際金融市場の動向分析',
  'アナリスト：第三四半期の国際金融市場を振り返りますと、米国のFRBによる利上げの打ち止め観測が強まる中、世界的に株式市場は堅調に推移いたしました。一方、地政学的リスクの高まり、とりわけ中東情勢の緊迫化により、原油価格は一バレル九十ドル台まで上昇し、インフレ圧力の再燃が懸念されております。\n為替市場に目を転じますと、日米金利差の縮小期待から、円相場はドルに対して若干の円高方向に振れましたが、依然として歴史的な円安水準にとどまっております。日本銀行のイールドカーブ・コントロール政策の修正が市場の最大の関心事であり、その動向次第では、為替・債券市場に大きなボラティリティが生じる可能性がございます。\n新興国市場においては、中国経済の減速懸念が重しとなり、アジア通貨は総じて軟調でした。インドだけが例外的に堅調な経済成長を背景に、資金流入が続いております。',
  'monologue',
  'N1',
  ARRAY['アナリスト'],
  '金融機関の四半期市場レビューセミナー',
  '[{"word":"利上げ","reading":"りあげ","meaning_ko":"금리 인상"},{"word":"地政学的","reading":"ちせいがくてき","meaning_ko":"지정학적"},{"word":"イールドカーブ","reading":"イールドカーブ","meaning_ko":"수익률 곡선"},{"word":"ボラティリティ","reading":"ボラティリティ","meaning_ko":"변동성"},{"word":"軟調","reading":"なんちょう","meaning_ko":"연조, 약세"}]'::jsonb,
  '애널리스트: 제3사분기 국제 금융 시장을 돌아보면, 미국 FRB의 금리 인상 중단 관측이 강해지는 가운데 세계적으로 주식 시장은 견조하게 추이했습니다. 한편 지정학적 리스크 고조, 특히 중동 정세의 긴박화로 원유 가격이 배럴당 90달러대까지 상승하여 인플레이션 압력 재연이 우려되고 있습니다.\n환율 시장으로 눈을 돌리면, 미일 금리차 축소 기대에서 엔 시세는 달러 대비 약간의 엔고 방향으로 움직였으나, 여전히 역사적인 엔저 수준에 머물고 있습니다. 일본은행의 수익률 곡선 통제 정책 수정이 시장의 최대 관심사이며, 그 동향에 따라서는 환율·채권 시장에 큰 변동성이 발생할 가능성이 있습니다.\n신흥국 시장에서는 중국 경제 감속 우려가 부담이 되어 아시아 통화는 전반적으로 약세였습니다. 인도만이 예외적으로 견조한 경제 성장을 배경으로 자금 유입이 계속되고 있습니다.',
  36
);

-- N1-17: 先端医療技術の倫理的課題 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '先端医療技術の倫理的課題',
  '座長：本日は「ゲノム編集技術の臨床応用における倫理的課題」について、各委員のご見解を伺いたいと思います。\n医学部教授：CRISPR技術の進歩は目覚ましく、遺伝性疾患の根治的治療への道を開きつつあります。しかしながら、生殖細胞系列への介入、いわゆるジャームライン編集については、将来世代への影響が予測不能であり、極めて慎重な姿勢が求められます。\n生命倫理学者：そもそも、人間の遺伝子を操作するということは、何を意味するのかという根源的な問いに立ち返る必要があります。デザイナーベビーの問題にも通じますが、能力増強目的での利用と治療目的での利用の境界線を、どこに引くのかという合意形成が不可欠です。\n法学者：現行法制では、ゲノム編集の臨床応用に関する包括的な規制が存在しません。研究段階と臨床段階を明確に区分し、段階に応じた規制の枠組みを早急に整備すべきです。特に、インフォームドコンセントの在り方については、従来の枠組みでは不十分であり、将来世代の権利をいかに保護するかという観点が必要です。\n座長：国際的な規制の調和も重要な論点ですね。一国だけが規制を強化しても、いわゆる「規制の抜け穴」を求めて海外に流出する懸念があります。',
  'meeting',
  'N1',
  ARRAY['座長', '医学部教授', '生命倫理学者', '法学者'],
  '先端医療技術に関する倫理審査委員会',
  '[{"word":"ゲノム編集","reading":"ゲノムへんしゅう","meaning_ko":"유전체 편집"},{"word":"生殖細胞系列","reading":"せいしょくさいぼうけいれつ","meaning_ko":"생식세포 계열"},{"word":"デザイナーベビー","reading":"デザイナーベビー","meaning_ko":"맞춤형 아기"},{"word":"インフォームドコンセント","reading":"インフォームドコンセント","meaning_ko":"충분한 설명에 의한 동의"},{"word":"包括的","reading":"ほうかつてき","meaning_ko":"포괄적"}]'::jsonb,
  '좌장: 오늘은 "유전체 편집 기술의 임상 응용에서의 윤리적 과제"에 대해 각 위원의 견해를 듣고자 합니다.\n의학부 교수: CRISPR 기술의 진보는 눈부시며 유전성 질환의 근치적 치료로의 길을 열어가고 있습니다. 그러나 생식세포 계열에 대한 개입, 이른바 생식세포 편집에 대해서는 미래 세대에 대한 영향이 예측 불가능하며 극히 신중한 자세가 요구됩니다.\n생명윤리학자: 애초에 인간의 유전자를 조작한다는 것이 무엇을 의미하는지라는 근원적 물음으로 돌아갈 필요가 있습니다. 맞춤형 아기 문제와도 통하지만 능력 강화 목적의 이용과 치료 목적의 이용의 경계선을 어디에 그을지 합의 형성이 불가결합니다.\n법학자: 현행 법제에서는 유전체 편집의 임상 응용에 관한 포괄적 규제가 존재하지 않습니다. 연구 단계와 임상 단계를 명확히 구분하고 단계에 맞는 규제 틀을 조속히 정비해야 합니다. 특히 충분한 설명에 의한 동의의 형태에 대해서는 기존 틀로는 불충분하며 미래 세대의 권리를 어떻게 보호할지라는 관점이 필요합니다.\n좌장: 국제적 규제 조화도 중요한 논점이군요. 한 나라만 규제를 강화해도 이른바 "규제의 빈틈"을 찾아 해외로 유출될 우려가 있습니다.',
  37
);

-- N1-18: 伝統工芸の後継者問題 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '伝統工芸の後継者問題',
  'インタビュアー：先生は京都で四代続く漆芸家でいらっしゃいますが、伝統工芸の現状について、どのようにお考えですか。\n漆芸家：率直に申し上げて、危機的な状況です。私が修業を始めた四十年前には、京都だけでも百人以上の漆芸の職人がおりましたが、現在は二十人を切っております。しかも、その大半が六十代以上です。\nインタビュアー：後継者不足の原因は何でしょうか。\n漆芸家：最大の要因は、一人前になるまでに十年以上の修業期間を要し、その間の収入が極めて不安定であることです。現代の若者に、それだけの忍耐と犠牲を求めることの難しさは否めません。加えて、生活様式の変化により漆器の需要自体が縮小しています。\nインタビュアー：打開策はあるのでしょうか。\n漆芸家：私は二つの方向性があると考えています。一つは、伝統技法を現代のデザインやプロダクトに応用すること。もう一つは、海外市場の開拓です。欧州のラグジュアリーブランドとのコラボレーションなど、日本の漆の美しさを世界に発信する取り組みが始まっています。伝統を守るということは、変わらないことではなく、本質を保ちながら変化し続けることだと、私は信じております。',
  'dialogue',
  'N1',
  ARRAY['インタビュアー', '漆芸家'],
  '伝統工芸の漆芸家へのインタビュー',
  '[{"word":"漆芸","reading":"しつげい","meaning_ko":"칠예"},{"word":"修業","reading":"しゅぎょう","meaning_ko":"수업, 수련"},{"word":"一人前","reading":"いちにんまえ","meaning_ko":"한 사람 몫, 독립"},{"word":"忍耐","reading":"にんたい","meaning_ko":"인내"},{"word":"打開策","reading":"だかいさく","meaning_ko":"타개책"}]'::jsonb,
  '인터뷰어: 선생님은 교토에서 4대째 이어지는 칠예가이신데, 전통공예의 현황에 대해 어떻게 생각하십니까?\n칠예가: 솔직히 말씀드려 위기적 상황입니다. 제가 수련을 시작한 40년 전에는 교토만 해도 100명 이상의 칠예 장인이 있었지만, 현재는 20명이 안 됩니다. 게다가 대부분이 60대 이상입니다.\n인터뷰어: 후계자 부족의 원인은 무엇인가요?\n칠예가: 최대 요인은 한 사람 몫을 하기까지 10년 이상의 수련 기간이 필요하고 그 기간의 수입이 극히 불안정하다는 것입니다. 현대 젊은이에게 그만큼의 인내와 희생을 요구하기 어렵다는 점은 부정할 수 없습니다. 게다가 생활양식의 변화로 칠기 수요 자체가 축소되고 있습니다.\n인터뷰어: 타개책은 있는 건가요?\n칠예가: 저는 두 가지 방향성이 있다고 봅니다. 하나는 전통 기법을 현대 디자인이나 제품에 응용하는 것. 또 하나는 해외 시장 개척입니다. 유럽 럭셔리 브랜드와의 콜라보레이션 등 일본 칠의 아름다움을 세계에 알리는 노력이 시작되고 있습니다. 전통을 지킨다는 것은 변하지 않는 것이 아니라 본질을 유지하면서 변화를 계속하는 것이라고 저는 믿고 있습니다.',
  38
);

-- N1-19: 宇宙開発の国際協力 (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '宇宙開発の国際協力',
  '局長：JAXAは本日、アルテミス計画における日本の役割について、重要な発表をいたします。NASAとの協定に基づき、日本人宇宙飛行士が月面着陸ミッションに参加することが正式に決定いたしました。これは、アポロ計画以来、半世紀ぶりの有人月面探査であり、日本にとっては歴史的な一歩となります。\n日本の主な貢献は三つです。第一に、月周回有人拠点「ゲートウェイ」への居住モジュールの提供です。JAXAが開発する与圧モジュールは、国際宇宙ステーションで培った生命維持技術の粋を集めたものです。第二に、月面探査用の加圧ローバーの開発です。トヨタ自動車との共同開発により、宇宙飛行士が宇宙服なしで月面を長距離移動できる画期的な車両を実現します。第三に、月面での水資源探査です。月の南極域に存在すると推定される水氷の探査・採取技術を開発し、将来の月面基地建設に不可欠な資源の確保を目指します。\nこれらの取り組みを通じて、日本は宇宙開発の新たなフロンティアにおいて、不可欠なパートナーとしての地位を確立してまいります。',
  'announcement',
  'N1',
  ARRAY['局長'],
  'JAXAによる月面探査計画の記者発表',
  '[{"word":"アルテミス計画","reading":"アルテミスけいかく","meaning_ko":"아르테미스 계획"},{"word":"月周回","reading":"つきしゅうかい","meaning_ko":"달 주회"},{"word":"与圧モジュール","reading":"よあつモジュール","meaning_ko":"여압 모듈"},{"word":"加圧ローバー","reading":"かあつローバー","meaning_ko":"가압 로버"},{"word":"水氷","reading":"すいひょう","meaning_ko":"수빙"}]'::jsonb,
  '국장: JAXA는 오늘 아르테미스 계획에서의 일본의 역할에 대해 중요한 발표를 합니다. NASA와의 협정에 기반하여 일본인 우주비행사가 달 표면 착륙 미션에 참가하는 것이 정식으로 결정되었습니다. 이는 아폴로 계획 이래 반세기 만의 유인 달 탐사이며, 일본에게는 역사적인 한 걸음이 됩니다.\n일본의 주요 공헌은 세 가지입니다. 첫째, 달 주회 유인 거점 "게이트웨이"에 거주 모듈 제공입니다. JAXA가 개발하는 여압 모듈은 국제우주정거장에서 쌓은 생명유지 기술의 정수를 모은 것입니다. 둘째, 달 표면 탐사용 가압 로버 개발입니다. 도요타 자동차와의 공동 개발로 우주비행사가 우주복 없이 달 표면을 장거리 이동할 수 있는 획기적 차량을 실현합니다. 셋째, 달 표면에서의 수자원 탐사입니다. 달의 남극 지역에 존재할 것으로 추정되는 수빙의 탐사·채취 기술을 개발하여 미래 달 표면 기지 건설에 불가결한 자원 확보를 목표로 합니다.\n이러한 노력을 통해 일본은 우주 개발의 새로운 프런티어에서 불가결한 파트너로서의 지위를 확립해 나가겠습니다.',
  39
);

-- N1-20: 司法制度改革の論点 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '司法制度改革の論点',
  '座長：本日の法制審議会では、裁判員制度の十五年間の運用実績を踏まえた改善策について審議いたします。\n裁判官：裁判員制度は、国民の司法参加という理念のもと、一定の成果を上げてまいりました。しかしながら、裁判員の辞退率が年々上昇しており、現在は六十七パーセントに達しております。制度の持続可能性の観点から、抜本的な見直しが必要であると考えます。\n弁護士：辞退率の高さの背景には、裁判員の心理的負担の問題があります。凄惨な証拠写真への接触や、死刑を含む量刑判断の重圧は、一般市民には過大な負担です。PTSDを発症したケースも報告されており、メンタルヘルスケアの体制を拡充すべきです。\n法学者：制度設計の根本にも問題があります。対象事件を重大犯罪に限定しているため、裁判員が関与する事件は必然的に残虐性の高いものとなります。対象を拡大して、より広範な事件を扱うことで、一件あたりの負担を軽減するという選択肢も検討に値します。\n座長：守秘義務の範囲についても議論が必要ですね。現行制度では、裁判員経験者が評議の内容を一切話せないことが、制度への理解促進の妨げとなっているとの指摘があります。',
  'meeting',
  'N1',
  ARRAY['座長', '裁判官', '弁護士', '法学者'],
  '法制審議会での裁判員制度改革に関する審議',
  '[{"word":"裁判員制度","reading":"さいばんいんせいど","meaning_ko":"재판원 제도"},{"word":"辞退率","reading":"じたいりつ","meaning_ko":"사퇴율"},{"word":"量刑","reading":"りょうけい","meaning_ko":"양형"},{"word":"守秘義務","reading":"しゅひぎむ","meaning_ko":"비밀 유지 의무"},{"word":"評議","reading":"ひょうぎ","meaning_ko":"평의"}]'::jsonb,
  '좌장: 오늘 법제심의회에서는 재판원 제도의 15년간 운용 실적을 바탕으로 한 개선책에 대해 심의합니다.\n재판관: 재판원 제도는 국민의 사법 참여라는 이념 아래 일정한 성과를 거두어 왔습니다. 그러나 재판원 사퇴율이 해마다 상승하여 현재 67%에 달하고 있습니다. 제도의 지속가능성 관점에서 근본적인 재검토가 필요하다고 봅니다.\n변호사: 사퇴율 상승의 배경에는 재판원의 심리적 부담 문제가 있습니다. 참혹한 증거 사진 접촉이나 사형을 포함한 양형 판단의 중압감은 일반 시민에게 과도한 부담입니다. PTSD를 발병한 사례도 보고되어 있어 정신건강 케어 체제를 확충해야 합니다.\n법학자: 제도 설계의 근본에도 문제가 있습니다. 대상 사건을 중대 범죄로 한정하고 있어 재판원이 관여하는 사건은 필연적으로 잔혹성이 높은 것이 됩니다. 대상을 확대하여 더 넓은 범위의 사건을 다루는 것으로 건당 부담을 경감하는 선택지도 검토할 가치가 있습니다.\n좌장: 비밀 유지 의무 범위에 대해서도 논의가 필요하지요. 현행 제도에서는 재판원 경험자가 평의 내용을 일절 말할 수 없는 것이 제도에 대한 이해 촉진의 저해 요인이라는 지적이 있습니다.',
  40
);

-- N1-21: 人工知能と雇用の未来 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '人工知能と雇用の未来',
  '司会：「AIが変える労働市場の未来」をテーマに、パネルディスカッションを始めます。まず、経済学の観点から、山本教授にお伺いします。\n山本教授：産業革命以来、技術革新のたびに「機械が仕事を奪う」という懸念が繰り返されてきましたが、歴史的に見れば、技術革新は新たな雇用を創出してきました。しかし、生成AIの登場は、これまでの技術革新とは質的に異なります。ホワイトカラーの知的労働を代替する可能性がある点で、過去の自動化とは本質的に別次元の問題を提起しています。\nIT企業CEO：経営者の立場から申し上げますと、AIは人間を代替するものではなく、人間の能力を拡張するものです。重要なのは、AIと協働できる人材の育成です。弊社では、全社員にAIリテラシー研修を実施し、業務プロセスの中にAIを組み込む取り組みを進めています。\n労働組合代表：しかしながら、現実に解雇が発生しているのも事実です。リスキリングの機会が十分に提供されないまま、AIによる合理化が進められれば、社会的格差は拡大します。移行期においては、セーフティネットの拡充と、労使協議に基づく段階的な導入が不可欠です。',
  'dialogue',
  'N1',
  ARRAY['司会', '山本教授', 'IT企業CEO', '労働組合代表'],
  'AI時代の雇用に関するパネルディスカッション',
  '[{"word":"生成AI","reading":"せいせいエーアイ","meaning_ko":"생성 AI"},{"word":"ホワイトカラー","reading":"ホワイトカラー","meaning_ko":"사무직"},{"word":"リスキリング","reading":"リスキリング","meaning_ko":"리스킬링, 재교육"},{"word":"セーフティネット","reading":"セーフティネット","meaning_ko":"안전망"},{"word":"労使協議","reading":"ろうしきょうぎ","meaning_ko":"노사 협의"}]'::jsonb,
  '사회자: "AI가 바꾸는 노동 시장의 미래"를 주제로 패널 디스커션을 시작합니다. 먼저 경제학 관점에서 야마모토 교수님께 여쭙겠습니다.\n야마모토 교수: 산업혁명 이래 기술 혁신 때마다 "기계가 일자리를 빼앗는다"는 우려가 반복되어 왔지만, 역사적으로 보면 기술 혁신은 새로운 고용을 창출해 왔습니다. 그러나 생성 AI의 등장은 지금까지의 기술 혁신과는 질적으로 다릅니다. 사무직의 지적 노동을 대체할 가능성이 있다는 점에서 과거의 자동화와는 본질적으로 다른 차원의 문제를 제기하고 있습니다.\nIT 기업 CEO: 경영자 입장에서 말씀드리자면, AI는 인간을 대체하는 것이 아니라 인간의 능력을 확장하는 것입니다. 중요한 것은 AI와 협업할 수 있는 인재 육성입니다. 당사에서는 전 사원에게 AI 리터러시 연수를 실시하고 업무 프로세스에 AI를 접목하는 노력을 진행하고 있습니다.\n노동조합 대표: 하지만 현실에 해고가 발생하고 있는 것도 사실입니다. 리스킬링 기회가 충분히 제공되지 않은 채 AI에 의한 합리화가 추진되면 사회적 격차는 확대됩니다. 전환기에는 안전망 확충과 노사 협의에 기반한 단계적 도입이 불가결합니다.',
  41
);

-- N1-22: 文化財修復の最新技術 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '文化財修復の最新技術',
  '研究員：国宝の修復において、私たちが最も重視しているのは「可逆性」の原則です。すなわち、将来、より優れた技術が開発された際に、修復を元に戻せるようにしておくということです。この原則に基づき、近年導入された最新技術についてご紹介いたします。\nまず、三次元レーザースキャニングによるデジタルアーカイブです。ミクロン単位の精度で文化財の形状を記録し、万が一の損傷に備えた完全なデジタルツインを作成します。先日修復を終えた法隆寺の壁画では、この技術により、肉眼では判別できない経年変化のパターンを可視化することに成功しました。\n次に、蛍光X線分析による非破壊での顔料同定技術です。従来はサンプルの採取が必要でしたが、現在では作品に一切触れることなく、使用されている顔料の成分を特定できます。これにより、制作当時の色彩を科学的に復元することが可能となりました。\nさらに、和紙の補修においても革新が進んでいます。ナノセルロースファイバーを用いた補強技術により、劣化した和紙の強度を飛躍的に向上させることが可能となり、それでいて作品の風合いを損なわないという、相反する要求を両立させています。',
  'monologue',
  'N1',
  ARRAY['研究員'],
  '文化財修復技術に関する学術講演',
  '[{"word":"可逆性","reading":"かぎゃくせい","meaning_ko":"가역성"},{"word":"デジタルツイン","reading":"デジタルツイン","meaning_ko":"디지털 트윈"},{"word":"顔料同定","reading":"がんりょうどうてい","meaning_ko":"안료 동정"},{"word":"非破壊","reading":"ひはかい","meaning_ko":"비파괴"},{"word":"ナノセルロース","reading":"ナノセルロース","meaning_ko":"나노셀룰로스"}]'::jsonb,
  '연구원: 국보 수복에서 저희가 가장 중시하는 것은 "가역성"의 원칙입니다. 즉, 미래에 더 뛰어난 기술이 개발되었을 때 수복을 되돌릴 수 있도록 해 두는 것입니다. 이 원칙에 기반하여 최근 도입된 최신 기술을 소개하겠습니다.\n먼저 3차원 레이저 스캐닝에 의한 디지털 아카이브입니다. 마이크론 단위의 정밀도로 문화재의 형상을 기록하고 만일의 손상에 대비한 완전한 디지털 트윈을 작성합니다. 최근 수복을 마친 호류지 벽화에서는 이 기술로 육안으로는 판별할 수 없는 경년 변화 패턴을 가시화하는 데 성공했습니다.\n다음으로 형광 X선 분석에 의한 비파괴 안료 동정 기술입니다. 종래에는 시료 채취가 필요했지만 현재는 작품에 전혀 접촉하지 않고 사용된 안료의 성분을 특정할 수 있습니다. 이를 통해 제작 당시의 색채를 과학적으로 복원하는 것이 가능해졌습니다.\n나아가 와시 보수에서도 혁신이 진행되고 있습니다. 나노셀룰로스 파이버를 이용한 보강 기술로 열화된 와시의 강도를 비약적으로 향상시킬 수 있으면서도 작품의 질감을 해치지 않는다는 상반된 요구를 양립시키고 있습니다.',
  42
);

-- N1-23: 少子化対策の政策討論 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '少子化対策の政策討論',
  '議長：本日は、少子化対策の抜本強化に向けた政策パッケージについて議論いたします。昨年の出生数が七十万人を下回り、過去最少を更新しました。まず、厚生労働省の見解をお聞かせください。\n厚労省局長：少子化の要因は複合的であり、経済的不安、働き方の問題、価値観の多様化が絡み合っております。我々は「次元の異なる少子化対策」として、児童手当の拡充、育児休業給付率の引き上げ、そして保育の質と量の確保を三本の柱として推進しております。\n人口学者：しかしながら、これまでの少子化対策は十分な効果を挙げてこなかったのも事実です。フランスやスウェーデンの事例を見ますと、単なる経済的支援ではなく、社会全体の意識変革、特に男性の育児参加を促す制度設計が成功の鍵でした。日本の男性の育児休業取得率は、依然として三十パーセント程度にとどまっております。\n経済学者：マクロ経済の観点から申し上げますと、少子化は潜在成長率を押し下げ、社会保障制度の持続可能性を根幹から脅かします。移民政策を含めた人口戦略の策定が急務であり、出生率の回復と外国人材の受け入れを車の両輪として推進すべきです。',
  'meeting',
  'N1',
  ARRAY['議長', '厚労省局長', '人口学者', '経済学者'],
  '政府の少子化対策に関する有識者会議',
  '[{"word":"出生数","reading":"しゅっしょうすう","meaning_ko":"출생수"},{"word":"児童手当","reading":"じどうてあて","meaning_ko":"아동수당"},{"word":"育児休業","reading":"いくじきゅうぎょう","meaning_ko":"육아 휴직"},{"word":"潜在成長率","reading":"せんざいせいちょうりつ","meaning_ko":"잠재 성장률"},{"word":"車の両輪","reading":"くるまのりょうりん","meaning_ko":"수레의 두 바퀴(양립)"}]'::jsonb,
  '의장: 오늘은 저출산 대책의 근본적 강화를 위한 정책 패키지에 대해 논의합니다. 작년 출생수가 70만 명을 밑돌아 과거 최소를 경신했습니다. 먼저 후생노동성의 견해를 듣겠습니다.\n후생노동성 국장: 저출산의 요인은 복합적이며, 경제적 불안, 근무 방식의 문제, 가치관의 다양화가 얽혀 있습니다. 우리는 "차원이 다른 저출산 대책"으로서 아동수당 확충, 육아 휴직 급여율 인상, 그리고 보육의 질과 양 확보를 3개 기둥으로 추진하고 있습니다.\n인구학자: 그러나 지금까지의 저출산 대책이 충분한 효과를 거두지 못한 것도 사실입니다. 프랑스와 스웨덴의 사례를 보면, 단순한 경제적 지원이 아니라 사회 전체의 의식 변혁, 특히 남성의 육아 참여를 촉진하는 제도 설계가 성공의 열쇠였습니다. 일본 남성의 육아 휴직 취득률은 여전히 30% 정도에 머물고 있습니다.\n경제학자: 거시경제 관점에서 말씀드리자면, 저출산은 잠재 성장률을 낮추고 사회보장 제도의 지속가능성을 근본부터 위협합니다. 이민 정책을 포함한 인구 전략 수립이 급선무이며, 출생률 회복과 외국 인재 수용을 수레의 두 바퀴로 추진해야 합니다.',
  43
);

-- N1-24: 量子コンピュータの産業応用 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '量子コンピュータの産業応用',
  '記者：量子コンピュータの実用化について、現在の開発状況を教えていただけますか。\nCTO：量子コンピュータは、従来のコンピュータでは天文学的な時間を要する計算を、短時間で解くことが期待される革新的技術です。現在、我々は超伝導方式の量子ビットを用いて、一千量子ビットのプロセッサーを開発中です。ただし、量子ビットはノイズに極めて脆弱であり、エラー訂正の技術が実用化の最大のボトルネックとなっております。\n記者：具体的にはどのような産業分野での応用が見込まれますか。\nCTO：最も有望なのは、創薬シミュレーションです。タンパク質の折り畳み構造を量子力学的に正確にシミュレートすることで、新薬の候補物質の探索を劇的に加速できます。また、金融分野におけるポートフォリオ最適化や、物流の配送経路最適化、そして暗号技術への影響も重大です。現行のRSA暗号は量子コンピュータによって解読される可能性があり、量子耐性暗号への移行が国家安全保障上の喫緊の課題となっております。\n記者：実用化の時期についてはどのようにお考えですか。\nCTO：特定の応用分野では五年以内に実用レベルに達すると考えておりますが、汎用的な量子コンピュータの実現には、なお十年から二十年を要するでしょう。',
  'dialogue',
  'N1',
  ARRAY['記者', 'CTO'],
  '量子コンピュータ企業のCTOへのインタビュー',
  '[{"word":"量子ビット","reading":"りょうしビット","meaning_ko":"큐비트"},{"word":"超伝導","reading":"ちょうでんどう","meaning_ko":"초전도"},{"word":"創薬","reading":"そうやく","meaning_ko":"신약 개발"},{"word":"量子耐性暗号","reading":"りょうしたいせいあんごう","meaning_ko":"양자 내성 암호"},{"word":"喫緊","reading":"きっきん","meaning_ko":"시급한"}]'::jsonb,
  '기자: 양자 컴퓨터 실용화에 대해 현재 개발 상황을 알려주시겠습니까?\nCTO: 양자 컴퓨터는 기존 컴퓨터로는 천문학적 시간이 소요되는 계산을 단시간에 풀 수 있을 것으로 기대되는 혁신적 기술입니다. 현재 우리는 초전도 방식의 큐비트를 이용하여 1,000 큐비트 프로세서를 개발 중입니다. 다만 큐비트는 노이즈에 극히 취약하며, 에러 정정 기술이 실용화의 최대 병목이 되고 있습니다.\n기자: 구체적으로 어떤 산업 분야에서의 응용이 예상됩니까?\nCTO: 가장 유망한 것은 신약 개발 시뮬레이션입니다. 단백질의 접힘 구조를 양자역학적으로 정확하게 시뮬레이션하여 신약 후보 물질 탐색을 극적으로 가속할 수 있습니다. 또한 금융 분야의 포트폴리오 최적화, 물류의 배송 경로 최적화, 그리고 암호 기술에 대한 영향도 중대합니다. 현행 RSA 암호는 양자 컴퓨터에 의해 해독될 가능성이 있어 양자 내성 암호로의 전환이 국가 안보상 시급한 과제가 되고 있습니다.\n기자: 실용화 시기에 대해서는 어떻게 보십니까?\nCTO: 특정 응용 분야에서는 5년 이내에 실용 수준에 도달할 것으로 보지만, 범용 양자 컴퓨터 실현에는 아직 10년에서 20년이 소요될 것입니다.',
  44
);

-- N1-25: 日本語の敬語体系に関する講義 (monologue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '日本語の敬語体系に関する講義',
  '教授：本日は、日本語の敬語体系について、社会言語学の観点から考察いたします。二〇〇七年の文化審議会答申により、従来の三分類から五分類へと敬語の体系が改められました。すなわち、尊敬語、謙譲語Ⅰ、謙譲語Ⅱ（丁重語）、丁寧語、美化語の五つです。\nこの改訂の背景には、日本語使用の実態と従来の文法体系との乖離がありました。例えば、「参る」と「お持ちする」は、いずれも謙譲語とされてきましたが、前者は聞き手に対する丁重さを表すのに対し、後者は動作の受け手への敬意を表すという、質的に異なる機能を持っています。\nしかしながら、この五分類体系が日本語教育の現場に定着しているかというと、必ずしもそうとは言えません。母語話者でさえ、敬語の使い分けに困難を感じることが少なくないのに、非母語話者にとっては、さらに高いハードルとなっております。\n近年の傾向として興味深いのは、「させていただく」の過剰使用の問題です。本来は相手の許可を前提とした表現ですが、現在では単なる丁寧表現として汎用されており、いわゆる「マニュアル敬語」の象徴とも言えます。言語は社会の変化とともに変容するものであり、敬語もまたその例外ではありません。',
  'monologue',
  'N1',
  ARRAY['教授'],
  '大学院の社会言語学講義',
  '[{"word":"敬語体系","reading":"けいごたいけい","meaning_ko":"경어 체계"},{"word":"文化審議会","reading":"ぶんかしんぎかい","meaning_ko":"문화심의회"},{"word":"乖離","reading":"かいり","meaning_ko":"괴리"},{"word":"丁重語","reading":"ていちょうご","meaning_ko":"정중어"},{"word":"汎用","reading":"はんよう","meaning_ko":"범용"}]'::jsonb,
  '교수: 오늘은 일본어 경어 체계에 대해 사회언어학적 관점에서 고찰하겠습니다. 2007년 문화심의회 답신으로 종래의 3분류에서 5분류로 경어 체계가 개편되었습니다. 즉 존경어, 겸양어I, 겸양어II(정중어), 정녕어, 미화어의 5가지입니다.\n이 개정의 배경에는 일본어 사용 실태와 종래 문법 체계의 괴리가 있었습니다. 예를 들어 "마이루"와 "오모치스루"는 모두 겸양어로 분류되어 왔지만, 전자는 듣는 사람에 대한 정중함을 나타내는 반면 후자는 동작 대상에 대한 경의를 나타낸다는 질적으로 다른 기능을 갖고 있습니다.\n그러나 이 5분류 체계가 일본어 교육 현장에 정착했느냐 하면 반드시 그렇다고는 할 수 없습니다. 모국어 화자도 경어 구분에 어려움을 느끼는 경우가 적지 않은데, 비모국어 화자에게는 더 높은 장벽이 되고 있습니다.\n최근 경향으로 흥미로운 것은 "사세테이타다쿠"의 과잉 사용 문제입니다. 본래는 상대방의 허가를 전제로 한 표현이지만 현재는 단순한 정녕 표현으로 범용되고 있어 이른바 "매뉴얼 경어"의 상징이라 할 수 있습니다. 언어는 사회의 변화와 함께 변용되는 것이며, 경어 또한 그 예외가 아닙니다.',
  45
);

-- N1-26: 再生可能エネルギーの課題 (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '再生可能エネルギーの課題',
  '委員長：エネルギー基本計画の改定に向けた検討を始めます。二〇三五年の電源構成目標について、各委員のご意見をお聞かせください。\n工学教授：再生可能エネルギーの導入拡大は不可避ですが、系統安定性の課題を軽視すべきではありません。太陽光と風力は天候に左右される間欠性電源であり、大規模蓄電池や水素変換による貯蔵技術なくしては、基幹電源としての信頼性を確保できません。\n環境団体代表：しかし、蓄電池のコストは過去十年で八十パーセント以上低下しており、技術的障壁は急速に解消されつつあります。問題は技術ではなく、既存の電力システムに固執する制度と利害構造にあります。送配電網の広域運用と、電力市場の自由化をさらに推進すべきです。\n経産省課長：エネルギー安全保障の観点も重要です。化石燃料への依存度を下げることは、地政学的リスクの低減にも直結します。ただし、電力コストの急激な上昇は産業競争力を損ないかねず、現実的な移行経路を設計する必要があります。\n委員長：原子力の位置づけについてはいかがでしょうか。\n工学教授：次世代型の小型モジュール炉は、安全性と経済性を両立させる選択肢として検討に値しますが、使用済み核燃料の処分問題は依然として未解決であり、国民的合意なくして前進は困難です。',
  'meeting',
  'N1',
  ARRAY['委員長', '工学教授', '環境団体代表', '経産省課長'],
  'エネルギー基本計画改定に向けた審議会',
  '[{"word":"系統安定性","reading":"けいとうあんていせい","meaning_ko":"계통 안정성"},{"word":"間欠性","reading":"かんけつせい","meaning_ko":"간헐성"},{"word":"送配電網","reading":"そうはいでんもう","meaning_ko":"송배전망"},{"word":"小型モジュール炉","reading":"こがたモジュールろ","meaning_ko":"소형 모듈 원자로"},{"word":"使用済み核燃料","reading":"しようずみかくねんりょう","meaning_ko":"사용후 핵연료"}]'::jsonb,
  '위원장: 에너지 기본 계획 개정을 향한 검토를 시작합니다. 2035년 전원 구성 목표에 대해 각 위원의 의견을 듣겠습니다.\n공학 교수: 재생 가능 에너지 도입 확대는 불가피하지만 계통 안정성 과제를 경시해서는 안 됩니다. 태양광과 풍력은 날씨에 좌우되는 간헐성 전원이며, 대규모 축전지나 수소 변환에 의한 저장 기술 없이는 기간 전원으로서의 신뢰성을 확보할 수 없습니다.\n환경 단체 대표: 그러나 축전지 비용은 지난 10년간 80% 이상 하락했으며 기술적 장벽은 빠르게 해소되고 있습니다. 문제는 기술이 아니라 기존 전력 시스템에 집착하는 제도와 이해 구조에 있습니다. 송배전망의 광역 운용과 전력 시장 자유화를 더욱 추진해야 합니다.\n경산성 과장: 에너지 안보 관점도 중요합니다. 화석 연료 의존도를 낮추는 것은 지정학적 리스크 저감과도 직결됩니다. 다만 전력 비용의 급격한 상승은 산업 경쟁력을 해칠 수 있어 현실적인 전환 경로를 설계할 필요가 있습니다.\n위원장: 원자력의 위상에 대해서는 어떻습니까?\n공학 교수: 차세대형 소형 모듈 원자로는 안전성과 경제성을 양립시키는 선택지로서 검토할 가치가 있지만, 사용후 핵연료 처분 문제는 여전히 미해결이며 국민적 합의 없이는 진전이 어렵습니다.',
  46
);

-- N1-27: 哲学カフェでの自由意志論 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '哲学カフェでの自由意志論',
  '進行役：今日のテーマは「自由意志は存在するか」です。脳科学の進歩により、この古典的な哲学問題が、新たな局面を迎えています。\n脳科学者：ベンジャミン・リベットの実験以来、意識的な決定に先立って脳が活動を開始しているという知見が蓄積されています。最近のfMRI研究では、被験者が意識的に決定を下す最大十秒前に、その決定を脳活動のパターンから予測できるという報告もあります。これは、いわゆる「自由な選択」が、実は無意識の脳過程の結果に過ぎないことを示唆しています。\n哲学者：しかし、それは「自由意志」の定義の問題です。決定論的な因果連鎖の中に位置づけられるとしても、その決定が外部の強制ではなく、自己の欲求や信念に基づいてなされるのであれば、それは十分に「自由」と呼びうるのではないでしょうか。これがいわゆる両立論の立場です。\n脳科学者：興味深い指摘ですが、その「自己の欲求」自体が、遺伝と環境によって決定されているとすれば、「自己」とは何かという問いに行き着きます。\n哲学者：まさにそこが核心です。自由意志の問題は、究極的には自己同一性の問題、すなわち「私」とは何かという問いと不可分なのです。',
  'dialogue',
  'N1',
  ARRAY['進行役', '脳科学者', '哲学者'],
  '哲学カフェでの自由意志に関する対話',
  '[{"word":"自由意志","reading":"じゆういし","meaning_ko":"자유의지"},{"word":"決定論的","reading":"けっていろんてき","meaning_ko":"결정론적"},{"word":"因果連鎖","reading":"いんがれんさ","meaning_ko":"인과 연쇄"},{"word":"両立論","reading":"りょうりつろん","meaning_ko":"양립론"},{"word":"自己同一性","reading":"じこどういつせい","meaning_ko":"자기동일성"}]'::jsonb,
  '진행자: 오늘의 주제는 "자유의지는 존재하는가"입니다. 뇌과학의 진보로 이 고전적 철학 문제가 새로운 국면을 맞이하고 있습니다.\n뇌과학자: 벤자민 리벳의 실험 이래, 의식적 결정에 앞서 뇌가 활동을 개시한다는 지견이 축적되어 왔습니다. 최근 fMRI 연구에서는 피험자가 의식적으로 결정을 내리기 최대 10초 전에 그 결정을 뇌 활동 패턴에서 예측할 수 있다는 보고도 있습니다. 이는 이른바 "자유로운 선택"이 실은 무의식의 뇌 과정의 결과에 불과하다는 것을 시사합니다.\n철학자: 하지만 그것은 "자유의지"의 정의 문제입니다. 결정론적 인과 연쇄 속에 위치하더라도 그 결정이 외부의 강제가 아니라 자기의 욕구와 신념에 기반한 것이라면 그것은 충분히 "자유"라 부를 수 있지 않을까요? 이것이 이른바 양립론의 입장입니다.\n뇌과학자: 흥미로운 지적이지만, 그 "자기의 욕구" 자체가 유전과 환경에 의해 결정된 것이라면 "자기"란 무엇인가라는 물음에 이르게 됩니다.\n철학자: 바로 거기가 핵심입니다. 자유의지의 문제는 궁극적으로 자기동일성의 문제, 즉 "나"란 무엇인가라는 물음과 불가분입니다.',
  47
);

-- N1-28: 国際人道法の適用問題 (announcement)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '国際人道法の適用問題',
  '教授：本日の国際法特別講義では、現代の武力紛争における国際人道法の適用上の課題について考察いたします。\nジュネーヴ諸条約は、国家間の武力紛争を主として想定して策定されましたが、現代の紛争形態は、非国家武装集団の台頭、サイバー攻撃、そして自律型致死兵器システム、いわゆるLAWSの出現により、根本的に変容しております。\n第一の論点は、サイバー攻撃に対する国際人道法の適用可能性です。サイバー攻撃が物理的損害をもたらす場合には、武力行使に該当しうるとするタリン・マニュアルの見解がありますが、情報操作やインフラの機能妨害のような、物理的破壊を伴わない攻撃の位置づけは、なお議論の途上にあります。\n第二に、自律型致死兵器の問題です。人間の判断を介さずに殺傷行為を行う兵器は、区別原則と比例原則の遵守をいかに担保するのかという、根源的な問題を提起しています。「有意な人間の関与」を要件とすべきだとする立場と、技術的発展を過度に制約すべきではないとする立場が対立しており、国際的な規制の枠組みは未だ合意に至っておりません。',
  'announcement',
  'N1',
  ARRAY['教授'],
  '大学院の国際法特別講義',
  '[{"word":"国際人道法","reading":"こくさいじんどうほう","meaning_ko":"국제인도법"},{"word":"ジュネーヴ諸条約","reading":"ジュネーヴしょじょうやく","meaning_ko":"제네바 제조약"},{"word":"自律型致死兵器","reading":"じりつがたちしへいき","meaning_ko":"자율형 치사 무기"},{"word":"区別原則","reading":"くべつげんそく","meaning_ko":"구별 원칙"},{"word":"比例原則","reading":"ひれいげんそく","meaning_ko":"비례 원칙"}]'::jsonb,
  '교수: 오늘 국제법 특별 강의에서는 현대 무력 분쟁에서의 국제인도법 적용상 과제에 대해 고찰하겠습니다.\n제네바 제조약은 국가 간 무력 분쟁을 주로 상정하여 수립되었지만, 현대의 분쟁 형태는 비국가 무장 집단의 대두, 사이버 공격, 그리고 자율형 치사 무기 시스템, 이른바 LAWS의 출현으로 근본적으로 변용되고 있습니다.\n첫째 논점은 사이버 공격에 대한 국제인도법의 적용 가능성입니다. 사이버 공격이 물리적 손해를 초래하는 경우에는 무력 행사에 해당할 수 있다는 탈린 매뉴얼의 견해가 있지만, 정보 조작이나 인프라 기능 방해와 같은 물리적 파괴를 수반하지 않는 공격의 위상은 아직 논의 중입니다.\n둘째, 자율형 치사 무기의 문제입니다. 인간의 판단을 거치지 않고 살상 행위를 하는 무기는 구별 원칙과 비례 원칙의 준수를 어떻게 담보할 것인가라는 근원적 문제를 제기합니다. "유의미한 인간의 관여"를 요건으로 해야 한다는 입장과 기술적 발전을 과도하게 제약해서는 안 된다는 입장이 대립하고 있으며, 국제적 규제 틀은 아직 합의에 이르지 못했습니다.',
  48
);

-- N1-29: 都市計画と地域コミュニティ (meeting)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '都市計画と地域コミュニティ',
  '市長：本日は「コンパクトシティ構想と地域コミュニティの再生」について、有識者の皆様にご議論いただきたいと思います。\n都市計画教授：人口減少と高齢化が進む地方都市において、都市機能を中心部に集約するコンパクトシティの考え方は、行政サービスの効率化と住民の生活利便性向上の観点から合理的です。しかしながら、中心部への集約は、周辺部の衰退を加速させるという、いわば二律背反の問題を内包しています。\n住民代表：私たちの地区は、三十年前は商店街が賑わっておりましたが、郊外の大型店舗の進出と人口流出により、空き家率が四十パーセントを超えています。コンパクトシティの名のもとに切り捨てられるのではないかという不安があります。\n社会学者：重要なのは、「集約」と「ネットワーク」を車の両輪として捉えることです。中心部に機能を集約しつつも、周辺地域との交通ネットワークを維持し、デジタル技術を活用した遠隔サービスを充実させる。単なる撤退ではなく、機能の再配置として位置づけるべきです。\n市長：具体的には、オンデマンド型の公共交通や、遠隔医療の導入も含めて検討しているところです。\n都市計画教授：ウォーカブルな街づくりとカーボンニュートラルの両立も視野に入れるべきでしょう。歩いて暮らせる街は、環境負荷の低減にも直結します。',
  'meeting',
  'N1',
  ARRAY['市長', '都市計画教授', '住民代表', '社会学者'],
  'コンパクトシティ構想に関する有識者会議',
  '[{"word":"コンパクトシティ","reading":"コンパクトシティ","meaning_ko":"콤팩트 시티"},{"word":"二律背反","reading":"にりつはいはん","meaning_ko":"이율배반"},{"word":"空き家率","reading":"あきやりつ","meaning_ko":"빈집 비율"},{"word":"オンデマンド","reading":"オンデマンド","meaning_ko":"온디맨드"},{"word":"ウォーカブル","reading":"ウォーカブル","meaning_ko":"걸을 수 있는, 보행 친화적"}]'::jsonb,
  '시장: 오늘은 "콤팩트 시티 구상과 지역 커뮤니티 재생"에 대해 유식자 여러분께 논의를 부탁드리고자 합니다.\n도시계획 교수: 인구 감소와 고령화가 진행되는 지방 도시에서 도시 기능을 중심부에 집약하는 콤팩트 시티 개념은 행정 서비스 효율화와 주민 생활 편의성 향상 관점에서 합리적입니다. 그러나 중심부로의 집약은 주변부의 쇠퇴를 가속시킨다는, 이른바 이율배반의 문제를 내포하고 있습니다.\n주민 대표: 우리 지구는 30년 전에는 상점가가 활기찼지만, 교외 대형 매장의 진출과 인구 유출로 빈집 비율이 40%를 넘고 있습니다. 콤팩트 시티라는 이름 아래 버려지는 것은 아닌지 불안합니다.\n사회학자: 중요한 것은 "집약"과 "네트워크"를 수레의 두 바퀴로 파악하는 것입니다. 중심부에 기능을 집약하면서도 주변 지역과의 교통 네트워크를 유지하고 디지털 기술을 활용한 원격 서비스를 충실히 하는 것. 단순한 철수가 아니라 기능의 재배치로 자리매김해야 합니다.\n시장: 구체적으로는 온디맨드형 대중교통이나 원격 의료 도입도 포함하여 검토하고 있는 중입니다.\n도시계획 교수: 보행 친화적 도시 조성과 탄소 중립의 양립도 시야에 넣어야 할 것입니다. 걸어서 생활할 수 있는 도시는 환경 부하 저감에도 직결됩니다.',
  49
);

-- N1-30: 翻訳文学の可能性と限界 (dialogue)
INSERT INTO jlpt_listening_scripts (title, script, script_type, jlpt_level, speakers, situation, vocabulary_notes, translation_ko, sort_order)
VALUES (
  '翻訳文学の可能性と限界',
  '司会：本日は「翻訳は裏切りか、架橋か」というテーマで、お二人の翻訳家にお話を伺います。\n翻訳家A：イタリアの格言「翻訳者は裏切り者」という言葉が象徴するように、翻訳には本質的な不可能性が伴います。言語は単なるコミュニケーションの道具ではなく、文化そのものです。例えば、日本語の「木漏れ日」という言葉は、英語に直訳することが困難です。単に「sunlight filtering through leaves」と訳しても、そこに込められた侘び寂びの感性は伝わりません。\n翻訳家B：おっしゃる通りですが、私はむしろ、その不可能性にこそ翻訳の創造性があると考えています。村上春樹がフィッツジェラルドを翻訳する時、あるいはエドワード・サイデンステッカーが「雪国」を翻訳する時、そこには原文とは異なる、新たな文学的価値が生まれています。翻訳は損失であると同時に、付加でもあるのです。\n翻訳家A：近年の機械翻訳の進歩は、この議論に新たな次元を加えています。大規模言語モデルは、文脈を踏まえた翻訳において驚異的な精度を示していますが、文学的なニュアンスや、著者の文体的特徴の再現には、なお限界があります。\n翻訳家B：技術が進歩しても、異文化理解の深層に触れる翻訳は、人間の共感能力と文化的素養なくしては成し得ないと、私は信じています。翻訳とは、究極的には、他者を理解しようとする人間の営みの表れなのです。',
  'dialogue',
  'N1',
  ARRAY['司会', '翻訳家A', '翻訳家B'],
  '翻訳文学に関する対談イベント',
  '[{"word":"裏切り","reading":"うらぎり","meaning_ko":"배신"},{"word":"架橋","reading":"かきょう","meaning_ko":"가교, 다리 놓기"},{"word":"侘び寂び","reading":"わびさび","meaning_ko":"와비사비(소박한 멋)"},{"word":"大規模言語モデル","reading":"だいきぼげんごモデル","meaning_ko":"대규모 언어 모델"},{"word":"素養","reading":"そよう","meaning_ko":"소양"}]'::jsonb,
  '사회자: 오늘은 "번역은 배신인가, 가교인가"라는 주제로 두 분의 번역가에게 이야기를 듣겠습니다.\n번역가A: 이탈리아 격언 "번역자는 배신자"라는 말이 상징하듯 번역에는 본질적 불가능성이 수반됩니다. 언어는 단순한 커뮤니케이션 도구가 아니라 문화 그 자체입니다. 예를 들어 일본어의 "코모레비(나뭇잎 사이로 비치는 햇살)"라는 말은 영어로 직역하기 어렵습니다. 단순히 "sunlight filtering through leaves"라고 옮겨도 거기에 담긴 와비사비의 감성은 전달되지 않습니다.\n번역가B: 말씀대로이지만, 저는 오히려 그 불가능성에야말로 번역의 창조성이 있다고 봅니다. 무라카미 하루키가 피츠제럴드를 번역할 때, 혹은 에드워드 사이덴스태커가 "설국"을 번역할 때, 거기에는 원문과는 다른 새로운 문학적 가치가 태어납니다. 번역은 손실인 동시에 부가이기도 합니다.\n번역가A: 최근 기계 번역의 진보는 이 논의에 새로운 차원을 더하고 있습니다. 대규모 언어 모델은 문맥을 고려한 번역에서 경이적 정밀도를 보이지만, 문학적 뉘앙스나 저자의 문체적 특징 재현에는 아직 한계가 있습니다.\n번역가B: 기술이 진보해도 이문화 이해의 심층에 닿는 번역은 인간의 공감 능력과 문화적 소양 없이는 이루어질 수 없다고 저는 믿습니다. 번역이란 궁극적으로 타자를 이해하고자 하는 인간 활동의 표현인 것입니다.',
  50
);
